-- ############################################################################
-- 0005_squadrons_safety_comms.sql
-- ############################################################################

-- Wingman — squadrons, safety, calls, comms
-- Covers SPEC.md build steps 2, 4, 8 and 9. Run after 0004. Safe to re-run.

-- ---------------------------------------------------------------- profiles
-- Onboarding answers and identity. §7.1 collects study_time; §2 needs livery.
create table if not exists pilot_profiles (
  user_id       text primary key,
  callsign      text,
  livery        text        not null default 'dawn-patrol',
  variant_pin   text,                                   -- 'day' | 'night' | null = auto
  study_time    text,                                   -- 'early' | 'day' | 'evening' | 'late'
  invisible     boolean     not null default false,     -- §8.3, no penalty
  glow_enabled  boolean     not null default true,      -- §7.6 toggle
  is_staff      boolean     not null default false,     -- §7.1, badged real people only
  created_at    timestamptz not null default now()
);

-- --------------------------------------------------------------- squadrons
-- §7.1. Target 10-20 members. A squadron below 10 is 'forming' and says so.
create table if not exists squadrons (
  id           uuid        primary key default gen_random_uuid(),
  module_code  text        not null,
  livery       text        not null default 'dawn-patrol',   -- §2.12, group vote
  study_time   text,
  status       text        not null default 'forming',       -- 'forming' | 'active'
  created_at   timestamptz not null default now()
);

create table if not exists squadron_members (
  squadron_id uuid        not null references squadrons (id) on delete cascade,
  user_id     text        not null,
  marking     text        not null default 'solid',     -- §2.9 collision markings
  joined_at   timestamptz not null default now(),
  primary key (squadron_id, user_id)
);
create index if not exists squadron_members_user_idx on squadron_members (user_id);

-- ------------------------------------------------------------------ safety
-- §9. Must exist before any user-generated content ships.
create table if not exists blocks (
  user_id    text not null,
  blocked_id text not null,
  created_at timestamptz not null default now(),
  primary key (user_id, blocked_id),
  check (user_id <> blocked_id)
);

create table if not exists mutes (
  user_id   text not null,
  muted_id  text not null,
  created_at timestamptz not null default now(),
  primary key (user_id, muted_id)
);

create table if not exists reports (
  id          uuid        primary key default gen_random_uuid(),
  reporter_id text        not null,
  target_type text        not null,          -- 'message' | 'image' | 'user'
  target_id   text        not null,
  reason      text,
  chapter_id  text,
  channel_id  text,
  status      text        not null default 'open',   -- 'open' | 'actioned' | 'dismissed'
  created_at  timestamptz not null default now()
);
create index if not exists reports_open_idx on reports (status, created_at) where status = 'open';

-- ------------------------------------------------------------------- calls
-- §7.7. A Call must never expire unanswered without telling the caller.
create table if not exists calls (
  id           uuid        primary key default gen_random_uuid(),
  user_id      text        not null,
  chapter_id   text        not null,
  question_id  text,
  body         text,
  status       text        not null default 'open',   -- 'open' | 'answered' | 'surfaced'
  stage        smallint    not null default 0,        -- 0 none, 1 squadron, 2 widened, 3 told caller
  created_at   timestamptz not null default now()
);
create index if not exists calls_open_idx on calls (status, created_at) where status = 'open';

create table if not exists call_responses (
  id         uuid        primary key default gen_random_uuid(),
  call_id    uuid        not null references calls (id) on delete cascade,
  user_id    text        not null,
  body       text        not null,
  created_at timestamptz not null default now()
);

create table if not exists call_nudges (
  call_id    uuid        not null references calls (id) on delete cascade,
  user_id    text        not null,
  created_at timestamptz not null default now(),
  primary key (call_id, user_id)          -- §7.7: at most one nudge per member per call
);

-- ------------------------------------------------------------------- comms
-- §7.8. A continuous channel per module. Not a forum: no threads, no votes.
create table if not exists comms_messages (
  id            uuid        primary key default gen_random_uuid(),
  module_code   text        not null,
  squadron_id   uuid        references squadrons (id) on delete cascade,
  user_id       text        not null,
  body          text,
  image_url     text,
  chapter_id    text,                                  -- the chapter chip
  pinned_to     text,                                  -- pinned to this chapter
  is_system     boolean     not null default false,    -- §8.1 Wingman opener
  created_at    timestamptz not null default now(),
  edited_at     timestamptz
);
create index if not exists comms_channel_idx on comms_messages (module_code, created_at desc);
create index if not exists comms_pinned_idx on comms_messages (pinned_to) where pinned_to is not null;

create table if not exists comms_reactions (
  message_id uuid not null references comms_messages (id) on delete cascade,
  user_id    text not null,
  emoji      text not null,
  primary key (message_id, user_id, emoji)
);

-- -------------------------------------------------------------- formations
-- §7.9. Temporary, 2-6 people, one chapter. Nobody loses a Formation.
create table if not exists formations (
  id          uuid        primary key default gen_random_uuid(),
  chapter_id  text        not null,
  module_code text        not null,
  squadron_id uuid        references squadrons (id) on delete set null,
  started_at  timestamptz not null default now(),
  ended_at    timestamptz
);

create table if not exists formation_members (
  formation_id uuid not null references formations (id) on delete cascade,
  user_id      text not null,
  joined_at    timestamptz not null default now(),
  left_at      timestamptz,
  primary key (formation_id, user_id)
);

-- --------------------------------------------------------------------- RLS
do $$
declare t text;
begin
  foreach t in array array[
    'pilot_profiles','squadrons','squadron_members','blocks','mutes','reports',
    'calls','call_responses','call_nudges','comms_messages','comms_reactions',
    'formations','formation_members'
  ] loop
    execute format('alter table %I enable row level security', t);
    execute format('drop policy if exists %I on %I', t || '_open', t);
    execute format('create policy %I on %I for all using (true) with check (true)', t || '_open', t);
  end loop;
end $$;

-- ------------------------------------------------------- the fill ladder
-- §7.1. Descends the four rungs and stops at the first that reaches 10.
-- Never invents a member: if rung 4 still falls short the squadron stays
-- 'forming' and the UI says so plainly.
create or replace function assign_squadron(uid text, mod text, stime text)
returns uuid
language plpgsql
as $$
declare target uuid;
begin
  -- already placed for this module?
  select s.id into target
    from squadron_members m join squadrons s on s.id = m.squadron_id
   where m.user_id = uid and s.module_code = mod
   limit 1;
  if target is not null then return target; end if;

  -- rung 1: same module, same study-time, with room
  select s.id into target from squadrons s
   where s.module_code = mod and s.study_time is not distinct from stime
     and (select count(*) from squadron_members m where m.squadron_id = s.id) < 20
   order by (select count(*) from squadron_members m where m.squadron_id = s.id) desc
   limit 1;

  -- rung 2: same module, any study-time
  if target is null then
    select s.id into target from squadrons s
     where s.module_code = mod
       and (select count(*) from squadron_members m where m.squadron_id = s.id) < 20
     order by (select count(*) from squadron_members m where m.squadron_id = s.id) desc
     limit 1;
  end if;

  -- rung 3: any module, same study-time
  if target is null then
    select s.id into target from squadrons s
     where s.study_time is not distinct from stime
       and (select count(*) from squadron_members m where m.squadron_id = s.id) < 20
     order by (select count(*) from squadron_members m where m.squadron_id = s.id) desc
     limit 1;
  end if;

  -- rung 4: any squadron with room
  if target is null then
    select s.id into target from squadrons s
     where (select count(*) from squadron_members m where m.squadron_id = s.id) < 20
     order by (select count(*) from squadron_members m where m.squadron_id = s.id) desc
     limit 1;
  end if;

  -- none exists yet: open one. It will be 'forming' until it reaches 10.
  if target is null then
    insert into squadrons (module_code, study_time, livery)
    values (mod, stime, 'dawn-patrol')
    returning id into target;
  end if;

  insert into squadron_members (squadron_id, user_id)
  values (target, uid)
  on conflict do nothing;

  update squadrons
     set status = case
       when (select count(*) from squadron_members m where m.squadron_id = target) >= 10
       then 'active' else 'forming' end
   where id = target;

  return target;
end $$;

-- Squadron roster with everything the UI needs, minus anyone blocked either way.
create or replace function squadron_roster(uid text, sid uuid)
returns table (user_id text, callsign text, livery text, marking text, is_staff boolean, joined_at timestamptz)
language sql
stable
as $$
  select m.user_id, p.callsign, coalesce(p.livery, 'dawn-patrol'), m.marking,
         coalesce(p.is_staff, false), m.joined_at
    from squadron_members m
    left join pilot_profiles p on p.user_id = m.user_id
   where m.squadron_id = sid
     and m.user_id not in (select blocked_id from blocks where blocks.user_id = uid)
     and m.user_id not in (select b.user_id from blocks b where b.blocked_id = uid)
   order by m.joined_at;
$$;


-- ############################################################################
-- 0006_openers_rate_limits_moderation.sql
-- ############################################################################

-- §8.1 the app speaks first · §9 rate limits and the moderation queue
--
-- Everything here is idempotent and safe to re-run.

-- ---------------------------------------------------------------- openers
-- The quiet check and the insert have to happen together. Done in the client
-- they race: two people opening a quiet channel at the same moment both see it
-- as quiet and both post. This does it in one statement under one lock.
create or replace function post_opener_if_quiet(mod text, chap text, opener text)
returns uuid
language plpgsql
as $$
declare
  newest    timestamptz;
  human_wk  integer;
  new_id    uuid;
begin
  if opener is null or length(btrim(opener)) = 0 then return null; end if;

  -- Serialise per channel so concurrent callers queue rather than collide.
  perform pg_advisory_xact_lock(hashtext('opener:' || mod));

  select max(created_at) into newest
    from comms_messages where module_code = mod;

  -- Anything at all inside 48 hours means the channel is not quiet, including
  -- a previous opener -- which is what caps this at one per channel per 48h.
  if newest is not null and newest > now() - interval '48 hours' then
    return null;
  end if;

  select count(*) into human_wk
    from comms_messages
   where module_code = mod
     and is_system = false
     and created_at > now() - interval '7 days';

  if human_wk >= 20 then return null; end if;

  insert into comms_messages (module_code, user_id, body, chapter_id, is_system)
  values (mod, 'wingman', opener, chap, true)
  returning id into new_id;

  return new_id;
end $$;

-- ------------------------------------------------------------ rate limits
-- §9: composer posts, Calls and Formation invites are limited per user per
-- hour. Enforced here because a client-side guard is decoration.
create table if not exists rate_events (
  id         bigserial   primary key,
  user_id    text        not null,
  kind       text        not null,          -- 'message' | 'call' | 'formation'
  created_at timestamptz not null default now()
);
create index if not exists rate_events_lookup
  on rate_events (user_id, kind, created_at desc);

create or replace function rate_limit_take(uid text, k text, per_hour integer)
returns boolean
language plpgsql
as $$
declare used integer;
begin
  if uid is null then return false; end if;
  perform pg_advisory_xact_lock(hashtext('rate:' || uid || ':' || k));
  select count(*) into used
    from rate_events
   where user_id = uid and kind = k and created_at > now() - interval '1 hour';
  if used >= per_hour then return false; end if;
  insert into rate_events (user_id, kind) values (uid, k);
  return true;
end $$;

-- Housekeeping: nothing reads an event older than an hour.
create or replace function rate_events_prune()
returns void language sql as $$
  delete from rate_events where created_at < now() - interval '2 hours';
$$;

-- ------------------------------------------------------- moderation queue
-- §9: reports route to a human queue with the message, the chapter context and
-- the channel. Target first response within 24 hours, so the view carries the
-- age and the flag rather than making a person work it out.
create or replace view moderation_queue as
select
  r.id,
  r.created_at,
  r.reporter_id,
  r.target_type,
  r.target_id,
  r.reason,
  r.chapter_id,
  r.channel_id,
  r.status,
  now() - r.created_at                              as waiting,
  (now() - r.created_at) > interval '24 hours'      as past_target,
  m.body                                            as message_body,
  m.user_id                                         as message_author,
  m.module_code                                     as message_channel
from reports r
left join comms_messages m
  on r.target_type = 'message' and m.id::text = r.target_id
where r.status = 'open'
order by r.created_at;

do $$
begin
  execute 'alter table rate_events enable row level security';
  execute 'drop policy if exists rate_events_open on rate_events';
  execute 'create policy rate_events_open on rate_events for all using (true) with check (true)';
end $$;


-- ############################################################################
-- 0007_questions_squawks_teams.sql
-- ############################################################################

-- Phase 4 — §9.3.4 question-as-atom · §9.4.2 squawk · §9.4.3 teams ·
-- §9.4.4 standing · §9.4.5 notifications · §11 verified tier
--
-- Idempotent, and safe to re-run. Requires 0005.

-- ------------------------------------------------- §9.3.4 the atom is a question
-- A chat log is worthless a week later: the answer to "why is B wrong" scrolls
-- away. Marking a message as a question, and a reply as answering it, is what
-- lets settled knowledge separate from chatter.
alter table comms_messages add column if not exists is_question  boolean not null default false;
alter table comms_messages add column if not exists answers_id   uuid references comms_messages (id) on delete set null;
alter table comms_messages add column if not exists resolved_at  timestamptz;
-- §11 — a visually distinct verified tier, from day one.
alter table comms_messages add column if not exists is_verified  boolean not null default false;
alter table comms_messages add column if not exists verified_by  text;

create index if not exists comms_questions_idx
  on comms_messages (chapter_id, created_at desc) where is_question;
create index if not exists comms_answers_idx
  on comms_messages (answers_id) where answers_id is not null;

-- ------------------------------------------------------------ §9.4.2 squawk
-- Real aviation semantics: 7600 is radio failure ("I've read this three times
-- and I don't get it"), 7700 is emergency ("checkride Thursday and I'm lost").
--
-- The code sits on the question itself. Putting it on a parallel `calls` row
-- would mean two places to look and one of them usually empty.
alter table comms_messages add column if not exists squawk text;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'comms_squawk_code') then
    alter table comms_messages add constraint comms_squawk_code
      check (squawk is null or squawk in ('7600', '7700')) not valid;
  end if;
end $$;

-- §9.4.3 — "either now or scheduled (tonight 20:00)". 0005 gave formations a
-- started_at; a scheduled one needs a start in the future.
alter table formations add column if not exists starts_at timestamptz;

-- ------------------------------------------------------------- §9.4.3 teams
-- Self-formed, 3-6 people, persistent, their own chat. The strongest retention
-- mechanic in the plan: people come back for their group, not for the app.
create table if not exists teams (
  id          uuid        primary key default gen_random_uuid(),
  name        text        not null,
  module_code text,
  created_by  text        not null,
  created_at  timestamptz not null default now()
);

create table if not exists team_members (
  team_id   uuid        not null references teams (id) on delete cascade,
  user_id   text        not null,
  joined_at timestamptz not null default now(),
  primary key (team_id, user_id)
);
create index if not exists team_members_user_idx on team_members (user_id);

-- Team chat reuses comms_messages, scoped by team.
alter table comms_messages add column if not exists team_id uuid references teams (id) on delete cascade;
create index if not exists comms_team_idx on comms_messages (team_id, created_at desc) where team_id is not null;

-- ------------------------------------------- §9.4.4 standing · §11 status ladder
-- Standing is earned by helping, never by grinding chapters. The ladder is the
-- moderation model, not a gamification nicety: CFI unlocks marking an
-- explanation verified.
alter table pilot_profiles add column if not exists status  text    not null default 'student';
alter table pilot_profiles add column if not exists helped  integer not null default 0;
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'pilot_status_ladder') then
    alter table pilot_profiles add constraint pilot_status_ladder
      check (status in ('student', 'private', 'instrument', 'commercial', 'cfi')) not valid;
  end if;
end $$;

-- §9.4.5 — replies to you, your teams, and answers to your questions. Nothing
-- else, unless you opt in.
alter table pilot_profiles add column if not exists notify text not null default 'default';

-- ------------------------------------------------------ §10 per-module rollout
-- "Don't ship a social surface where it's empty. Turn it on per module once
-- there's content." A module with no social surface is fine; one with a visibly
-- abandoned surface is not.
create table if not exists module_social (
  module_code text primary key,
  enabled     boolean not null default false,
  enabled_at  timestamptz
);

do $$
declare t text;
begin
  foreach t in array array['teams', 'team_members', 'module_social'] loop
    execute format('alter table %I enable row level security', t);
    execute format('drop policy if exists %I on %I', t || '_open', t);
    execute format('create policy %I on %I for all using (true) with check (true)', t || '_open', t);
  end loop;
end $$;

-- ------------------------------------------------------------- open squawks
-- §9.4 band 2: unanswered questions from every chapter, with context attached.
-- This is the room's purpose and the reason it is never empty.
create or replace view open_squawks as
select
  q.id,
  q.user_id,
  q.body,
  q.chapter_id,
  q.module_code,
  q.created_at,
  q.squawk,
  now() - q.created_at as waiting
from comms_messages q
where q.is_question
  and q.resolved_at is null
  and not exists (select 1 from comms_messages a where a.answers_id = q.id)
order by q.created_at;

-- Marking an answer bumps the helper's standing and resolves the question.
create or replace function mark_answer(answer_id uuid, question_id uuid, marker text)
returns boolean
language plpgsql
as $$
declare asker text; helper text;
begin
  select user_id into asker  from comms_messages where id = question_id and is_question;
  select user_id into helper from comms_messages where id = answer_id;
  if asker is null or helper is null then return false; end if;
  -- Only the person who asked decides what answered it.
  if marker is distinct from asker then return false; end if;

  update comms_messages set answers_id = question_id where id = answer_id;
  update comms_messages set resolved_at = now() where id = question_id;
  -- §9.4.4 — count helping, never grinding.
  if helper is distinct from asker then
    update pilot_profiles set helped = helped + 1 where user_id = helper;
  end if;
  return true;
end $$;


-- ############################################################################
-- 0008_lesson_surface.sql
-- ############################################################################

-- Wingman — the lesson surface: notes, threads and replies
--
-- Run after 0007. Safe to re-run. Additive only: it creates three tables and
-- two functions and touches nothing that exists.
--
-- RUN against the live project, and the client is now pointed at it. Verified
-- on 2026-08-31 by connecting and looking, not inferred: all three tables
-- exist, both functions are in pg_proc with matching signatures, and the
-- lesson_threads_anchor_whole CHECK is present.
--
-- This header said "NOT YET RUN" for a while after it had been. That is the
-- same failure the squadron.js comments carry, and the reason nothing in this
-- project should trust a comment about deployment state: `npm run check:backend`
-- and `npm run check:threads` are the source of truth. Run them.
--
-- THE ONE RULE THIS SCHEMA ENFORCES, because it cannot be enforced by
-- remembering it: a thread with a lesson carries the moment it is anchored to,
-- and a thread without one carries neither. That asymmetry is the whole reason
-- a module post can never appear under a video — there is nothing to attach it
-- to — and it is a CHECK constraint here rather than a convention in a comment.

-- ------------------------------------------------------------------- notes
-- Private, and never returned to anyone else. RLS is open like every other
-- table in this project (the client is anonymous from Postgres' point of view
-- and access control happens in the app), so the app must always filter by
-- author_id. There is no second reader of this table.
--
-- body may be EMPTY. A bare pin is a valid note and is the point of the
-- feature: the real cost of taking notes during a lesson is not typing speed,
-- it is that writing makes you miss the next thing.
create table if not exists lesson_notes (
  id         text        primary key,
  user_id    text        not null,
  lesson_id  text        not null,
  t          integer     not null check (t >= 0),
  body       text        not null default '',
  created_at timestamptz not null default now()
);
create index if not exists lesson_notes_user_idx on lesson_notes (user_id, lesson_id, t);

alter table lesson_notes enable row level security;
-- Dropped first so this file can be run twice, the same as the rest of the
-- series (0009 carries the argument and check:migrations holds it).
--
-- AND THE SEQUENCE MATTERS HERE, which it does nowhere else: 0009 REPLACES
-- this open policy with a no-bulk-read one, because `using (true)` on a table
-- of private notes said "anyone may read anyone's notes". Run in order that is
-- closed again four files later. Running 0008 ALONE against an already
-- migrated database re-opens it — so run the series, or the bundle.
drop policy if exists lesson_notes_open on lesson_notes;
create policy lesson_notes_open on lesson_notes for all using (true) with check (true);

-- ----------------------------------------------------------------- threads
-- ONE TABLE, TWO QUERIES. The comment under the video and the thread in People
-- are the same row: the lesson asks what is on this lesson, People asks what is
-- in this module. Nothing copies, nothing syncs, nothing can drift.
--
-- Do not add a second table and a job that keeps them matching. That is the
-- version that ends up showing different reply counts in two places, and it is
-- the obvious implementation, which is why it is said here as well as in the
-- source.
create table if not exists lesson_threads (
  id         text        primary key,
  module_id  text        not null,
  lesson_id  text,                      -- null = a module post, People only
  t          integer,                   -- null iff lesson_id is null
  body       text        not null check (length(btrim(body)) > 0),
  author_id  text        not null,
  created_at timestamptz not null default now(),
  -- Anchored or not, never half. A row with a lesson and no moment would
  -- appear under a video with nowhere to sit on the bar; a row with a moment
  -- and no lesson would be a mark on a bar that belongs to no video.
  constraint lesson_threads_anchor_whole
    check ((lesson_id is null and t is null) or (lesson_id is not null and t is not null and t >= 0))
);
create index if not exists lesson_threads_module_idx on lesson_threads (module_id, created_at desc);
create index if not exists lesson_threads_lesson_idx on lesson_threads (module_id, lesson_id, t);

alter table lesson_threads enable row level security;
drop policy if exists lesson_threads_open on lesson_threads;
create policy lesson_threads_open on lesson_threads for all using (true) with check (true);

-- ----------------------------------------------------------------- replies
-- A reply belongs to the thread, never to a moment. It gets no timestamp of
-- its own and no mark on the bar — a good discussion would otherwise put
-- twelve marks on one spot and the bar would stop meaning anything.
--
-- Flat, not nested. parent_id is deliberately absent: a tree earns its keep at
-- ten thousand comments, not at forty, and adding it later is a column rather
-- than a migration of the rows.
create table if not exists lesson_replies (
  id         text        primary key,
  thread_id  text        not null references lesson_threads (id) on delete cascade,
  body       text        not null check (length(btrim(body)) > 0),
  author_id  text        not null,
  created_at timestamptz not null default now()
);
create index if not exists lesson_replies_thread_idx on lesson_replies (thread_id, created_at);

alter table lesson_replies enable row level security;
drop policy if exists lesson_replies_open on lesson_replies;
create policy lesson_replies_open on lesson_replies for all using (true) with check (true);

-- ------------------------------------------------------------- the two reads
-- Under the video: anchored threads on this lesson, in MOMENT order. Not
-- newest-first — ordering by moment is what makes scrolling the comment list
-- the same gesture as scrubbing the video, and it matches the bar above it.
create or replace function lesson_comments(p_module text, p_lesson text)
returns table (
  id text, module_id text, lesson_id text, t integer,
  body text, author_id text, created_at timestamptz, reply_count bigint
)
language sql
stable
as $$
  select th.id, th.module_id, th.lesson_id, th.t, th.body, th.author_id, th.created_at,
         count(r.id) as reply_count
  from lesson_threads th
  left join lesson_replies r on r.thread_id = th.id
  where th.module_id = p_module
    and th.lesson_id = p_lesson
  group by th.id
  order by th.t asc;
$$;

-- People: every thread in the module, with what a badge has to be measured
-- against. last_activity_by is the last thing that happened here that WASN'T
-- you, and it is null when the only activity is your own.
--
-- That second half is the one that is easy to miss. Measured against plain
-- last activity, a question you asked and nobody has answered badges itself —
-- you get a dot for your own post, forever, on every thread you start. That is
-- how People turns permanently red, which is the failure the module chat room
-- was rejected for.
create or replace function module_threads(p_module text, p_me text)
returns table (
  id text, lesson_id text, t integer, body text, author_id text,
  created_at timestamptz, reply_count bigint,
  in_it boolean, waiting boolean, last_activity_by timestamptz
)
language sql
stable
as $$
  select th.id, th.lesson_id, th.t, th.body, th.author_id, th.created_at,
         count(r.id)                                                     as reply_count,
         -- coalesce, because bool_or over an all-NULL set is NULL: a thread
         -- with no replies yields `th.author_id = p_me or NULL`, which is NULL
         -- rather than false for everyone else's unanswered questions.
         coalesce(bool_or(th.author_id = p_me or r.author_id = p_me), false) as in_it,
         count(r.id) = 0                                                  as waiting,
         -- greatest() ignores NULLs and returns NULL only when every argument
         -- is NULL, which is exactly the "the only activity here is yours"
         -- case the badge rule needs.
         greatest(
           case when th.author_id <> p_me then th.created_at end,
           max(r.created_at) filter (where r.author_id <> p_me)
         )                                                                as last_activity_by
  from lesson_threads th
  left join lesson_replies r on r.thread_id = th.id
  where th.module_id = p_module
  group by th.id
  -- In it, then waiting for an answer, then the rest. Newest-first is the
  -- wrong default here: the middle band is what turns eleven people into
  -- eleven people helping each other rather than everyone posting into silence.
  order by
    case when coalesce(bool_or(th.author_id = p_me or r.author_id = p_me), false) then 0
         when count(r.id) = 0 then 1
         else 2 end,
    greatest(th.created_at, coalesce(max(r.created_at), th.created_at)) desc;
$$;


-- ############################################################################
-- 0009_right_seat_boundary.sql
-- ############################################################################

-- Wingman — §7, the right seat's boundary, on the server
--
-- Run after 0008. Safe to re-run. Additive only: it creates two functions and
-- one policy and alters no table.
--
-- ===========================================================================
-- READ THIS BEFORE WRITING A POLICY THAT MENTIONS auth.uid()
-- ===========================================================================
-- It will not work, and it will not fail loudly either — it will silently deny
-- every row and the room will look empty rather than broken.
--
-- Clerk owns identity in this project. The browser talks to PostgREST with the
-- ANON key and nothing else: there is no Supabase session, no JWT carrying a
-- user, and auth.uid() is NULL on every single request. That is why every
-- table in this codebase carries `using (true)` and why user_id columns hold a
-- Clerk id as text rather than a Supabase uid. It is a deliberate
-- architecture, written down in CLAUDE.md, not an oversight to be corrected in
-- passing by a migration.
--
-- WHAT THIS MIGRATION THEREFORE IS. §7 says: only people you share a squadron
-- with may ever appear in the right seat. Until this file that sentence lived
-- only in JavaScript, in roomModel.rightSeatCandidates, which means it held
-- exactly as long as every present and future caller remembered to route
-- through that function — and the room had ALREADY forgotten once, handing the
-- raw presence list straight to the view.
--
-- So the boundary is expressed here as a function that cannot return a
-- stranger, whatever the caller asks for. The client calls right_seat(me)
-- instead of selecting presence and filtering afterwards. A caller that passes
-- somebody else's id gets that person's squadron-mates rather than their own,
-- which is a lateral move and not an escalation: presence is already readable
-- to the anon key, as it has to be for the online rail to work at all.
--
-- WHAT THIS IS NOT: authentication. It is one statement of the rule, in the
-- place the rule is applied, so a second caller cannot quietly disagree with
-- the first. Turning it into enforcement needs Clerk JWTs accepted by Supabase
-- so that auth.jwt()->>'sub' is trustworthy; at that point the `p_me`
-- parameter is deleted, every function below reads the subject from the token,
-- and the open policies are narrowed. That is a project, not a line, and it is
-- the same project for all thirty-odd tables at once — doing it for this one
-- would leave the codebase with two auth models, which is worse than one
-- honest one.
-- ===========================================================================

-- --------------------------------------------------------------- §7 helper
-- The squadrons an account is actually in. Its own function because three
-- things below need it and a copied subquery is a rule with three owners.
create or replace function my_squadron_ids(p_me text)
returns setof uuid
language sql
stable
as $$
  select squadron_id from squadron_members where user_id = p_me;
$$;

-- ------------------------------------------------------------ §7 right seat
-- Who is in the room right now that p_me shares a squadron with, minus anyone
-- either of them has blocked.
--
-- The blocks check runs BOTH WAYS on purpose. Blocking is not a mute: if A
-- blocks B then B must not be offered A's seat either, or the block is
-- trivially defeated by the blocked person doing the inviting.
create or replace function right_seat(p_me text, p_since interval default '90 seconds')
returns table (
  user_id      text,
  squadron_id  uuid,
  module_code  text,
  chapter_id   text,
  last_seen    timestamptz
)
language sql
stable
as $$
  select distinct on (p.user_id)
         p.user_id,
         sm.squadron_id,
         p.module_code,
         p.chapter_id,
         p.last_seen
  from presence p
  join squadron_members sm
    on sm.user_id = p.user_id
   and sm.squadron_id in (select my_squadron_ids(p_me))
  where p.user_id <> p_me
    and p.last_seen >= now() - p_since
    and not exists (
      select 1 from blocks b
      where (b.user_id = p_me and b.blocked_id = p.user_id)
         or (b.user_id = p.user_id and b.blocked_id = p_me)
    )
  order by p.user_id, p.last_seen desc;
$$;

-- --------------------------------------------------------- the one narrowing
-- lesson_notes is the single table in this schema with exactly one legitimate
-- reader — the person who wrote the note. Every other table here is shared by
-- design, so `using (true)` is an accurate description of them. This one it
-- was never accurate about: it said "anyone may read anyone's private notes",
-- and the only thing standing between that and the notes was the app
-- remembering to filter by author_id on every query it will ever write.
--
-- It cannot be narrowed to the AUTHOR without a JWT, per the header. It can be
-- narrowed to "not readable in bulk at all", which is a real reduction: a
-- policy of `false` for select means notes cannot be enumerated over REST by
-- anyone, and the app reads them where it always has — through user_progress,
-- which is where the client actually keeps them today.
--
-- Writes stay open so the table remains usable the moment a JWT exists and the
-- notes move here properly.
-- AND EVERY ONE OF THESE IS DROPPED FIRST, SO THE FILE CAN BE RUN TWICE.
-- Supabase's preview CI runs the whole series against a branch database, and a
-- run that died somewhere after this point left these policies standing while
-- the history table never recorded 0009 as applied. Every run after that
-- reached the first `create policy` below and stopped:
--
--   ERROR: policy "lesson_notes_no_bulk_read" for table "lesson_notes"
--          already exists (SQLSTATE 42710)   At statement: 3
--
-- The header above has said "safe to re-run" since the day this file was
-- written. Until 2026-10-13 that was not true of its policies, and the check
-- that would have caught it did not exist: `npm run check:migrations` now
-- holds every `create policy` in the series, in whichever of the three idioms
-- this repo already uses.
--
-- Dropping rather than swallowing a duplicate_object is the deliberate half. A
-- re-run converges on the definitions BELOW instead of leaving whatever a
-- half-finished run happened to leave — and these four ARE the boundary this
-- file exists to draw, so "it was already there" is not good enough.
drop policy if exists lesson_notes_open         on lesson_notes;
drop policy if exists lesson_notes_no_bulk_read on lesson_notes;
drop policy if exists lesson_notes_write        on lesson_notes;
drop policy if exists lesson_notes_update       on lesson_notes;
drop policy if exists lesson_notes_delete       on lesson_notes;

create policy lesson_notes_no_bulk_read on lesson_notes
  for select using (false);
create policy lesson_notes_write on lesson_notes
  for insert with check (true);
create policy lesson_notes_update on lesson_notes
  for update using (true) with check (true);
create policy lesson_notes_delete on lesson_notes
  for delete using (true);


-- ############################################################################
-- 0010_thread_titles_and_answers.sql
-- ############################################################################

-- Wingman — thread titles, best answers, and answer votes
--
-- Run after 0009. Safe to re-run. Additive only: three columns and one table.
-- Nothing existing changes shape, so a client that has not been updated keeps
-- working against these tables exactly as before.
--
-- WHY THESE THREE AND NOT MORE. The Ready Room rebuild turns a module's
-- discussion into a question feed: a list of titled questions, each with
-- answers, one of which the asker can mark as the one that worked. Those are
-- the only three facts the schema could not already hold.
--
-- ------------------------------------------------------------------- title
-- A thread created IN the Ready Room is a question and needs a title, because
-- a feed of untitled paragraphs cannot be scanned.
--
-- A thread MIRRORED from a lesson comment has no title and must not be given
-- one: adding a title field to the lesson comment box would put a form in
-- front of a casual remark, and casual commenting on a lesson has to stay
-- frictionless. Those rows keep title NULL and the client shows the comment's
-- first line instead, with a FROM LESSON tag that both explains the shorter
-- title and links back.
--
-- So the column is NULLABLE on purpose, and null means "this came from a
-- lesson". That is the same asymmetry 0008 already encodes with lesson_id and
-- t, and it is why there is no CHECK forcing a title: half these rows must
-- never have one.
alter table lesson_threads add column if not exists title text;

-- ------------------------------------------------------------- best answer
-- The asker's mark, not a vote count. "Which answer actually worked" is a
-- judgement only the person who asked can make, and it is one per thread,
-- which is why it lives here as a single column rather than as a flag on the
-- replies where two rows could both claim it.
--
-- ON DELETE SET NULL: deleting the chosen answer must not delete the question.
alter table lesson_threads
  add column if not exists best_reply_id text
  references lesson_replies (id) on delete set null;

-- ------------------------------------------------------------------- votes
-- One row per person per answer, so the primary key IS the "one vote each"
-- rule. A count column would need a second write to stay true and would drift;
-- this cannot.
--
-- No value column. post_votes carries value +1/-1 for the older social layer,
-- and this deliberately does not: an answer can be endorsed, not buried. A
-- downvote on somebody's attempt to help is the thing that stops people
-- answering.
create table if not exists lesson_reply_votes (
  reply_id   text        not null references lesson_replies (id) on delete cascade,
  user_id    text        not null,
  created_at timestamptz not null default now(),
  primary key (reply_id, user_id)
);
create index if not exists lesson_reply_votes_reply_idx on lesson_reply_votes (reply_id);

alter table lesson_reply_votes enable row level security;
-- Open, like every other table in this project: the client is anonymous from
-- Postgres' point of view and access control happens in the app. See 0009's
-- header before writing a policy that mentions auth.uid() here.
-- Dropped first so this file can be run twice (0009 carries the argument).
drop policy if exists lesson_reply_votes_open on lesson_reply_votes;
create policy lesson_reply_votes_open on lesson_reply_votes
  for all using (true) with check (true);


-- ############################################################################
-- 0011_discovery.sql
-- ############################################################################

-- Wingman — discovery: how a student who knows nobody reaches somebody
--
-- Run after 0010. Safe to re-run. Adds columns to two existing tables, creates
-- two tables and a set of functions. Alters no existing column and drops
-- nothing.
--
-- ===========================================================================
-- THE BOUNDARY LIVES HERE, NOT IN THE CLIENT
-- ===========================================================================
-- Read the header of 0009 first; the same architecture applies and for the
-- same reason. auth.uid() is NULL on every request, every table carries
-- `using (true)`, and the browser holds the anon key. So a rule expressed only
-- as "the UI does not call that endpoint" is not a rule — PostgREST will serve
-- the table to anyone who asks.
--
-- The rule this file has to hold is §3 of the brief: a person may appear in
-- search only if the searcher already shares a squadron with them, or that
-- person has answered in a module the searcher studies. Some of these students
-- are under 18. An app where an adult can search a minor by name is a grooming
-- vector, and "the client happens not to send that query" is not a defence.
--
-- So people_search is a function that cannot return a stranger whatever it is
-- asked for. It is not authentication — passing another user's id returns
-- THEIR orbit, which is a lateral move, the same trade 0009 documents — it is
-- one statement of the rule in the place the rule applies, so a second caller
-- cannot quietly disagree with the first.
-- ===========================================================================

-- ------------------------------------------------------------- 1 · squadrons
-- The table from 0005 has no name, which is why every squadron in the client
-- is currently identified by its module code. Discovery needs a room to be a
-- named thing you can be told about.
alter table squadrons add column if not exists name         text;
alter table squadrons add column if not exists blurb        text;
alter table squadrons add column if not exists owner_id     text;
alter table squadrons add column if not exists exam_window  text;

-- open        anyone may join immediately
-- request     joining creates a row in squadron_join_requests
-- invite_only the default, and the only way in is a link or an invite
alter table squadrons add column if not exists join_policy  text not null default 'invite_only';
do $$ begin
  alter table squadrons add constraint squadrons_join_policy_known
    check (join_policy in ('open', 'request', 'invite_only'));
exception when duplicate_object then null; end $$;

-- PER SQUADRON, NOT GLOBAL. 32 is a full class of 28 plus a repeat student, a
-- late joiner and an instructor. Open rooms are left NULL — uncapped — because
-- a cohort room that fills up locks out exactly the newcomers it exists for.
-- The brief flags this number as the one open decision; it is a default on a
-- column, so changing it is one statement rather than a migration of logic.
alter table squadrons add column if not exists member_cap   integer default 32;

-- The shareable link. One per squadron, regenerated by revoking.
alter table squadrons add column if not exists invite_token       text;
alter table squadrons add column if not exists invite_expires_at  timestamptz;
alter table squadrons add column if not exists invite_revoked_at  timestamptz;
create unique index if not exists squadrons_invite_token_idx
  on squadrons (lower(invite_token)) where invite_token is not null;

-- ------------------------------------------------------------- 2 · profiles
-- SET BY THE STUDENT, NEVER INFERRED. The brief is explicit: exam window and
-- active window are things a person says about themselves. Current module,
-- answer habit and study rhythm are derived below and deliberately not stored,
-- so they cannot drift from the behaviour they describe.
alter table pilot_profiles add column if not exists exam_window   text;
alter table pilot_profiles add column if not exists active_window text;   -- morning|afternoon|evening|night
alter table pilot_profiles add column if not exists timezone      text;
-- The opt-out. Removes a student from people-search entirely and leaves every
-- squadron they are already in untouched.
alter table pilot_profiles add column if not exists discoverable  boolean not null default true;

-- --------------------------------------------------------- 3 · new tables
-- A request is not a join. §8: nothing auto-joins anyone to anything, and an
-- invite cannot force-add — it is a request the invited person accepts.
create table if not exists squadron_join_requests (
  squadron_id uuid        not null references squadrons (id) on delete cascade,
  user_id     text        not null,
  state       text        not null default 'pending' check (state in ('pending','accepted','declined')),
  created_at  timestamptz not null default now(),
  decided_at  timestamptz,
  primary key (squadron_id, user_id)
);
create index if not exists squadron_join_requests_user_idx on squadron_join_requests (user_id, state);

-- Person-to-person, as distinct from the squadron's shareable link above.
-- "Invite to a squadron" on a profile writes one of these.
create table if not exists squadron_invites (
  id           uuid        primary key default gen_random_uuid(),
  squadron_id  uuid        not null references squadrons (id) on delete cascade,
  inviter_id   text        not null,
  invitee_id   text        not null,
  state        text        not null default 'pending' check (state in ('pending','accepted','declined','revoked')),
  created_at   timestamptz not null default now(),
  unique (squadron_id, invitee_id)
);
create index if not exists squadron_invites_invitee_idx on squadron_invites (invitee_id, state);

-- NO user_blocks TABLE. The brief lists one; `blocks` already exists from 0005
-- with exactly that shape and is already read by right_seat in 0009. A second
-- block list would be two owners of one fact, and the failure mode is the bad
-- one: a person blocked in one table and not the other is visible on whichever
-- surface reads the emptier list.

do $$
declare t text;
begin
  foreach t in array array['squadron_join_requests', 'squadron_invites'] loop
    execute format('alter table %I enable row level security', t);
    execute format('drop policy if exists %I on %I', t || '_open', t);
    execute format('create policy %I on %I for all using (true) with check (true)', t || '_open', t);
  end loop;
end $$;

-- --------------------------------------------------------- 4 · the orbit
-- Modules an account actually studies. There is no enrollments table in this
-- database — CLAUDE.md says there is, and it is wrong — so this is built from
-- the two signals that do exist: a chapter you completed, or a thread you
-- posted. Both are activity in the module rather than a claim about it.
create or replace function my_modules(p_me text)
returns setof text
language sql
stable
as $$
  select module_code from chapter_completions where user_id = p_me
  union
  select module_id   from lesson_threads      where author_id = p_me;
$$;

-- THE ORBIT ITSELF, and every people-facing function below goes through it.
-- True when p_me may see p_them at all: a shared squadron, or p_them has
-- written in a module p_me studies.
create or replace function in_my_orbit(p_me text, p_them text)
returns boolean
language sql
stable
as $$
  select p_me is not null and p_them is not null and p_me <> p_them and (
    exists (
      select 1 from squadron_members a
      join squadron_members b on b.squadron_id = a.squadron_id
      where a.user_id = p_me and b.user_id = p_them
    )
    or exists (
      select 1 from lesson_threads t
      where t.author_id = p_them and t.module_id in (select my_modules(p_me))
    )
    or exists (
      select 1 from lesson_replies r
      join lesson_threads t on t.id = r.thread_id
      where r.author_id = p_them and t.module_id in (select my_modules(p_me))
    )
  );
$$;

-- ------------------------------------------------------ 5 · people search
-- The only way the client is allowed to look a person up. Scoped by orbit,
-- filtered by the opt-out, and blocked BOTH WAYS — blocking is symmetric and
-- total, so neither party appears to the other, on any surface.
create or replace function people_search(p_me text, p_q text)
returns table (user_id text, callsign text, module_code text, shares_squadron boolean)
language sql
stable
as $$
  select
    p.user_id,
    p.callsign,
    (select c.module_code from chapter_completions c
      where c.user_id = p.user_id order by c.completed_at desc limit 1) as module_code,
    exists (
      select 1 from squadron_members a
      join squadron_members b on b.squadron_id = a.squadron_id
      where a.user_id = p_me and b.user_id = p.user_id
    ) as shares_squadron
  from pilot_profiles p
  where p.discoverable
    and in_my_orbit(p_me, p.user_id)
    and not exists (select 1 from blocks b
                    where (b.user_id = p_me and b.blocked_id = p.user_id)
                       or (b.user_id = p.user_id and b.blocked_id = p_me))
    and coalesce(btrim(p_q), '') <> ''
    and p.callsign ilike '%' || btrim(p_q) || '%'
  order by shares_squadron desc, p.callsign
  limit 20;
$$;

-- --------------------------------------------------------- 6 · capacity
-- Headcount is its own function because three things below need it, and a
-- copied count(*) is a rule with three owners.
create or replace function squadron_headcount(p_squadron uuid)
returns integer
language sql
stable
as $$
  select count(*)::int from squadron_members where squadron_id = p_squadron;
$$;

-- Full only when a cap is actually set. NULL member_cap means uncapped, which
-- is what open cohort rooms use.
create or replace function squadron_is_full(p_squadron uuid)
returns boolean
language sql
stable
as $$
  select s.member_cap is not null and squadron_headcount(s.id) >= s.member_cap
  from squadrons s where s.id = p_squadron;
$$;

-- ------------------------------------------------------- 7 · discovery list
-- Rooms p_me could join, SORTED BY ACTIVITY RATHER THAN SIZE — a busy room of
-- nine beats a dead room of forty. `known` is the social-proof line: people
-- already in there that p_me has studied alongside.
--
-- Capacity is returned as a headcount and a boolean, never as a fraction. §2:
-- a group of eight is a squadron; rendered as "8 of 32" it becomes a
-- half-empty one, and that framing is what kills small groups.
create or replace function discover_squadrons(p_me text, p_filter text default 'all')
returns table (
  id uuid, name text, blurb text, module_code text, exam_window text,
  join_policy text, members integer, active_week integer, is_full boolean,
  known_ids text[], already_in boolean, requested boolean
)
language sql
stable
as $$
  with mine as (select squadron_id from squadron_members where user_id = p_me),
  active as (
    select m.squadron_id, count(distinct pr.user_id)::int as n
    from squadron_members m
    left join presence pr
      on pr.user_id = m.user_id and pr.last_seen > now() - interval '7 days'
    group by m.squadron_id
  )
  select
    s.id, s.name, s.blurb, s.module_code, s.exam_window, s.join_policy,
    squadron_headcount(s.id) as members,
    coalesce(a.n, 0) as active_week,
    coalesce(squadron_is_full(s.id), false) as is_full,
    coalesce((
      select array_agg(sm.user_id)
      from squadron_members sm
      where sm.squadron_id = s.id and in_my_orbit(p_me, sm.user_id)
    ), '{}') as known_ids,
    s.id in (select squadron_id from mine) as already_in,
    exists (select 1 from squadron_join_requests r
            where r.squadron_id = s.id and r.user_id = p_me and r.state = 'pending') as requested
  from squadrons s
  left join active a on a.squadron_id = s.id
  where s.join_policy in ('open', 'request')
    and (p_filter <> 'yours' or s.module_code in (select my_modules(p_me)))
    and (p_filter <> 'exam'  or s.exam_window is not distinct from
         (select pp.exam_window from pilot_profiles pp where pp.user_id = p_me))
  order by coalesce(a.n, 0) desc, squadron_headcount(s.id) desc
  limit 40;
$$;

-- ------------------------------------------------------------- 8 · joining
-- ONE DOOR. Every route in — the discovery card, the invite link, an accepted
-- person-to-person invite — comes through here, so the capacity rule and the
-- block rule cannot be true on one path and forgotten on another.
--
-- Returns the outcome as text rather than raising: the caller renders it, and
-- "full" is an ordinary answer rather than an error.
create or replace function join_squadron(p_me text, p_squadron uuid)
returns text
language plpgsql
volatile
as $$
declare s squadrons%rowtype;
begin
  select * into s from squadrons where id = p_squadron;
  if not found then return 'missing'; end if;
  if exists (select 1 from squadron_members where squadron_id = s.id and user_id = p_me)
    then return 'already_in'; end if;
  -- A blocked person cannot arrive by any route, including a link they were
  -- given before the block.
  if exists (
    select 1 from squadron_members m
    join blocks b on (b.user_id = p_me and b.blocked_id = m.user_id)
                  or (b.user_id = m.user_id and b.blocked_id = p_me)
    where m.squadron_id = s.id
  ) then return 'unavailable'; end if;
  if coalesce(squadron_is_full(s.id), false) then return 'full'; end if;

  if s.join_policy = 'open' then
    insert into squadron_members (squadron_id, user_id) values (s.id, p_me)
      on conflict do nothing;
    return 'joined';
  elsif s.join_policy = 'request' then
    insert into squadron_join_requests (squadron_id, user_id) values (s.id, p_me)
      on conflict (squadron_id, user_id) do update set state = 'pending', decided_at = null;
    return 'requested';
  else
    return 'invite_only';
  end if;
end $$;

-- --------------------------------------------------------- 9 · invite links
-- Resolving a link is a read that already knows every reason it might fail, so
-- the page can say which one. A revoked or expired token is 'missing' on
-- purpose: a link that says "this was revoked" tells a stranger the room
-- exists.
create or replace function squadron_by_invite(p_me text, p_token text)
returns table (id uuid, name text, blurb text, members integer, state text)
language sql
stable
as $$
  select s.id, s.name, s.blurb, squadron_headcount(s.id) as members,
    case
      when s.invite_revoked_at is not null then 'missing'
      when s.invite_expires_at is not null and s.invite_expires_at < now() then 'missing'
      when exists (select 1 from squadron_members m where m.squadron_id = s.id and m.user_id = p_me)
        then 'already_in'
      when exists (
        select 1 from squadron_members m
        join blocks b on (b.user_id = p_me and b.blocked_id = m.user_id)
                      or (b.user_id = m.user_id and b.blocked_id = p_me)
        where m.squadron_id = s.id
      ) then 'unavailable'
      when coalesce(squadron_is_full(s.id), false) then 'full'
      else 'ok'
    end as state
  from squadrons s
  where lower(s.invite_token) = lower(btrim(p_token));
$$;


-- ############################################################################
-- 0012_search_and_suggestions.sql
-- ############################################################################

-- Wingman — searchable names, and suggestions that rank rather than list
--
-- Run after 0011. Safe to re-run. Adds one column and replaces three functions.
--
-- ===========================================================================
-- 1 · A NAME IS SEARCHABLE UNTIL ITS OWNER SAYS OTHERWISE
-- ===========================================================================
-- People are found by callsign OR real name. But "Go by callsign" already
-- exists as a preference — user_prefs.identity_display, 'real' | 'username' —
-- and when somebody has chosen it, their real name is not merely hidden from
-- the result, it is NOT MATCHED AT ALL. Searching their real name finds
-- nothing, which is the only version of that promise worth making: a name that
-- is unmatchable cannot be confirmed by guessing it.
--
-- And the function never RETURNS the real name of somebody who goes by
-- callsign. Filtering it in the client would leave it in the response, which is
-- the same leak with a curtain over it.
alter table pilot_profiles add column if not exists real_name text;

/* DROPPED AND RECREATED, not replaced. The signature changes — it returned
   `callsign` and now returns `display_name`, because what a searcher may see is
   no longer always the same string — and Postgres will not let a replace change
   a return type. Dropping a function is not data loss; the guard on the SQL
   runner treats every drop the same and this one needs saying out loud. */
drop function if exists people_search(text, text);

create function people_search(p_me text, p_q text)
returns table (user_id text, display_name text, module_code text, shares_squadron boolean)
language sql
stable
as $$
  with me_prefs as (select p_me as uid)
  select
    p.user_id,
    /* What the searcher is allowed to see them as. Never coalesce to real_name
       for somebody who goes by callsign — that is the leak. */
    case when coalesce(up.identity_display, 'real') = 'username'
         then p.callsign
         else coalesce(p.real_name, p.callsign) end as display_name,
    (select c.module_code from chapter_completions c
      where c.user_id = p.user_id order by c.completed_at desc limit 1) as module_code,
    exists (
      select 1 from squadron_members a
      join squadron_members b on b.squadron_id = a.squadron_id
      where a.user_id = p_me and b.user_id = p.user_id
    ) as shares_squadron
  from pilot_profiles p
  left join user_prefs up on up.user_id = p.user_id
  cross join me_prefs
  where p.discoverable
    and in_my_orbit(p_me, p.user_id)
    and not exists (select 1 from blocks b
                    where (b.user_id = p_me and b.blocked_id = p.user_id)
                       or (b.user_id = p.user_id and b.blocked_id = p_me))
    and coalesce(btrim(p_q), '') <> ''
    and (
      p.callsign ilike '%' || btrim(p_q) || '%'
      /* The real name is matchable ONLY while they have not chosen otherwise. */
      or (coalesce(up.identity_display, 'real') <> 'username'
          and p.real_name ilike '%' || btrim(p_q) || '%')
    )
  order by shares_squadron desc, display_name
  limit 20;
$$;

-- ===========================================================================
-- 2 · SUGGESTIONS — ranked, with the reason attached
-- ===========================================================================
-- Modelled on what a suggestion feed actually does: score on overlap, order by
-- score, and say WHY. A list of rooms in creation order is a directory; the
-- same rooms ordered by how much they have to do with you, each carrying the
-- one fact that earned it its place, is a suggestion.
--
-- WHAT IT MAY NOT DO. It cannot suggest a person outside the orbit. A feed that
-- surfaces strangers is a directory with a ranking function in front of it, and
-- §3 forbids the directory however it is sorted. Squadrons are unrestricted —
-- that is the point of them, and it is why the room is the recommended door and
-- the person is what is behind it.
--
-- The weights are stated as numbers rather than buried in a case expression so
-- they can be argued with. In order of how much they say about whether you
-- belong somewhere: the module you study, then people you already know, then
-- the exam you are sitting, then how alive the room is.

create or replace function suggest_squadrons(p_me text, p_limit integer default 12)
returns table (
  id uuid, name text, blurb text, module_code text, exam_window text,
  join_policy text, members integer, active_week integer, is_full boolean,
  known_ids text[], score integer, reason text
)
language sql
stable
as $$
  with mine as (select squadron_id from squadron_members where user_id = p_me),
  my_mods as (select * from my_modules(p_me)),
  my_exam as (select exam_window e from pilot_profiles where user_id = p_me),
  active as (
    select m.squadron_id, count(distinct pr.user_id)::int n
    from squadron_members m
    left join presence pr on pr.user_id = m.user_id and pr.last_seen > now() - interval '7 days'
    group by m.squadron_id
  ),
  scored as (
    select s.*,
      coalesce(a.n, 0) as active_week,
      squadron_headcount(s.id) as members,
      coalesce(squadron_is_full(s.id), false) as full_now,
      coalesce((select array_agg(sm.user_id) from squadron_members sm
                where sm.squadron_id = s.id and in_my_orbit(p_me, sm.user_id)), '{}') as known,
      (s.module_code in (select * from my_mods))                            as mod_hit,
      (s.exam_window is not null
        and s.exam_window = (select e from my_exam))                        as exam_hit,
      (select count(*) from squadron_members sm
        where sm.squadron_id = s.id and in_my_orbit(p_me, sm.user_id))::int as known_n
    from squadrons s
    left join active a on a.squadron_id = s.id
    where s.join_policy in ('open', 'request')
      and s.id not in (select squadron_id from mine)
      /* Never suggest a room where somebody has blocked you, or you them. */
      and not exists (
        select 1 from squadron_members m
        join blocks b on (b.user_id = p_me and b.blocked_id = m.user_id)
                      or (b.user_id = m.user_id and b.blocked_id = p_me)
        where m.squadron_id = s.id)
  )
  select id, name, blurb, module_code, exam_window, join_policy,
    members, active_week, full_now as is_full, known,
    (   case when mod_hit  then 40 else 0 end
      + case when exam_hit then 20 else 0 end
      + least(known_n * 8, 24)
      + least(active_week, 10) * 2
      + case when full_now then -35 else 0 end
    )::int as score,
    /* ONE REASON, THE STRONGEST. Three reasons on a card is a specification;
       one is a suggestion. Ordered by what actually persuades somebody to join:
       who is already in there beats what it is about. */
    case
      when known_n > 0    then 'known'
      when mod_hit        then 'module'
      when exam_hit       then 'exam'
      when active_week > 0 then 'busy'
      else 'open'
    end as reason
  from scored
  order by score desc, active_week desc, members desc
  limit greatest(1, p_limit);
$$;

-- People, and only ever from inside the orbit. Ranked on the things that
-- predict whether two students are useful to each other: rooms in common,
-- the module they are both in, the sitting they are both working toward, and
-- whether they are awake at the same time.
create or replace function suggest_people(p_me text, p_limit integer default 8)
returns table (
  user_id text, display_name text, module_code text,
  shared_squadrons integer, score integer, reason text
)
language sql
stable
as $$
  with me as (
    select p.exam_window, p.active_window
    from pilot_profiles p where p.user_id = p_me
  ),
  cand as (
    select p.user_id, p.callsign, p.real_name, p.exam_window, p.active_window,
      coalesce(up.identity_display, 'real') as ident,
      (select count(*) from squadron_members a
        join squadron_members b on b.squadron_id = a.squadron_id
        where a.user_id = p_me and b.user_id = p.user_id)::int as shared_sq,
      (select count(*) from lesson_threads t
        where t.author_id = p.user_id and t.module_id in (select * from my_modules(p_me)))::int as posts_here,
      (select max(pr.last_seen) from presence pr where pr.user_id = p.user_id) as seen
    from pilot_profiles p
    left join user_prefs up on up.user_id = p.user_id
    where p.discoverable
      and in_my_orbit(p_me, p.user_id)
      and not exists (select 1 from blocks b
                      where (b.user_id = p_me and b.blocked_id = p.user_id)
                         or (b.user_id = p.user_id and b.blocked_id = p_me))
  )
  select c.user_id,
    case when c.ident = 'username' then c.callsign
         else coalesce(c.real_name, c.callsign) end as display_name,
    (select ch.module_code from chapter_completions ch
      where ch.user_id = c.user_id order by ch.completed_at desc limit 1) as module_code,
    c.shared_sq as shared_squadrons,
    (   least(c.shared_sq * 25, 50)
      + least(c.posts_here * 6, 18)
      + case when c.exam_window is not null
              and c.exam_window = (select exam_window from me) then 15 else 0 end
      + case when c.active_window is not null
              and c.active_window = (select active_window from me) then 10 else 0 end
      + case when c.seen > now() - interval '7 days' then 8 else 0 end
    )::int as score,
    case
      when c.shared_sq > 0 then 'squadron'
      when c.posts_here > 0 then 'answers'
      when c.exam_window = (select exam_window from me) then 'exam'
      when c.active_window = (select active_window from me) then 'hours'
      else 'module'
    end as reason
  from cand c
  order by score desc, c.seen desc nulls last
  limit greatest(1, p_limit);
$$;


-- ############################################################################
-- 0013_retire_pilot_livery.sql
-- ############################################################################

-- 0013 — retire the pilot livery.
--
-- WHAT THIS REMOVES, AND WHY IT IS NOT THE LIVERY YOU ARE THINKING OF.
--
-- Two different things in this codebase were called a livery, and they had
-- nothing to do with each other beyond the word:
--
--   1. The APP's livery — sky / amber / tarmac / beacon / runway / skydrol.
--      Chosen in Profile -> Appearance, written to documentElement as
--      data-livery, and generated by src/lib/liveryEngine.js. This one is
--      current, it is the design system, and 0013 does not touch it.
--
--   2. The PILOT's livery — dawn-patrol / night-ops / contrail / carrier-deck
--      / altimeter / aurora. Picked once during signup, stored here, and used
--      to tint a person's tail. This is the older build's, and it is what 0013
--      removes.
--
-- It had already stopped meaning anything. Every --tail-<id> token in app.css
-- resolved to var(--active) for all twelve ids in both sets, under a comment
-- reading "A person carries no colour of their own under this system" — so the
-- choice painted nothing, on any screen, for anybody. What was left of it was a
-- step in onboarding asking a new student to pick between six swatches that all
-- produce the same colour, before they had seen the product.
--
-- Live values at the time of writing: 3 profiles across 2 distinct liveries,
-- 1 squadron. No information is lost, because none of it was ever rendered.
--
-- Order matters. squadron_roster is language sql and so has a hard catalogue
-- dependency on pilot_profiles.livery: the column cannot be dropped while the
-- function still selects it. Both functions are replaced first, then the
-- columns go.

-- ---------------------------------------------------------------- functions

-- Body copied from the live definition (pg_get_functiondef), with the livery
-- column removed from the one insert that set it. Nothing else changed.
create or replace function assign_squadron(uid text, mod text, stime text)
returns uuid
language plpgsql
as $$
declare target uuid;
begin
  select s.id into target
    from squadron_members m join squadrons s on s.id = m.squadron_id
   where m.user_id = uid and s.module_code = mod
   limit 1;
  if target is not null then return target; end if;

  select s.id into target from squadrons s
   where s.module_code = mod and s.study_time is not distinct from stime
     and (select count(*) from squadron_members m where m.squadron_id = s.id) < 20
   order by (select count(*) from squadron_members m where m.squadron_id = s.id) desc
   limit 1;

  if target is null then
    select s.id into target from squadrons s
     where s.module_code = mod
       and (select count(*) from squadron_members m where m.squadron_id = s.id) < 20
     order by (select count(*) from squadron_members m where m.squadron_id = s.id) desc
     limit 1;
  end if;

  if target is null then
    select s.id into target from squadrons s
     where s.study_time is not distinct from stime
       and (select count(*) from squadron_members m where m.squadron_id = s.id) < 20
     order by (select count(*) from squadron_members m where m.squadron_id = s.id) desc
     limit 1;
  end if;

  if target is null then
    select s.id into target from squadrons s
     where (select count(*) from squadron_members m where m.squadron_id = s.id) < 20
     order by (select count(*) from squadron_members m where m.squadron_id = s.id) desc
     limit 1;
  end if;

  -- none exists yet: open one. It will be 'forming' until it reaches 10.
  if target is null then
    insert into squadrons (module_code, study_time)
    values (mod, stime)
    returning id into target;
  end if;

  insert into squadron_members (squadron_id, user_id)
  values (target, uid)
  on conflict do nothing;

  update squadrons
     set status = case
       when (select count(*) from squadron_members m where m.squadron_id = target) >= 10
       then 'active' else 'forming' end
   where id = target;

  return target;
end $$;

-- The return type loses a column, so create or replace is not enough — the
-- signature has to be dropped first. Nothing in the client reads the result of
-- this one today, so the narrower shape breaks no caller.
drop function if exists squadron_roster(text, uuid);

create function squadron_roster(uid text, sid uuid)
returns table (user_id text, callsign text, marking text, is_staff boolean, joined_at timestamptz)
language sql
stable
as $$
  select m.user_id, p.callsign, m.marking,
         coalesce(p.is_staff, false), m.joined_at
    from squadron_members m
    left join pilot_profiles p on p.user_id = m.user_id
   where m.squadron_id = sid
     and m.user_id not in (select blocked_id from blocks where blocks.user_id = uid)
     and m.user_id not in (select b.user_id from blocks b where b.blocked_id = uid)
   order by m.joined_at;
$$;

-- ------------------------------------------------------------------ columns

alter table pilot_profiles drop column if exists livery;
alter table squadrons      drop column if exists livery;


-- ############################################################################
-- 0014_paper_annotations.sql
-- ############################################################################

-- 0014 — the annotation layer on Library papers.
--
-- A layer OVER a paper. The paper is never edited by anyone but the author;
-- every highlight, note, question and correction is a separate record pointing
-- at a passage. Filtering by person, by type or by group is then just deciding
-- which records to draw, and nothing a reader does can damage the paper.
--
-- R1 — AN ANCHOR IS TEXT, NEVER COORDINATES. This is the rule the whole design
-- turns on, and it is enforced here rather than trusted: the CHECK below
-- refuses any anchor carrying page, rect, rects or bbox. Coordinates are a
-- drawing detail that changes with zoom, with rotation, with the renderer, and
-- with the paper becoming native content later. They go in `hint`, which is
-- explicitly disposable, and nothing may read `hint` for identity.
--
-- Written against the live schema, not assumed: the four rings all have real
-- tables already — wingmen, formation_members + formations, squadron_members
-- and enrollments — so ring visibility is a join, not a new concept.

create table if not exists paper_annotations (
  id             uuid primary key default gen_random_uuid(),
  paper_id       text        not null,
  module_code    text        not null,
  -- The version of the paper this mark was made against. Papers are a content
  -- fixture today, so every mark is made against version 1; when papers become
  -- native content that brief owns the bump, and a bump is what triggers the
  -- re-resolve that can orphan a mark.
  paper_version  int         not null default 1,
  -- Never null. There is no anonymous marking: every mark carries a licence, so
  -- there is always a name behind it.
  author_id      text        not null,
  kind           text        not null check (kind in ('highlight','note','question','correction')),
  ring           text        not null default 'module' check (ring in ('solo','wingman','formation','module')),
  -- Null for a bare highlight. R5: the cheapest mark is wordless, and density
  -- is built out of exactly these.
  body           text,
  -- Set for kind='question': the Ready Room thread this mirrors into (R10).
  thread_id      text,
  -- Corrections only: when the author accepted or dismissed it (R9).
  resolved_at    timestamptz,
  status         text        not null default 'ok' check (status in ('ok','orphaned')),
  anchor         jsonb       not null,
  -- Cached page and rects, for drawing only. Discarded on any version bump.
  hint           jsonb,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),

  -- R1, enforced rather than reviewed. A code path that tries to smuggle a
  -- position into the anchor fails at the database, where it cannot be argued
  -- with, instead of silently producing marks that cannot survive a reflow.
  constraint anchor_is_text_only check (
    not (anchor ? 'page' or anchor ? 'rect' or anchor ? 'rects' or anchor ? 'bbox')
  ),
  -- A question without its thread is a question nobody can answer.
  constraint question_has_thread check (kind <> 'question' or thread_id is not null)
);

create index if not exists paper_annotations_paper on paper_annotations (paper_id, status);
create index if not exists paper_annotations_author on paper_annotations (author_id);
create index if not exists paper_annotations_updated on paper_annotations (paper_id, updated_at desc);

alter table paper_annotations enable row level security;
-- Open, like every other table here: the client is anonymous from Postgres'
-- point of view and access control happens in the functions below and in the
-- app. See 0009's header before writing any policy that mentions auth.uid().
drop policy if exists paper_annotations_all on paper_annotations;
create policy paper_annotations_all on paper_annotations for all using (true) with check (true);

-- ---------------------------------------------------------------- the rings
--
-- Who can see a mark this person made. The rings nest: module contains
-- formation contains wingman contains solo. One function, so the paper view
-- cannot grow a second opinion about what "formation" means (R12).
create or replace function ring_covers(p_author text, p_viewer text, p_ring text, p_module text)
returns boolean
language sql
stable
as $$
  select case
    when p_author = p_viewer then true
    when p_ring = 'solo' then false
    when p_ring = 'wingman' then exists (
      select 1 from wingmen w
       where (w.user_id = p_author and w.wingman_user_id = p_viewer)
          or (w.user_id = p_viewer and w.wingman_user_id = p_author))
    when p_ring = 'formation' then exists (
      select 1 from wingmen w
       where (w.user_id = p_author and w.wingman_user_id = p_viewer)
          or (w.user_id = p_viewer and w.wingman_user_id = p_author))
      or exists (
      select 1 from formation_members a
        join formation_members b on b.formation_id = a.formation_id
       where a.user_id = p_author and b.user_id = p_viewer
         and a.left_at is null and b.left_at is null)
      or exists (
      select 1 from squadron_members a
        join squadron_members b on b.squadron_id = a.squadron_id
       where a.user_id = p_author and b.user_id = p_viewer)
    when p_ring = 'module' then coalesce(p_module, '') <> ''
    else false
  end;
$$;

-- ------------------------------------------------------------------- reading
--
-- R9 — corrections are invisible to other readers, and that is enforced HERE
-- rather than by hiding them in the client: a correction written by student A
-- is absent from student B's payload entirely, not merely undrawn.
--
-- R12 — Fly solo is symmetric and needs no second toggle on the paper. An
-- invisible reader sees only their own marks; an invisible author's marks
-- reach nobody.
-- `close` is R4's whole selector, decided here rather than in the client: true
-- for you, your wingman and your formation, false for everyone else on the
-- module. Individuals are drawn for the first group; the second becomes
-- density. Working it out in the browser would mean either a query per author
-- or a second opinion about what formation means.
drop function if exists paper_annotations_for(text, text, timestamptz);

create function paper_annotations_for(uid text, p_paper text, p_since timestamptz default null)
returns table (
  id uuid, paper_id text, module_code text, paper_version int,
  author_id text, author_name text, kind text, ring text, body text,
  thread_id text, resolved_at timestamptz, status text,
  anchor jsonb, hint jsonb, created_at timestamptz, updated_at timestamptz,
  close boolean
)
language sql
stable
as $$
  with me as (
    select coalesce((select p.invisible from pilot_profiles p where p.user_id = uid), false) as solo,
           coalesce((select p.is_staff  from pilot_profiles p where p.user_id = uid), false) as staff
  )
  select a.id, a.paper_id, a.module_code, a.paper_version,
         a.author_id,
         case when a.author_id = uid then 'You'
              else coalesce(pp.callsign, pp.real_name, 'Someone') end as author_name,
         a.kind, a.ring, a.body, a.thread_id, a.resolved_at, a.status,
         a.anchor, a.hint, a.created_at, a.updated_at,
         (a.author_id = uid or ring_covers(a.author_id, uid, 'formation', a.module_code)) as close
    from paper_annotations a
    left join pilot_profiles pp on pp.user_id = a.author_id
   cross join me
   where a.paper_id = p_paper
     and (p_since is null or a.updated_at > p_since)
     -- your own are always yours
     and (a.author_id = uid
          or (
            not me.solo
            -- an invisible author reaches nobody
            and not coalesce((select p.invisible from pilot_profiles p where p.user_id = a.author_id), false)
            -- blocks cut both ways
            and not exists (select 1 from blocks b where b.user_id = uid and b.blocked_id = a.author_id)
            and not exists (select 1 from blocks b where b.user_id = a.author_id and b.blocked_id = uid)
            and not exists (select 1 from mutes m where m.user_id = uid and m.muted_id = a.author_id)
            /* R9 — a correction is for its author and the staff, and for
               nobody else. Deliberately NOT "the ring rule, plus a staff
               exception": whichever ring a correction was stored with is
               irrelevant to who may see it, and making staff visibility depend
               on the ring meant the author could not see a correction written
               to the writer's own ring — which is every correction, since that
               is what the composer sets. The kind decides. */
            and (case when a.kind = 'correction' then me.staff
                      else ring_covers(a.author_id, uid, a.ring, a.module_code) end)
          ))
   order by a.created_at;
$$;

-- The author queue: every open correction on this module, for staff only.
-- Returns nothing at all for anybody else rather than raising — a queue you
-- cannot see should not tell you it exists.
create or replace function paper_corrections_for(uid text, p_module text)
returns table (
  id uuid, paper_id text, author_id text, author_name text,
  body text, anchor jsonb, status text, created_at timestamptz
)
language sql
stable
as $$
  select a.id, a.paper_id, a.author_id,
         coalesce(pp.callsign, pp.real_name, 'Someone'),
         a.body, a.anchor, a.status, a.created_at
    from paper_annotations a
    left join pilot_profiles pp on pp.user_id = a.author_id
   where a.kind = 'correction'
     and a.module_code = p_module
     and a.resolved_at is null
     and coalesce((select p.is_staff from pilot_profiles p where p.user_id = uid), false)
   order by a.created_at;
$$;

-- R2 — a lost annotation is orphaned, never relocated and never deleted. The
-- re-resolve runs where the document text is (the reader), and this is the one
-- write it makes. Kept as a function so "mark orphaned" cannot drift into
-- "delete the row" at some call site.
create or replace function paper_annotation_status(p_id uuid, p_status text)
returns void
language sql
volatile
as $$
  update paper_annotations
     set status = case when p_status = 'orphaned' then 'orphaned' else 'ok' end,
         updated_at = now()
   where id = p_id;
$$;


-- ############################################################################
-- 0015_live_updates.sql
-- ############################################################################

-- 0015 — live updates.
--
-- The discussion was read once per module entry, then on a 20 second timer.
-- Twenty seconds is not "live" to anyone standing next to the person who just
-- typed: they look, nothing is there, and they refresh. So the client listens
-- now, and the timer becomes a safety net rather than the mechanism.
--
-- Supabase Realtime only sends changes for tables in this publication, and it
-- was empty. Three tables, and only three: the two halves of the discussion and
-- the squadron chat. Presence is deliberately NOT here — it is a heartbeat with
-- a three minute window, and streaming every beat to every reader would be a
-- lot of traffic to say nothing has changed.
--
-- REPLICA IDENTITY FULL is what makes a DELETE carry the row that was deleted.
-- Without it a delete arrives as a bare primary key, and a client that cannot
-- tell which module a deleted thread belonged to has to refetch all of them.

alter publication supabase_realtime add table lesson_threads;
alter publication supabase_realtime add table lesson_replies;
alter publication supabase_realtime add table comms_messages;

alter table lesson_threads  replica identity full;
alter table lesson_replies  replica identity full;
alter table comms_messages  replica identity full;


-- ############################################################################
-- 0016_pilot_code.sql
-- ############################################################################

-- 0016 — the three-character code.
--
-- Every pilot has one, chosen at signup, shown on their licence, and stamped on
-- a chapter when they finish it. It is an identity people say out loud, so:
--
--   UNIQUE, because two pilots with the same code is two pilots with no code.
--   The index enforces it; nothing in the app is trusted to check first and
--   then insert, because between the check and the insert is where the
--   duplicate gets in.
--
--   UPPERCASE AND THREE CHARACTERS, from an alphabet with no 0/O and no 1/I/L.
--   A code that cannot be read back off a photograph is not an identifier, and
--   a photograph is exactly where this one will be read from. See src/lib/code.js
--   — the CHECK below is that alphabet, written where it cannot be bypassed.
--
-- Nullable on purpose: every account that exists today predates this, and a
-- NOT NULL would lock all of them out of a table the whole app reads. They get
-- one the next time they set foot in the licence.

alter table pilot_profiles add column if not exists code text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'pilot_code_shape') then
    alter table pilot_profiles
      add constraint pilot_code_shape
      check (code is null or code ~ '^[23456789ABCDEFGHJKMNPQRSTUVWXYZ]{3}$');
  end if;
end $$;

create unique index if not exists pilot_profiles_code_key on pilot_profiles (code)
  where code is not null;

-- Claiming one. Atomic: the insert either takes the code or it does not, and the
-- caller is told which. Doing this as "is it free? then take it" in the client
-- leaves a gap two people can walk through at once, and at signup — when
-- everybody arrives together — that gap is widest.
--
-- Returns the code on success and null when it is already somebody else's.
create or replace function claim_code(uid text, want text)
returns text
language plpgsql
volatile
as $$
declare taken boolean;
begin
  if want is null or want !~ '^[23456789ABCDEFGHJKMNPQRSTUVWXYZ]{3}$' then
    return null;
  end if;

  select exists (
    select 1 from pilot_profiles p where p.code = want and p.user_id <> uid
  ) into taken;
  if taken then return null; end if;

  insert into pilot_profiles (user_id, code) values (uid, want)
  on conflict (user_id) do update set code = excluded.code;

  return want;
exception
  -- Somebody claimed it between the check and the write. That is the race this
  -- function exists to lose safely: say no, and the caller offers another.
  when unique_violation then return null;
end $$;

-- A free one to suggest, so nobody has to invent a code under pressure while
-- signing up. Tries at random and gives up rather than looping forever — with
-- 29,791 codes and a cohort of students, a collision is rare and the caller
-- can simply ask again.
create or replace function suggest_code()
returns text
language plpgsql
stable
as $$
declare
  alphabet text := '23456789ABCDEFGHJKMNPQRSTUVWXYZ';
  candidate text;
begin
  for _try in 1..12 loop
    candidate := substr(alphabet, 1 + floor(random() * 31)::int, 1)
              || substr(alphabet, 1 + floor(random() * 31)::int, 1)
              || substr(alphabet, 1 + floor(random() * 31)::int, 1);
    if not exists (select 1 from pilot_profiles p where p.code = candidate) then
      return candidate;
    end if;
  end loop;
  return null;
end $$;


-- ############################################################################
-- 0017_paper_ink.sql
-- ############################################################################

-- 0017 — ink, colour, and the two marks the reader was missing.
--
-- Three things, and they are one change: this is what turns the annotation
-- layer into a reader people recognise.
--
--   1. paper_annotations.colour — the highlighter has a palette now. The NAME
--      is stored, never the colour, so what "blue" looks like stays a CSS
--      decision and can be re-tinted for the night theme without a migration
--      and without changing what anybody's existing mark means.
--
--   2. kind gains 'underline' and 'strikethrough'. Same anchor, same rings,
--      same everything — a different way of drawing the passage you picked.
--      They are text marks in every sense, so they go here rather than in the
--      ink table, and a reader who underlines still gets a mark that survives
--      the paper being re-extracted.
--
--   3. paper_ink — freehand strokes, and the ONE place in this feature where
--      coordinates are stored.
--
-- ---------------------------------------------------------------------------
-- WHY INK DOES NOT BREAK R1
--
-- R1 says an anchor is text, never coordinates, and 0014's anchor_is_text_only
-- CHECK refuses any anchor carrying a page, rect or bbox. That constraint is
-- untouched here and stays exactly as strict, because ink never goes near an
-- anchor: a stroke is not a claim about a passage, it is a drawing, and there
-- is no sentence you could store instead that would let you draw it again.
--
-- The rule R1 exists to protect is "a mark about a passage must survive the
-- passage moving". A stroke makes no such claim, and this table says so in its
-- own shape: it has a page and it has points, it has no anchor at all, and it
-- carries the version it was drawn against so a bump can strand it honestly
-- rather than drawing it somewhere plausible.
--
-- Points are FRACTIONS of the unrotated page, 0..1, not pixels. A stroke drawn
-- at 80% on a phone is the same stroke at 250% on a laptop. Pixels would have
-- been the same class of silent bug as a positional anchor.

-- --------------------------------------------------------------- 1. colour
alter table paper_annotations add column if not exists colour text;

do $$ begin
  alter table paper_annotations add constraint colour_is_a_name check (
    colour is null or colour in
      ('yellow','green','blue','pink','orange','purple','red','graphite')
  );
exception when duplicate_object then null; end $$;

-- --------------------------------------------------- 2. two more text marks
-- The kind CHECK is replaced rather than added to: a constraint cannot be
-- widened in place, and dropping it for the instant between is safe because
-- nothing can insert an invalid kind through the client in that window — the
-- kinds come from a constant list in paperMarks.js.
do $$
declare c text;
begin
  for c in
    select con.conname from pg_constraint con
      join pg_class t on t.oid = con.conrelid
     where t.relname = 'paper_annotations' and con.contype = 'c'
       and pg_get_constraintdef(con.oid) like '%highlight%'
  loop
    execute format('alter table paper_annotations drop constraint %I', c);
  end loop;
end $$;
alter table paper_annotations add constraint paper_annotations_kind_check
  check (kind in ('highlight','underline','strikethrough','note','question','correction'));

-- ------------------------------------------------------------------ 3. ink
create table if not exists paper_ink (
  id             uuid primary key default gen_random_uuid(),
  paper_id       text        not null,
  module_code    text        not null,
  paper_version  int         not null default 1,
  author_id      text        not null,
  page           int         not null check (page >= 1),
  -- 'pen' lays colour down solid; 'marker' lays it down translucent and
  -- multiplies, the way a highlighter does over words.
  tool           text        not null default 'pen' check (tool in ('pen','marker')),
  colour         text        not null default 'graphite' check (
    colour in ('yellow','green','blue','pink','orange','purple','red','graphite')),
  -- A fraction of the page WIDTH, so the nib is the same size at every zoom.
  width          real        not null default 0.0032 check (width > 0 and width < 0.2),
  ring           text        not null default 'solo' check (ring in ('solo','wingman','formation','module')),
  -- [[x,y], …] with every value 0..1 of the unrotated page.
  points         jsonb       not null,
  created_at     timestamptz not null default now(),

  -- A stroke with one point is a dot and is legitimate; a stroke with none is
  -- a bug that would otherwise sit in the table forever drawing nothing.
  constraint ink_has_points check (jsonb_typeof(points) = 'array' and jsonb_array_length(points) >= 1)
  -- There is deliberately no anchor column and no CHECK pretending to guard
  -- one. Ink is coordinates and only coordinates; a stroke carrying a quote
  -- would be a mark claiming to survive a reflow it cannot survive, and the
  -- way to make that impossible is to give it nowhere to put one.
);

create index if not exists paper_ink_paper on paper_ink (paper_id, page);
create index if not exists paper_ink_author on paper_ink (author_id);

alter table paper_ink enable row level security;
drop policy if exists paper_ink_all on paper_ink;
create policy paper_ink_all on paper_ink for all using (true) with check (true);

-- Ink is read through a function for the same reason marks are: Fly solo is
-- symmetric, blocks cut both ways, and the ring decides. Doing that in the
-- client would mean a second opinion about what "formation" means, and 0014's
-- header says why there is exactly one.
create or replace function paper_ink_for(uid text, p_paper text)
returns table (
  id uuid, paper_id text, module_code text, paper_version int,
  author_id text, author_name text, page int, tool text, colour text,
  width real, ring text, points jsonb, created_at timestamptz, mine boolean
)
language sql
stable
as $$
  with me as (
    select coalesce((select p.invisible from pilot_profiles p where p.user_id = uid), false) as solo
  )
  select k.id, k.paper_id, k.module_code, k.paper_version,
         k.author_id,
         case when k.author_id = uid then 'You'
              else coalesce(pp.callsign, pp.real_name, 'Someone') end,
         k.page, k.tool, k.colour, k.width, k.ring, k.points, k.created_at,
         (k.author_id = uid)
    from paper_ink k
    left join pilot_profiles pp on pp.user_id = k.author_id
   cross join me
   where k.paper_id = p_paper
     and (k.author_id = uid
          or (
            not me.solo
            and not coalesce((select p.invisible from pilot_profiles p where p.user_id = k.author_id), false)
            and not exists (select 1 from blocks b where b.user_id = uid and b.blocked_id = k.author_id)
            and not exists (select 1 from blocks b where b.user_id = k.author_id and b.blocked_id = uid)
            and not exists (select 1 from mutes m where m.user_id = uid and m.muted_id = k.author_id)
            and ring_covers(k.author_id, uid, k.ring, k.module_code)
          ))
   order by k.created_at;
$$;

-- ------------------------------------------------- marks, now with a colour
--
-- A NEW NAME RATHER THAN A REPLACEMENT, AND ON PURPOSE.
--
-- A function's return shape cannot be widened in place — Postgres refuses
-- CREATE OR REPLACE the moment the column list changes — so adding `colour`
-- to paper_annotations_for would mean dropping it first. This migration
-- expands instead of replacing: the new shape gets a new name, the old
-- function keeps answering for anything still calling it, and nothing is
-- dropped in the same breath as something is created.
--
-- That is the ordinary way to widen a live contract, and it costs one dead
-- function. `paper_marks_for` is also simply the right name: the screen calls
-- them marks, the rail tab says Marks, and the model lives in paperMarks.js.
-- `paper_annotations_for` was the only place in the feature still saying
-- annotations.
--
-- When it is convenient, and with nothing calling it:
--   drop function if exists paper_annotations_for(text, text, timestamptz);
create or replace function paper_marks_for(uid text, p_paper text, p_since timestamptz default null)
returns table (
  id uuid, paper_id text, module_code text, paper_version int,
  author_id text, author_name text, kind text, ring text, body text,
  colour text, thread_id text, resolved_at timestamptz, status text,
  anchor jsonb, hint jsonb, created_at timestamptz, updated_at timestamptz,
  close boolean
)
language sql
stable
as $$
  with me as (
    select coalesce((select p.invisible from pilot_profiles p where p.user_id = uid), false) as solo,
           coalesce((select p.is_staff  from pilot_profiles p where p.user_id = uid), false) as staff
  )
  select a.id, a.paper_id, a.module_code, a.paper_version,
         a.author_id,
         case when a.author_id = uid then 'You'
              else coalesce(pp.callsign, pp.real_name, 'Someone') end as author_name,
         a.kind, a.ring, a.body, a.colour, a.thread_id, a.resolved_at, a.status,
         a.anchor, a.hint, a.created_at, a.updated_at,
         (a.author_id = uid or ring_covers(a.author_id, uid, 'formation', a.module_code)) as close
    from paper_annotations a
    left join pilot_profiles pp on pp.user_id = a.author_id
   cross join me
   where a.paper_id = p_paper
     and (p_since is null or a.updated_at > p_since)
     and (a.author_id = uid
          or (
            not me.solo
            and not coalesce((select p.invisible from pilot_profiles p where p.user_id = a.author_id), false)
            and not exists (select 1 from blocks b where b.user_id = uid and b.blocked_id = a.author_id)
            and not exists (select 1 from blocks b where b.user_id = a.author_id and b.blocked_id = uid)
            and not exists (select 1 from mutes m where m.user_id = uid and m.muted_id = a.author_id)
            /* R9, unchanged from 0014 — the kind decides, not the ring. */
            and (case when a.kind = 'correction' then me.staff
                      else ring_covers(a.author_id, uid, a.ring, a.module_code) end)
          ))
   order by a.created_at;
$$;


-- ############################################################################
-- 0018_reader_rebuild.sql
-- ############################################################################

-- 0018 — the reader rebuild.
--
-- NOT RUN BY THE REBUILD. The instruction for that run was explicit: do not run
-- migrations against production; I will run them myself after I have checked.
-- So this is written, reviewed and left. `npm run reader:setup` applies it.
--
-- Everything here is ADDITIVE except one function replacement, called out below.
-- No column is dropped, no row is touched, and every existing mark keeps
-- working: the new columns all have defaults, and the old eight colour names
-- stay legal alongside the five new ones.
--
-- ---------------------------------------------------------------------------
-- 1. COLOURS ARE VERBS (brief §6)
--
-- Five meanings join the eight ink names. They are NOT a replacement: the eight
-- are what a nib is loaded with and carry no claim, the five are what a text
-- mark MEANS and each one does something — revision deck, glossary, question
-- bank, a thread, Master Caution. Both sets live in one column because a mark
-- has one colour; which set applies is decided by its kind.

alter table paper_annotations drop constraint if exists colour_is_a_name;
alter table paper_annotations add constraint colour_is_a_name check (
  colour is null or colour in (
    -- ink, from 0017 — free colour, no meaning
    'yellow','green','blue','pink','orange','purple','red','graphite',
    -- meanings, and the set is closed for text marks
    'critical','definition','limit','unsure','wrong'
  )
);

-- ---------------------------------------------------------------------------
-- 2. WHAT A MARK NEEDS THAT IT DID NOT HAVE (brief §5.1)

-- §6.2 — questions are anonymous by default. The author is STORED, because
-- moderation needs it, and stripped on the way out. See the function below:
-- the id is absent from another student's payload, not hidden in their browser.
alter table paper_annotations add column if not exists anonymous boolean not null default false;

-- §10 — "Agree" on somebody else's mark, with its count on the card.
alter table paper_annotations add column if not exists agree_count int not null default 0;

-- §5.1 — a soft delete, because sync needs the tombstone. A mark deleted on one
-- device must be able to tell another device it is gone; a row that simply
-- vanishes cannot say anything.
alter table paper_annotations add column if not exists deleted_at timestamptz;
create index if not exists paper_annotations_tomb on paper_annotations (paper_id, updated_at)
  where deleted_at is not null;

-- §5.1 — width and opacity, so a mark can be restyled rather than remade.
alter table paper_annotations add column if not exists style jsonb;

-- §5.1 — the remaining kinds. `ink` is deliberately absent: strokes live in
-- paper_ink, which has no anchor column, for the reason 0017's header gives.
alter table paper_annotations drop constraint if exists paper_annotations_kind_check;
alter table paper_annotations add constraint paper_annotations_kind_check
  check (kind in ('highlight','underline','strikethrough','note','question',
                  'correction','shape','text','stamp'));

-- ---------------------------------------------------------------------------
-- 3. THE ROUND TRIP (brief §14)
--
-- A thread made from a passage could reach the Ready Room but could not point
-- back: `lesson_threads` had no idea which paper or page it came from, so the
-- passage knew about the thread and the thread knew nothing about the passage.
-- "Two features sharing a table", in the brief's words.

alter table lesson_threads add column if not exists paper_id text;
alter table lesson_threads add column if not exists page int;
alter table lesson_threads add column if not exists anchor jsonb;
create index if not exists lesson_threads_paper on lesson_threads (paper_id) where paper_id is not null;

-- ---------------------------------------------------------------------------
-- 4. PAPERS BECOME ROWS (brief §17b)
--
-- Papers are a JSON fixture today, which is why there is no way to add one. A
-- real file uploaded by hand needs somewhere to be recorded, and the sidecars
-- the reader actually reads — manifest, text layer, thumbnails — need somewhere
-- to live beside it.

create table if not exists papers (
  id             text primary key,
  module_code    text not null,
  chapter_id     text,
  title          text not null,
  file_path      text not null,          -- inside the `papers` storage bucket
  pages          int,
  bytes          bigint,
  version        int not null default 1,
  -- 'pending' while the browser is still producing the sidecars. A paper in
  -- this state shows "Preparing…" in the Library rather than a broken viewer.
  status         text not null default 'pending'
                 check (status in ('pending','ready','failed')),
  -- What ingest found, recorded rather than guessed at: whether the file is
  -- linearized (which decides how well range loading works) and whether it has
  -- a text layer at all (which decides whether text marks are possible).
  linearized     boolean,
  has_text       boolean,
  manifest       jsonb,
  failure        text,
  uploaded_by    text,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index if not exists papers_module on papers (module_code, status);

alter table papers enable row level security;
drop policy if exists papers_all on papers;
create policy papers_all on papers for all using (true) with check (true);

-- The bucket the files go in. Public read, because a paper is course material
-- and the app is already gated by Clerk in front of it; writes are the app's.
insert into storage.buckets (id, name, public, file_size_limit)
values ('papers', 'papers', true, 268435456)     -- 256MB, above the 200MB case
on conflict (id) do update set public = true, file_size_limit = 268435456;

drop policy if exists papers_read on storage.objects;
create policy papers_read on storage.objects for select using (bucket_id = 'papers');
drop policy if exists papers_write on storage.objects;
create policy papers_write on storage.objects for insert with check (bucket_id = 'papers');
drop policy if exists papers_update on storage.objects;
create policy papers_update on storage.objects for update using (bucket_id = 'papers');

-- ---------------------------------------------------------------------------
-- 5. THE READER'S QUERY, WIDENED
--
-- THE ONE REPLACEMENT IN THIS FILE. A function's return columns cannot be
-- widened in place, so carrying the new fields means a new shape. 0017 solved
-- the same problem by taking a new name and leaving the old function standing;
-- doing that twice would leave three. This one drops and recreates within a
-- single migration, which is safe because nothing runs between the two
-- statements — and `paper_annotations_for`, already dead since 0017, is
-- dropped at the same time.

drop function if exists paper_annotations_for(text, text, timestamptz);
drop function if exists paper_marks_for(text, text, timestamptz);

create function paper_marks_for(uid text, p_paper text, p_since timestamptz default null)
returns table (
  id uuid, paper_id text, module_code text, paper_version int,
  author_id text, author_name text, kind text, ring text, body text,
  colour text, style jsonb, anonymous boolean, agree_count int,
  thread_id text, resolved_at timestamptz, status text,
  anchor jsonb, hint jsonb, deleted_at timestamptz,
  created_at timestamptz, updated_at timestamptz, close boolean
)
language sql
stable
as $$
  with me as (
    select coalesce((select p.invisible from pilot_profiles p where p.user_id = uid), false) as solo,
           coalesce((select p.is_staff  from pilot_profiles p where p.user_id = uid), false) as staff
  )
  select a.id, a.paper_id, a.module_code, a.paper_version,
         /* §6.2 — ANONYMITY IS ENFORCED HERE, ON THE WAY OUT.
            The id is not hidden in the browser, it is absent from the payload.
            Instructors still receive it, because moderation needs it and the
            UI says so plainly rather than promising what it does not deliver.
            A student always sees their own. */
         case when a.anonymous and a.author_id <> uid and not me.staff then null
              else a.author_id end as author_id,
         case when a.author_id = uid then 'You'
              when a.anonymous and not me.staff then 'Anonymous'
              else coalesce(pp.callsign, pp.real_name, 'Someone') end as author_name,
         a.kind, a.ring, a.body, a.colour, a.style, a.anonymous, a.agree_count,
         a.thread_id, a.resolved_at, a.status, a.anchor, a.hint, a.deleted_at,
         a.created_at, a.updated_at,
         (a.author_id = uid or ring_covers(a.author_id, uid, 'formation', a.module_code)) as close
    from paper_annotations a
    left join pilot_profiles pp on pp.user_id = a.author_id
   cross join me
   where a.paper_id = p_paper
     and (p_since is null or a.updated_at > p_since)
     /* Tombstones ARE returned on an incremental read — that is how a delete
        made on one device reaches another. A first read (p_since null) skips
        them, because a mark deleted last week is not news. */
     and (p_since is not null or a.deleted_at is null)
     and (a.author_id = uid
          or (
            not me.solo
            and not coalesce((select p.invisible from pilot_profiles p where p.user_id = a.author_id), false)
            and not exists (select 1 from blocks b where b.user_id = uid and b.blocked_id = a.author_id)
            and not exists (select 1 from blocks b where b.user_id = a.author_id and b.blocked_id = uid)
            and not exists (select 1 from mutes m where m.user_id = uid and m.muted_id = a.author_id)
            /* R9, unchanged since 0014 — the kind decides, not the ring. */
            and (case when a.kind = 'correction' then me.staff
                      else ring_covers(a.author_id, uid, a.ring, a.module_code) end)
          ))
   order by a.created_at;
$$;

-- Agreeing is a counter, not a row: one statement, no read-modify-write, so two
-- people agreeing in the same second both count.
create or replace function agree_with_mark(p_id uuid)
returns int
language sql
volatile
as $$
  update paper_annotations set agree_count = agree_count + 1, updated_at = now()
   where id = p_id returning agree_count;
$$;


-- ############################################################################
-- 0019_paper_scope.sql
-- ############################################################################

-- 0019 — who a paper is for.
--
-- Adding a paper is open to everybody, and what differs is who else can see it:
--
--   solo       your own copy. Nobody else, ever.
--   formation  the people you fly with.
--   module     everybody studying this module — STAFF ONLY.
--
-- The last one is the whole reason this migration exists. A student adding
-- their own notes is a personal act and should need no permission; a student
-- putting a document in front of the entire cohort is a publishing act, and
-- one mislabelled or copyrighted file reaches everyone at once. So the first
-- two are open and the third is gated.
--
-- It is gated HERE, in the function, and not in the browser. A check in the UI
-- is a suggestion; `add_paper` refuses a module-wide paper from a non-staff
-- caller and returns the scope it actually used, so a client that asks for
-- more than it may have gets an honest answer rather than a silent success.

alter table papers add column if not exists visibility text not null default 'solo'
  check (visibility in ('solo','formation','module'));
alter table papers add column if not exists owner_id text;

-- Existing rows (there are none yet) belong to whoever uploaded them.
update papers set owner_id = uploaded_by where owner_id is null;

create index if not exists papers_visible on papers (module_code, visibility);

-- ---------------------------------------------------------------------------
-- Reading: the same ring rule the marks use, so there is one opinion in this
-- codebase about what "formation" means. 0014's ring_covers does the work.
drop function if exists papers_for(text, text);

create function papers_for(uid text, p_module text)
returns table (
  id text, module_code text, chapter_id text, title text, file_path text,
  pages int, bytes bigint, version int, status text, visibility text,
  linearized boolean, has_text boolean, manifest jsonb, failure text,
  owner_id text, owner_name text, mine boolean,
  created_at timestamptz, updated_at timestamptz
)
language sql
stable
as $$
  select p.id, p.module_code, p.chapter_id, p.title, p.file_path,
         p.pages, p.bytes, p.version, p.status, p.visibility,
         p.linearized, p.has_text, p.manifest, p.failure,
         p.owner_id,
         case when p.owner_id = uid then 'You'
              else coalesce(pp.callsign, pp.real_name, 'Someone') end,
         (p.owner_id = uid),
         p.created_at, p.updated_at
    from papers p
    left join pilot_profiles pp on pp.user_id = p.owner_id
   where p.module_code = p_module
     and (p.owner_id = uid
          or ring_covers(coalesce(p.owner_id, ''), uid, p.visibility, p.module_code))
   order by p.visibility desc, p.created_at;
$$;

-- ---------------------------------------------------------------------------
-- Writing: one statement that decides the scope rather than trusting the one
-- it was handed. Returns the row as stored, so the client can see what it got.
/* Dropped and recreated rather than replaced: a function's OUT columns cannot
   be renamed in place, and these had to be — see the note below. */
drop function if exists add_paper(text, text, text, text, text, text, int, bigint, text, boolean, boolean, jsonb);

create function add_paper(
  uid text, p_id text, p_module text, p_chapter text, p_title text,
  p_file text, p_pages int, p_bytes bigint, p_visibility text,
  p_linearized boolean, p_has_text boolean, p_manifest jsonb
)
/* THE OUT COLUMNS ARE NOT CALLED `id` OR `visibility`.

   plpgsql puts a RETURNS TABLE column into the same namespace as the table's
   own columns, so `on conflict (id)` and `where papers.owner_id = uid` became
   "column reference id is ambiguous" the first time a real upload ran. Naming
   them for what they are — the paper that was made, the scope it was given —
   removes the collision rather than papering over it with aliases. */
returns table (made_id text, made_visibility text, made_status text, downgraded boolean)
language plpgsql
volatile
as $$
declare
  staff boolean;
  want  text;
  used  text;
begin
  select coalesce((select pr.is_staff from pilot_profiles pr where pr.user_id = uid), false) into staff;
  want := coalesce(p_visibility, 'solo');
  if want not in ('solo','formation','module') then want := 'solo'; end if;
  -- Module-wide is a publishing act. Anybody may ASK for it; only staff get it.
  used := case when want = 'module' and not staff then 'formation' else want end;

  insert into papers (id, module_code, chapter_id, title, file_path, pages, bytes,
                      status, visibility, linearized, has_text, manifest,
                      uploaded_by, owner_id)
  values (p_id, p_module, nullif(p_chapter, ''), p_title, p_file, p_pages, p_bytes,
          'pending', used, p_linearized, p_has_text, p_manifest, uid, uid)
  on conflict (id) do update set
    title = excluded.title, chapter_id = excluded.chapter_id,
    file_path = excluded.file_path, pages = excluded.pages, bytes = excluded.bytes,
    visibility = excluded.visibility, linearized = excluded.linearized,
    has_text = excluded.has_text, manifest = excluded.manifest,
    status = 'pending', updated_at = now()
  where papers.owner_id = uid or papers.owner_id is null;

  return query
    select p_id, used, 'pending'::text, (used <> want);
end $$;

-- Marking one ready, or failed, and only by the person who owns it.
create or replace function paper_status(uid text, p_id text, p_status text, p_failure text default null)
returns void
language sql
volatile
as $$
  update papers set status = p_status, failure = p_failure, updated_at = now()
   where id = p_id and owner_id = uid
     and p_status in ('pending','ready','failed');
$$;

create or replace function delete_paper(uid text, p_id text)
returns boolean
language sql
volatile
as $$
  with gone as (delete from papers where id = p_id and owner_id = uid returning 1)
  select count(*) > 0 from gone;
$$;


-- ############################################################################
-- 0020_reader_tools.sql
-- ############################################################################

-- 0020 — the last of the tool table.
--
-- NOT RUN. 0018's header states the standing instruction and it still holds:
-- migrations are written, reviewed and left, and run by hand after checking.
-- `npm run sql -- supabase/migrations/0020_reader_tools.sql --yes` applies it.
--
-- Everything here is ADDITIVE. No column is dropped, no row is touched, every
-- existing stroke and mark keeps working, and the reader works without it —
-- three tools are simply less than they could be until it runs. Each section
-- says which tool and what it gains.
--
-- ---------------------------------------------------------------------------
-- 1. A TAPE MEASURE YOU CAN KEEP
--
-- paper_ink says what a stroke LOOKS like and cannot say what it IS: its tool
-- CHECK is ('pen','marker'), which is the two ways a nib lays colour down.
-- That is right for a nib and wrong for everything else the tool table has.
--
-- Today the reader works round it honestly rather than lying: a Shape is
-- stored as its own points, so a box comes back a box with nothing having to
-- say so, and Measure keeps nothing at all — it reads the page while you drag
-- and lets go, because a kept measurement would come back as a plain line with
-- its number gone, which is worse than a tape measure that does not pretend.
--
-- With this, a measurement is a stroke that knows it is one and can draw its
-- own length again; a shape can be re-edited rather than only redrawn; and a
-- text box could live here instead of as an anchored mark, if that ever turns
-- out to be the better home for it.

alter table paper_ink drop constraint if exists paper_ink_tool_check;
alter table paper_ink add constraint paper_ink_tool_check
  check (tool in ('pen','marker','shape','text','measure'));

-- Which figure a shape is, and which reading a measurement took. Null for a
-- freehand stroke, which has no variant and never will.
alter table paper_ink add column if not exists variant text;

-- ---------------------------------------------------------------------------
-- 2. THE OPACITY A STUDENT CHOSE
--
-- Every drawing tool has an opacity slider and none of them keeps it: the
-- value is applied to the live stroke and dropped on the way to the database,
-- so a marker drawn at 55% comes back at whatever the stylesheet says. The
-- slider has been a live-preview control since the tool bar was wired.
--
-- A fraction rather than a percentage, to match `width`, which is already a
-- fraction of the page.

alter table paper_ink add column if not exists opacity real not null default 1
  check (opacity > 0 and opacity <= 1);

-- ---------------------------------------------------------------------------
-- 3. LINK
--
-- The one tool in the table with no behaviour at all, and the only one whose
-- gap is a schema gap rather than a missing afternoon. A link is a passage
-- plus a target, the passage is an anchor like any other, and the target is
-- either a page in this paper or a URL — so it needs a kind and nothing else.
-- `body` already holds the target, the way a question's body holds the
-- question.
--
-- The kind CHECK is replaced rather than added to, because a constraint
-- cannot be widened in place. Dropping it for the instant between is safe for
-- the reason 0017's header gives: the kinds come from a constant list in the
-- client, so nothing can insert an invalid one in that window.

alter table paper_annotations drop constraint if exists paper_annotations_kind_check;
alter table paper_annotations add constraint paper_annotations_kind_check
  check (kind in ('highlight','underline','strikethrough','note','question',
                  'correction','shape','text','stamp','link'));

-- ---------------------------------------------------------------------------
-- WHAT DOES NOT CHANGE
--
-- R1 is untouched. `anchor_is_text_only` still refuses any anchor carrying a
-- page, a rect or a bbox, and paper_ink still has no anchor column to smuggle
-- a position into an annotation through. A link anchors to words like every
-- other mark; a measurement is coordinates like every other stroke; and the
-- line between the two tables is exactly where it was.


-- ############################################################################
-- 0021_close_the_tables.sql
-- ############################################################################

-- 0021 — the anon key stops being a skeleton key.
--
-- WHAT WAS WRONG, measured rather than reasoned about. The key compiled into
-- the public bundle at wingman.institute is, by design, not a secret: anybody
-- can read it out of /assets/index-*.js in one devtools tab. Every table then
-- answered it directly, because every table carries an open `using (true)`
-- policy. So this, from anywhere, with no login and no session:
--
--   curl "$URL/rest/v1/paper_annotations?select=*" -H "apikey: $ANON_KEY"
--
-- returned every row: the author's Clerk id in the clear, the full anchor with
-- the exact words they marked, and the body of every private note. The same
-- for paper_ink and for user_progress, which is every student's whole progress
-- blob. See docs/audit-pdf.md, P0-1.
--
-- WHAT THIS DOES. The three tables stop answering REST at all, and everything
-- the app needs from them moves behind SECURITY DEFINER functions that run as
-- the owner. Reads keep the ring rules they already had — 0018's
-- paper_marks_for already nulls the author of an anonymous mark, and that was
-- never the hole. Writes gain something they did not have: the author_id is
-- set by the function from its own uid argument rather than accepted from the
-- client, and every update and delete is scoped to `author_id = uid`, so one
-- account can no longer edit or destroy another's marks by id.
--
-- WHAT THIS DOES NOT DO, said plainly because a half-fix described as a whole
-- one is worse than no fix. The uid is still a parameter the caller chooses.
-- After this migration an attacker must know a specific classmate's Clerk id
-- and ask for one paper at a time, instead of dumping the cohort in a single
-- request — and the place those Clerk ids were being handed out is precisely
-- what closes here. That is a large reduction and it is not airtight. Airtight
-- needs the request to carry an identity Postgres can verify, which means
-- Clerk as a Supabase third-party auth provider and policies on
-- `auth.jwt()->>'sub'`. That is a dashboard change plus a client change; see
-- the note at the foot of this file. Until then, treat uid as asserted.
--
-- ORDER OF OPERATIONS. Run this BEFORE deploying the client that calls the new
-- functions, or after — either is safe. The client tries the RPC first and
-- falls back to the direct table write, so it works on both sides of this
-- migration; once the revoke below lands, the fallback can no longer succeed
-- and is dead code to be removed.
--
-- 0020 is independent of this file and still unrun. Nothing here needs it.

-- ---------------------------------------------------------------------------
-- 1. The readers keep working once the tables are shut.
--
-- ALTER rather than CREATE OR REPLACE on purpose: re-stating a function body
-- here would be a second copy of 0014's and 0018's rules, free to drift from
-- them. Changing only the security mode cannot drift.
--
-- search_path is pinned on every one of them. A SECURITY DEFINER function that
-- resolves its own table names through the caller's search_path is how a
-- definer function becomes a privilege ladder.

alter function ring_covers(text, text, text, text)              security definer;
alter function ring_covers(text, text, text, text)              set search_path = public, pg_temp;

alter function paper_marks_for(text, text, timestamptz)         security definer;
alter function paper_marks_for(text, text, timestamptz)         set search_path = public, pg_temp;

alter function paper_ink_for(text, text)                        security definer;
alter function paper_ink_for(text, text)                        set search_path = public, pg_temp;

alter function paper_corrections_for(text, text)                security definer;
alter function paper_corrections_for(text, text)                set search_path = public, pg_temp;

alter function paper_annotation_status(uuid, text)              security definer;
alter function paper_annotation_status(uuid, text)              set search_path = public, pg_temp;

alter function merge_progress(text, jsonb)                      security definer;
alter function merge_progress(text, jsonb)                      set search_path = public, pg_temp;

-- Dead but still standing, per CLAUDE.md. Left reachable so that dropping it
-- stays a separate decision from this one.
do $$ begin
  if exists (select 1 from pg_proc where proname = 'paper_annotations_for') then
    execute 'alter function paper_annotations_for(text, text, timestamptz) security definer';
    execute 'alter function paper_annotations_for(text, text, timestamptz) set search_path = public, pg_temp';
  end if;
end $$;

-- 0018's agree counter writes to a table that is about to be shut.
do $$ begin
  if exists (select 1 from pg_proc where proname = 'agree_with_mark') then
    execute 'alter function agree_with_mark(uuid) security definer';
    execute 'alter function agree_with_mark(uuid) set search_path = public, pg_temp';
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- 2. Writing moves behind functions that know whose row it is.
--
-- The shape mirrors what the client already sends, so the call sites change
-- from .from().insert() to .rpc() and nothing else. The difference that
-- matters is not visible in the signature: author_id comes from uid, and the
-- client cannot set it to somebody else.

create or replace function paper_mark_add(
  uid         text,
  p_paper     text,
  p_module    text,
  p_kind      text default 'highlight',
  p_ring      text default 'module',
  p_body      text default null,
  p_thread_id text default null,
  p_colour    text default null,
  p_anchor    jsonb default null,
  p_hint      jsonb default null,
  p_anonymous boolean default null,
  p_id        uuid default null
)
returns paper_annotations
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare row paper_annotations;
begin
  if uid is null or uid = '' or p_paper is null or p_anchor is null then
    return null;
  end if;
  insert into paper_annotations
    (id, paper_id, module_code, author_id, kind, ring, body, thread_id, colour, anchor, hint, anonymous)
  values
    (coalesce(p_id, gen_random_uuid()), p_paper, p_module,
     /* NOT from the client. This is the whole point of the function. */
     uid,
     p_kind, p_ring, p_body, p_thread_id, p_colour, p_anchor, p_hint,
     /* §6.2 of the brief: a question is anonymous unless told otherwise. The
        author is still stored — instructors can see who asked — it is simply
        not handed to classmates, which 0018's reader already enforces. */
     coalesce(p_anonymous, p_kind = 'question' or p_colour = 'unsure', false))
  returning * into row;
  return row;
end $$;

-- A patch rather than a column per call, because that is the shape the reader
-- already uses for restyling and for answering. The whitelist is here so that
-- "edit your mark" can never widen into "edit your author_id".
create or replace function paper_mark_edit(uid text, p_id uuid, p_patch jsonb)
returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare n int;
begin
  if uid is null or p_id is null or p_patch is null then return false; end if;
  update paper_annotations a set
    body        = case when p_patch ? 'body'        then nullif(p_patch->>'body', '')        else a.body end,
    colour      = case when p_patch ? 'colour'      then p_patch->>'colour'                  else a.colour end,
    ring        = case when p_patch ? 'ring'        then p_patch->>'ring'                    else a.ring end,
    kind        = case when p_patch ? 'kind'        then p_patch->>'kind'                    else a.kind end,
    style       = case when p_patch ? 'style'       then p_patch->'style'                    else a.style end,
    hint        = case when p_patch ? 'hint'        then p_patch->'hint'                     else a.hint end,
    anonymous   = case when p_patch ? 'anonymous'   then (p_patch->>'anonymous')::boolean    else a.anonymous end,
    resolved_at = case when p_patch ? 'resolved_at' then (p_patch->>'resolved_at')::timestamptz else a.resolved_at end,
    updated_at  = now()
   where a.id = p_id
     /* the sentence this migration exists to write */
     and a.author_id = uid;
  get diagnostics n = row_count;
  return n > 0;
end $$;

create or replace function paper_mark_delete(uid text, p_id uuid)
returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare n int;
begin
  if uid is null or p_id is null then return false; end if;
  delete from paper_annotations where id = p_id and author_id = uid;
  get diagnostics n = row_count;
  return n > 0;
end $$;

create or replace function paper_ink_add(
  uid      text,
  p_paper  text,
  p_module text,
  p_page   int,
  p_points jsonb,
  p_tool   text default 'pen',
  p_colour text default 'graphite',
  p_width  real default 0.0032,
  p_ring   text default 'solo',
  p_id     uuid default null
)
returns paper_ink
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare row paper_ink;
begin
  if uid is null or uid = '' or p_paper is null or p_page is null or p_points is null then
    return null;
  end if;
  insert into paper_ink (id, paper_id, module_code, author_id, page, tool, colour, width, ring, points)
  values (coalesce(p_id, gen_random_uuid()), p_paper, p_module, uid,
          p_page, p_tool, p_colour, p_width, p_ring, p_points)
  returning * into row;
  return row;
end $$;

-- Plural because the eraser hits whatever it touches, and one round trip beats
-- six. Scoped to the caller's own strokes, so an eraser cannot reach across
-- accounts however the ids were come by.
create or replace function paper_ink_delete(uid text, p_ids uuid[])
returns int
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare n int;
begin
  if uid is null or p_ids is null or array_length(p_ids, 1) is null then return 0; end if;
  delete from paper_ink where id = any(p_ids) and author_id = uid;
  get diagnostics n = row_count;
  return n;
end $$;

-- user_progress is read on every mount by the progress provider and cleared
-- from the account screen. Both moved behind the same door as the rest.
create or replace function progress_for(uid text)
returns jsonb
language sql
security definer
set search_path = public, pg_temp
stable
as $$
  select coalesce((select p.data from user_progress p where p.user_id = uid), '{}'::jsonb);
$$;

create or replace function progress_clear(uid text)
returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if uid is null or uid = '' then return false; end if;
  delete from user_progress where user_id = uid;
  return true;
end $$;

-- ---------------------------------------------------------------------------
-- 3. The doors.
--
-- EXECUTE to the roles PostgREST actually uses, then the tables themselves are
-- taken away from both. A revoke rather than a `using (false)` policy on
-- purpose: a policy that filters everything out returns `[]`, which reads like
-- "there is no data". A revoke returns "permission denied for table", which
-- reads like what it is.

grant execute on function
  paper_mark_add(text, text, text, text, text, text, text, text, jsonb, jsonb, boolean, uuid),
  paper_mark_edit(text, uuid, jsonb),
  paper_mark_delete(text, uuid),
  paper_ink_add(text, text, text, int, jsonb, text, text, real, text, uuid),
  paper_ink_delete(text, uuid[]),
  progress_for(text),
  progress_clear(text)
to anon, authenticated;

-- The open policies go. They are not what grants access — the table privilege
-- is — but leaving a policy saying `using (true)` next to a revoked grant is
-- an invitation for the next person to re-grant and wonder why it is fine.
drop policy if exists paper_annotations_all  on paper_annotations;
drop policy if exists paper_annotations_open on paper_annotations;
drop policy if exists paper_ink_all          on paper_ink;
drop policy if exists paper_ink_open         on paper_ink;
drop policy if exists user_progress_open     on user_progress;

alter table paper_annotations enable row level security;
alter table paper_ink         enable row level security;
alter table user_progress     enable row level security;

-- No policy at all, with RLS on, denies everything to anyone who is not the
-- owner or a definer function. That is exactly the shape we want.

revoke all on table paper_annotations from anon, authenticated;
revoke all on table paper_ink         from anon, authenticated;
revoke all on table user_progress     from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 4. Proof, run at migration time rather than trusted.
--
-- If any of the three still answers the anon role, this migration fails rather
-- than reporting success on a hole it did not close.
do $$
declare t text;
begin
  foreach t in array array['paper_annotations', 'paper_ink', 'user_progress'] loop
    if has_table_privilege('anon', t, 'SELECT') then
      raise exception '0021 did not close %: anon can still SELECT it', t;
    end if;
    if has_table_privilege('anon', t, 'INSERT')
    or has_table_privilege('anon', t, 'UPDATE')
    or has_table_privilege('anon', t, 'DELETE') then
      raise exception '0021 did not close %: anon can still write to it', t;
    end if;
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- WHAT IS LEFT, and it is the next piece of work rather than a footnote.
--
-- Every other table in this database is still open to the anon key, including
-- pilot_profiles, lesson_threads, lesson_replies and chapter_completions. This
-- migration closes the three the papers reader owns, which is the surface that
-- was audited; closing the rest means moving roughly thirty call sites behind
-- functions and re-verifying every screen, and doing it blind in one pass is
-- how a working app stops working.
--
-- And the real end state, for whoever picks this up:
--
--   1. Supabase dashboard -> Authentication -> Third-Party Auth -> add Clerk.
--   2. Clerk dashboard -> the session token gains a `role: "authenticated"`
--      claim.
--   3. src/lib/supabaseClient.js sends the Clerk session token as the bearer
--      instead of the anon key.
--   4. Then, and only then, `auth.jwt()->>'sub'` is a Clerk user id Postgres
--      can trust, every `uid text` argument above becomes redundant, and these
--      functions can be rewritten as RLS policies that cannot be lied to.
--
-- Do not do 3 before 1 and 2, or every data call in the app fails at once.


-- ############################################################################
-- 0022_ready_room.sql
-- ############################################################################

-- 0022 — the Ready Room, made to work.
--
-- Run after 0021. Safe to re-run. Adds columns to four existing tables, creates
-- three tables and fourteen functions. Alters no existing column and drops
-- nothing.
--
-- ===========================================================================
-- WHY THIS FILE EXISTS
-- ===========================================================================
-- The room shipped with controls that had nothing behind them. "Create one" on
-- the discovery screen called a handler App never supplied, and there was no
-- create_squadron to supply it with. "Ask to fly" emitted an event nobody
-- handled, and there was no table for a request to live in. comms_reactions
-- has existed since 0005 with no writer, copilot_sessions since 0001 with no
-- writer. Read state lived in localStorage, so it never followed anyone to a
-- second device.
--
-- Every function here follows 0009 and 0011: the rule lives in SQL, not in the
-- client. auth.uid() is NULL on every request in this architecture and the
-- browser holds the anon key, so a boundary expressed as "the UI does not call
-- that endpoint" is not a boundary. Membership, capacity, blocks and the
-- shared-squadron rule for the right seat are all decided in here.
--
-- THE RIGHT SEAT'S RULE, restated once because it is the one with teeth: you
-- may only ask to fly with somebody you already share a squadron with. 0009
-- states it for presence; request_right_seat states it for the request. Both
-- read the same my_squadron_ids.

-- ============================================================ 1 · squadrons
-- A squadron made by a student, rather than assigned. The columns discovery
-- added in 0011 have been sitting unused because nothing wrote them: the
-- client built a display name out of the module code instead.
alter table squadrons add column if not exists created_by text;

-- Per member, not per squadron: muting is one person's decision and read state
-- is one person's place. Both were client-side and therefore per-device.
alter table squadron_members add column if not exists muted        boolean     not null default false;
alter table squadron_members add column if not exists last_read_at timestamptz not null default now();
alter table squadron_members add column if not exists role         text        not null default 'member';
do $$ begin
  alter table squadron_members add constraint squadron_members_role_known
    check (role in ('member', 'owner', 'staff'));
exception when duplicate_object then null; end $$;

-- ============================================================= 2 · messages
-- reply_to is the quoted message every chat app has and this one did not, so a
-- thirty-message morning had no way to say which line an answer belonged to.
-- deleted_at is a tombstone rather than a DELETE: a removed message that
-- vanishes from the middle of a transcript reads as a bug to everyone who saw
-- it, and realtime carries an UPDATE more cheaply than a DELETE.
alter table comms_messages add column if not exists reply_to   uuid references comms_messages (id) on delete set null;
alter table comms_messages add column if not exists deleted_at timestamptz;
alter table comms_messages add column if not exists pinned_at  timestamptz;
alter table comms_messages add column if not exists pinned_by  text;
create index if not exists comms_messages_sq_created_idx
  on comms_messages (squadron_id, created_at desc) where squadron_id is not null;

-- ============================================================== 3 · answers
-- One level, and one level only. nestAnswers has been deriving a hierarchy
-- from flat data since 0008 and honestly returning everything flat, because
-- there was no column to hang it on. There is one now, and it is deliberately
-- not recursive: a reply whose parent is itself a reply is re-pointed at the
-- top-level answer, in the function, so the schema cannot grow a thread that
-- breaks on a phone.
alter table lesson_replies add column if not exists parent_id text references lesson_replies (id) on delete cascade;
create index if not exists lesson_replies_parent_idx on lesson_replies (parent_id) where parent_id is not null;

-- A vote on the QUESTION, not only on the answers. lesson_reply_votes (0010)
-- covers answers; a feed where the question cannot be voted has no way to
-- surface the one everybody is stuck on.
create table if not exists thread_votes (
  thread_id  text        not null references lesson_threads (id) on delete cascade,
  user_id    text        not null,
  dir        smallint    not null check (dir in (-1, 1)),
  created_at timestamptz not null default now(),
  primary key (thread_id, user_id)
);
alter table thread_votes enable row level security;
do $$ begin
  create policy thread_votes_all on thread_votes for all using (true) with check (true);
exception when duplicate_object then null; end $$;

-- ============================================================ 4 · right seat
-- A request is not a session. Nothing auto-pairs anybody: the person asked has
-- to answer, and an unanswered request expires rather than sitting open for a
-- week. One pending request per pair at a time — the UI says "asked, waiting"
-- and that has to be true rather than a fifth row.
create table if not exists seat_requests (
  id         uuid        primary key default gen_random_uuid(),
  from_id    text        not null,
  to_id      text        not null,
  state      text        not null default 'pending'
               check (state in ('pending', 'accepted', 'declined', 'expired', 'cancelled')),
  session_id uuid        references copilot_sessions (id) on delete set null,
  created_at timestamptz not null default now(),
  answered_at timestamptz,
  check (from_id <> to_id)
);
create unique index if not exists seat_requests_one_pending
  on seat_requests (from_id, to_id) where state = 'pending';
create index if not exists seat_requests_to_idx on seat_requests (to_id, state);
alter table seat_requests enable row level security;
do $$ begin
  create policy seat_requests_all on seat_requests for all using (true) with check (true);
exception when duplicate_object then null; end $$;

-- The session itself. copilot_sessions has existed since 0001 and nothing ever
-- opened one. These three columns are what makes it a right seat rather than a
-- log line: where each person is, and when the pair last did anything.
alter table copilot_sessions add column if not exists last_active_at timestamptz not null default now();
alter table copilot_participants add column if not exists at_module  text;
alter table copilot_participants add column if not exists at_place   text;
alter table copilot_participants add column if not exists at_since   timestamptz not null default now();

-- Session-scoped chat. Deliberately its own table and not comms_messages: it
-- is deleted when the seat empties, and mixing it into the squadron transcript
-- would make a thing that vanishes live next to a thing that does not.
create table if not exists seat_messages (
  id         uuid        primary key default gen_random_uuid(),
  session_id uuid        not null references copilot_sessions (id) on delete cascade,
  user_id    text        not null,
  body       text        not null check (length(btrim(body)) > 0),
  kept       boolean     not null default false,
  created_at timestamptz not null default now()
);
create index if not exists seat_messages_session_idx on seat_messages (session_id, created_at);
alter table seat_messages enable row level security;
do $$ begin
  create policy seat_messages_all on seat_messages for all using (true) with check (true);
exception when duplicate_object then null; end $$;

-- =========================================================== 5 · squadrons()
-- CREATE. The one door: it makes the room, puts the maker in it as owner, and
-- mints the invite token in the same statement. A client that made the row and
-- then added itself would leave an ownerless squadron behind every time the
-- second call failed.
create or replace function create_squadron(
  p_me text, p_name text, p_module text,
  p_blurb text default null, p_policy text default 'invite_only'
) returns uuid language plpgsql security definer as $$
declare v_id uuid; v_token text;
begin
  if p_me is null or btrim(coalesce(p_name,'')) = '' or btrim(coalesce(p_module,'')) = '' then
    return null;
  end if;
  if coalesce(p_policy,'') not in ('open','request','invite_only') then
    p_policy := 'invite_only';
  end if;
  -- Not unlimited. A student who can mint rooms in a loop can fill discovery
  -- with them, and discovery is the screen a newcomer trusts most.
  if (select count(*) from squadrons
        where created_by = p_me and created_at > now() - interval '1 day') >= 5 then
    return null;
  end if;
  v_token := lower(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
  insert into squadrons (module_code, name, blurb, owner_id, created_by, join_policy, invite_token, status)
  values (upper(btrim(p_module)), btrim(p_name), nullif(btrim(coalesce(p_blurb,'')), ''),
          p_me, p_me, p_policy, v_token, 'forming')
  returning id into v_id;
  insert into squadron_members (squadron_id, user_id, role)
  values (v_id, p_me, 'owner')
  on conflict do nothing;
  return v_id;
end $$;

-- LEAVE. The last member out takes the room with them, because an empty
-- squadron in discovery is a door into nowhere. Ownership passes to the
-- longest-standing member instead of the room becoming unadministered.
create or replace function leave_squadron(p_me text, p_squadron uuid)
returns text language plpgsql security definer as $$
declare v_left integer; v_next text; v_owner text;
begin
  if p_me is null or p_squadron is null then return 'missing'; end if;
  delete from squadron_members where squadron_id = p_squadron and user_id = p_me;
  if not found then return 'not_a_member'; end if;
  select count(*) into v_left from squadron_members where squadron_id = p_squadron;
  if v_left = 0 then
    delete from squadrons where id = p_squadron;
    return 'closed';
  end if;
  select owner_id into v_owner from squadrons where id = p_squadron;
  if v_owner = p_me then
    select user_id into v_next from squadron_members
      where squadron_id = p_squadron order by joined_at asc limit 1;
    update squadrons set owner_id = v_next where id = p_squadron;
    update squadron_members set role = 'owner'
      where squadron_id = p_squadron and user_id = v_next;
  end if;
  return 'left';
end $$;

create or replace function set_squadron_muted(p_me text, p_squadron uuid, p_muted boolean)
returns boolean language sql security definer as $$
  update squadron_members set muted = coalesce(p_muted, false)
   where squadron_id = p_squadron and user_id = p_me
  returning muted;
$$;

create or replace function rename_squadron(p_me text, p_squadron uuid, p_name text, p_blurb text default null)
returns boolean language plpgsql security definer as $$
begin
  if btrim(coalesce(p_name,'')) = '' then return false; end if;
  update squadrons
     set name = btrim(p_name),
         blurb = coalesce(nullif(btrim(coalesce(p_blurb,'')), ''), blurb)
   where id = p_squadron and owner_id = p_me;
  return found;
end $$;

-- A fresh link, and the old one stops working the moment it is called. This is
-- the control behind "someone shared it who shouldn't have".
create or replace function revoke_invite(p_me text, p_squadron uuid)
returns text language plpgsql security definer as $$
declare v_token text;
begin
  v_token := lower(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
  update squadrons
     set invite_token = v_token, invite_revoked_at = null, invite_expires_at = null
   where id = p_squadron and owner_id = p_me;
  if not found then return null; end if;
  return v_token;
end $$;

-- READ STATE, and it lives on the server so it follows the student to their
-- phone. The client passed a localStorage map called pw-room-seen, which meant
-- every badge lit again on a second device.
create or replace function mark_squadron_read(p_me text, p_squadron uuid)
returns timestamptz language sql security definer as $$
  update squadron_members set last_read_at = now()
   where squadron_id = p_squadron and user_id = p_me
  returning last_read_at;
$$;

-- ============================================================ 6 · messages()
create or replace function toggle_message_reaction(p_me text, p_message uuid, p_emoji text)
returns boolean language plpgsql security definer as $$
begin
  if p_me is null or p_message is null or btrim(coalesce(p_emoji,'')) = '' then return false; end if;
  -- A member of the squadron the message is in, and nobody else.
  if not exists (
    select 1 from comms_messages m
      join squadron_members sm on sm.squadron_id = m.squadron_id and sm.user_id = p_me
     where m.id = p_message) then
    return false;
  end if;
  delete from comms_reactions where message_id = p_message and user_id = p_me and emoji = p_emoji;
  if found then return false; end if;
  insert into comms_reactions (message_id, user_id, emoji) values (p_message, p_me, p_emoji);
  return true;
end $$;

-- ONE PIN PER SQUADRON. A list of pinned messages is a second inbox; a single
-- pin is a notice board, which is what a study group actually uses it for.
create or replace function pin_message(p_me text, p_message uuid, p_on boolean default true)
returns boolean language plpgsql security definer as $$
declare v_sq uuid;
begin
  select squadron_id into v_sq from comms_messages where id = p_message;
  if v_sq is null then return false; end if;
  if not exists (select 1 from squadron_members where squadron_id = v_sq and user_id = p_me) then
    return false;
  end if;
  update comms_messages set pinned_at = null, pinned_by = null
   where squadron_id = v_sq and pinned_at is not null;
  if coalesce(p_on, true) then
    update comms_messages set pinned_at = now(), pinned_by = p_me where id = p_message;
  end if;
  return true;
end $$;

-- Your own, and within the window where an edit is a correction rather than a
-- rewrite of what somebody replied to.
create or replace function edit_message(p_me text, p_message uuid, p_body text)
returns boolean language plpgsql security definer as $$
begin
  if btrim(coalesce(p_body,'')) = '' then return false; end if;
  update comms_messages set body = btrim(p_body), edited_at = now()
   where id = p_message and user_id = p_me and deleted_at is null
     and created_at > now() - interval '15 minutes';
  return found;
end $$;

create or replace function delete_message(p_me text, p_message uuid)
returns boolean language plpgsql security definer as $$
begin
  update comms_messages set deleted_at = now(), body = null, pinned_at = null, pinned_by = null
   where id = p_message and user_id = p_me and deleted_at is null;
  return found;
end $$;

-- ============================================================= 7 · answers()
create or replace function toggle_thread_vote(p_me text, p_thread text, p_dir smallint)
returns smallint language plpgsql security definer as $$
declare v_now smallint;
begin
  if p_me is null or p_thread is null then return 0; end if;
  select dir into v_now from thread_votes where thread_id = p_thread and user_id = p_me;
  if v_now is not null and v_now = p_dir then
    delete from thread_votes where thread_id = p_thread and user_id = p_me;
    return 0;
  end if;
  if p_dir not in (-1, 1) then
    delete from thread_votes where thread_id = p_thread and user_id = p_me;
    return 0;
  end if;
  insert into thread_votes (thread_id, user_id, dir) values (p_thread, p_me, p_dir)
  on conflict (thread_id, user_id) do update set dir = excluded.dir;
  return p_dir;
end $$;

create or replace function thread_vote_counts(p_threads text[], p_me text)
returns table (thread_id text, score bigint, mine smallint)
language sql stable as $$
  select t.thread_id,
         coalesce(sum(t.dir), 0)::bigint,
         coalesce(max(case when t.user_id = p_me then t.dir end), 0)::smallint
    from thread_votes t
   where t.thread_id = any (p_threads)
   group by t.thread_id;
$$;

-- ========================================================== 8 · right seat()
-- ASK. The shared-squadron rule is checked here, not in the component, and a
-- block in either direction refuses the request without saying which.
create or replace function request_right_seat(p_me text, p_them text)
returns text language plpgsql security definer as $$
declare v_id uuid;
begin
  if p_me is null or p_them is null or p_me = p_them then return 'missing'; end if;
  if exists (select 1 from blocks
              where (user_id = p_me and blocked_id = p_them)
                 or (user_id = p_them and blocked_id = p_me)) then
    return 'unavailable';
  end if;
  if not exists (
    select 1 from squadron_members a
      join squadron_members b on b.squadron_id = a.squadron_id
     where a.user_id = p_me and b.user_id = p_them) then
    return 'not_shared';
  end if;
  -- Already flying with somebody. The right seat is one seat.
  if exists (
    select 1 from copilot_participants cp
      join copilot_sessions cs on cs.id = cp.session_id
     where cp.user_id = p_me and cp.left_at is null and cs.ended_at is null) then
    return 'already_flying';
  end if;
  -- They asked you first: answering rather than asking back is the honest
  -- resolution, so this accepts theirs instead of opening a second request.
  select id into v_id from seat_requests
   where from_id = p_them and to_id = p_me and state = 'pending' limit 1;
  if v_id is not null then
    perform answer_right_seat(p_me, v_id, true);
    return 'accepted';
  end if;
  insert into seat_requests (from_id, to_id) values (p_me, p_them)
  on conflict do nothing;
  return 'asked';
end $$;

create or replace function cancel_right_seat(p_me text, p_them text)
returns boolean language plpgsql security definer as $$
begin
  update seat_requests set state = 'cancelled', answered_at = now()
   where from_id = p_me and to_id = p_them and state = 'pending';
  return found;
end $$;

-- ANSWER. Accepting is what opens the session, so there is exactly one place a
-- session can come into being and it needs two people to have agreed.
create or replace function answer_right_seat(p_me text, p_request uuid, p_accept boolean)
returns uuid language plpgsql security definer as $$
declare r seat_requests%rowtype; v_session uuid; v_mod text;
begin
  select * into r from seat_requests where id = p_request and to_id = p_me and state = 'pending';
  if r.id is null then return null; end if;
  if not coalesce(p_accept, false) then
    update seat_requests set state = 'declined', answered_at = now() where id = r.id;
    return null;
  end if;
  select module_code into v_mod from squadrons s
    join squadron_members a on a.squadron_id = s.id and a.user_id = r.from_id
    join squadron_members b on b.squadron_id = s.id and b.user_id = r.to_id
   limit 1;
  insert into copilot_sessions (module_code) values (coalesce(v_mod, ''))
  returning id into v_session;
  insert into copilot_participants (session_id, user_id) values (v_session, r.from_id), (v_session, r.to_id)
  on conflict do nothing;
  update seat_requests set state = 'accepted', answered_at = now(), session_id = v_session where id = r.id;
  -- Every other pending request either of them holds is now moot.
  update seat_requests set state = 'expired', answered_at = now()
   where state = 'pending' and (from_id in (r.from_id, r.to_id) or to_id in (r.from_id, r.to_id));
  return v_session;
end $$;

-- WHERE I AM, said by the client as it moves. This is what puts the partner's
-- place on the other half of the session card, and it doubles as the heartbeat
-- that keeps the seat from expiring.
create or replace function seat_heartbeat(p_me text, p_module text default null, p_place text default null)
returns uuid language plpgsql security definer as $$
declare v_session uuid;
begin
  select cs.id into v_session from copilot_participants cp
    join copilot_sessions cs on cs.id = cp.session_id
   where cp.user_id = p_me and cp.left_at is null and cs.ended_at is null
   order by cs.started_at desc limit 1;
  if v_session is null then return null; end if;
  update copilot_participants
     set at_module = coalesce(p_module, at_module),
         at_place  = coalesce(p_place, at_place),
         at_since  = case when coalesce(p_place,'') is distinct from coalesce(at_place,'')
                          then now() else at_since end
   where session_id = v_session and user_id = p_me;
  update copilot_sessions set last_active_at = now() where id = v_session;
  return v_session;
end $$;

create or replace function end_right_seat(p_me text)
returns boolean language plpgsql security definer as $$
declare v_session uuid;
begin
  select cs.id into v_session from copilot_participants cp
    join copilot_sessions cs on cs.id = cp.session_id
   where cp.user_id = p_me and cp.left_at is null and cs.ended_at is null limit 1;
  if v_session is null then return false; end if;
  update copilot_sessions set ended_at = now() where id = v_session;
  update copilot_participants set left_at = now() where session_id = v_session and left_at is null;
  -- §right seat — the session chat is deleted, not archived. Only what someone
  -- deliberately kept survives, and the client has already turned those into
  -- lesson notes by the time this runs.
  delete from seat_messages where session_id = v_session and kept = false;
  return true;
end $$;

-- THE HOUR. A seat nobody has touched for an hour is not a study session, it
-- is two closed laptops. Called opportunistically by the room's own reads, so
-- it needs no scheduler to be correct — only to be timely.
create or replace function expire_right_seats()
returns integer language plpgsql security definer as $$
declare n integer;
begin
  with dead as (
    update copilot_sessions set ended_at = now()
     where ended_at is null and last_active_at < now() - interval '1 hour'
    returning id)
  select count(*) into n from dead;
  update copilot_participants set left_at = now()
   where left_at is null and session_id in (select id from copilot_sessions where ended_at is not null);
  update seat_requests set state = 'expired', answered_at = now()
   where state = 'pending' and created_at < now() - interval '2 hours';
  delete from seat_messages
   where kept = false and session_id in (select id from copilot_sessions where ended_at is not null);
  return coalesce(n, 0);
end $$;

-- Everything the right-seat screen needs, in one round trip: the live session
-- if there is one, who is in it and where they are, and the requests waiting on
-- an answer in both directions.
create or replace function my_seat(p_me text)
returns table (
  session_id uuid, partner_id text, partner_module text, partner_place text,
  partner_since timestamptz, started_at timestamptz, last_active_at timestamptz)
language sql stable as $$
  select cs.id, other.user_id, other.at_module, other.at_place, other.at_since,
         cs.started_at, cs.last_active_at
    from copilot_participants me
    join copilot_sessions cs on cs.id = me.session_id and cs.ended_at is null
    join copilot_participants other
      on other.session_id = cs.id and other.user_id <> p_me and other.left_at is null
   where me.user_id = p_me and me.left_at is null
   order by cs.started_at desc
   limit 1;
$$;

create or replace function my_seat_requests(p_me text)
returns table (id uuid, from_id text, to_id text, created_at timestamptz, direction text)
language sql stable as $$
  select r.id, r.from_id, r.to_id, r.created_at,
         case when r.to_id = p_me then 'in' else 'out' end
    from seat_requests r
   where r.state = 'pending' and (r.to_id = p_me or r.from_id = p_me)
   order by r.created_at desc;
$$;

-- ============================================================= 9 · realtime
-- Same three reasons as 0015: a badge that arrives twenty seconds late is a
-- badge nobody believes. REPLICA IDENTITY FULL so an update carries enough of
-- the row to know which squadron it belongs to.
do $$ begin alter publication supabase_realtime add table comms_reactions; exception when others then null; end $$;
do $$ begin alter publication supabase_realtime add table seat_requests;    exception when others then null; end $$;
do $$ begin alter publication supabase_realtime add table copilot_sessions; exception when others then null; end $$;
do $$ begin alter publication supabase_realtime add table seat_messages;    exception when others then null; end $$;
do $$ begin alter publication supabase_realtime add table thread_votes;     exception when others then null; end $$;

alter table comms_reactions   replica identity full;
alter table seat_requests     replica identity full;
alter table copilot_sessions  replica identity full;
alter table seat_messages     replica identity full;
alter table thread_votes      replica identity full;

-- ========================================================= 10 · backfill
-- Existing rooms get the name their members have been reading off the module
-- code, so nothing loses an identity on the way in, and the owner row gets the
-- role the column now records.
update squadrons set name = module_code || ' squadron' where name is null or btrim(name) = '';
update squadron_members sm set role = 'owner'
  from squadrons s where s.id = sm.squadron_id and s.owner_id = sm.user_id and sm.role = 'member';
update squadrons set invite_token = lower(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8))
 where invite_token is null;


-- ############################################################################
-- 0023_reader_works.sql
-- ############################################################################

-- 0023 — the papers reader, made to work.
--
-- Run after 0022. Safe to re-run. Adds columns to two existing tables, creates
-- one table, replaces four functions and publishes two tables to realtime.
-- Alters no existing column's type and drops nothing.
--
-- ===========================================================================
-- WHY THIS FILE EXISTS
-- ===========================================================================
-- The reader has been writing around its own schema for months.
--
-- A STROKE COULD NOT BE DESCRIBED. paper_ink has a width and nothing else, so
-- opacity and cap were dropped on the way out and invented on the way back: a
-- marker drawn at 55% and a highlighter at 38% both came back fully opaque,
-- covering the words they were drawn over, and a chisel highlighter came back
-- round-capped. `tool` was `check (tool in ('pen','marker'))` while the tool
-- table has six, so the client folded six into two and a Shape was
-- indistinguishable from a pen stroke. `colour` was a CHECK over eight palette
-- names while the reader offers twenty-four free colours, so picking olive
-- stored "graphite" and the stroke turned grey the moment the save returned.
--
-- 0020_reader_tools.sql was written for some of this and its own header says
-- NOT RUN — `reader:setup` runs 0018 only. This supersedes it: every statement
-- here is `if not exists`, so running 0020 first, after, or never all end in
-- the same place.
--
-- AGREEING WAS A COUNTER WITH NO ROWS. agree_with_mark(p_id) took an id and
-- nothing else and bumped a number. It could not say whether YOU had agreed,
-- could not be taken back, and one student could press it a hundred times. It
-- was also called by nothing, which is the only reason none of that showed.
--
-- A MARK COULD BE OVERWRITTEN BY A SECOND DEVICE without either knowing. And
-- paper_annotation_status — the one paper function with no `uid` argument and
-- no ownership check — was an unauthenticated write on anybody's row, called
-- on every load for every orphan because the client's guard read a column name
-- that does not exist.
--
-- THE READER HAD NO REALTIME AT ALL. lesson_threads, lesson_replies and
-- comms_messages were published in 0015; paper_annotations and paper_ink were
-- not, so the only mechanism was a sixty-second poll that re-read every mark
-- on the paper each time.

-- ============================================================== 1 · the ink
-- What a stroke actually is. Each of these was being drawn and then thrown
-- away at the table's edge.
alter table paper_ink add column if not exists opacity real    not null default 1;
alter table paper_ink add column if not exists cap     text    not null default 'round';
alter table paper_ink add column if not exists variant smallint not null default 0;
do $$ begin
  alter table paper_ink add constraint paper_ink_opacity_range check (opacity > 0 and opacity <= 1);
exception when duplicate_object then null; end $$;
do $$ begin
  alter table paper_ink add constraint paper_ink_cap_known check (cap in ('round', 'butt', 'square'));
exception when duplicate_object then null; end $$;

-- SIX TOOLS, NOT TWO. The old CHECK named the two nibs 0017 knew about, and
-- the client has been mapping 'shp' and 'mkr' onto them to get a write through
-- — which means the table cannot tell a shape from a pen stroke, and an eraser
-- that wants to remove "the last shape" has nothing to go on.
do $$ begin
  alter table paper_ink drop constraint if exists paper_ink_tool_check;
exception when others then null; end $$;
do $$ begin
  alter table paper_ink add constraint paper_ink_tool_known
    check (tool in ('pen', 'marker', 'mkr', 'hl', 'shp', 'msr', 'snap'));
exception when duplicate_object then null; end $$;

-- A NAME OR A COLOUR, and the difference matters. The palette's eight names
-- are a design decision the stylesheet owns — graphite becomes chalk under the
-- night light, because a pencil is defined by being darker than paper. A free
-- colour has no such reading and is stored as what it is.
do $$ begin
  alter table paper_ink drop constraint if exists paper_ink_colour_check;
exception when others then null; end $$;
do $$ begin
  alter table paper_ink add constraint paper_ink_colour_known
    check (colour in ('graphite','chalk','yellow','blue','green','purple','red','pink','orange')
           or colour ~ '^#[0-9A-Fa-f]{6}$');
exception when duplicate_object then null; end $$;

-- The writer. Same name, same first arguments, three more with defaults — so a
-- client that has not been updated keeps working and simply stores the
-- defaults it was storing before.
create or replace function paper_ink_add(
  uid text, p_paper text, p_module text, p_page integer,
  p_points jsonb, p_tool text default 'pen', p_colour text default 'graphite',
  p_width real default 0.0032, p_ring text default 'solo',
  p_opacity real default 1, p_cap text default 'round',
  p_variant smallint default 0, p_id uuid default null
) returns paper_ink language plpgsql security definer as $$
declare r paper_ink%rowtype;
begin
  if uid is null or p_paper is null or p_points is null then return null; end if;
  insert into paper_ink (id, paper_id, module_code, author_id, page, points,
                         tool, colour, width, ring, opacity, cap, variant)
  values (coalesce(p_id, gen_random_uuid()), p_paper, p_module, uid, p_page, p_points,
          coalesce(p_tool, 'pen'), coalesce(p_colour, 'graphite'),
          coalesce(p_width, 0.0032), coalesce(p_ring, 'solo'),
          least(greatest(coalesce(p_opacity, 1), 0.02), 1),
          coalesce(p_cap, 'round'), coalesce(p_variant, 0))
  on conflict (id) do nothing
  returning * into r;
  return r;
end $$;

-- ============================================================ 2 · agreeing
-- A row per person per mark, so it can be taken back, counted honestly, and
-- asked "did I".
create table if not exists paper_mark_agrees (
  mark_id    uuid        not null references paper_annotations (id) on delete cascade,
  user_id    text        not null,
  created_at timestamptz not null default now(),
  primary key (mark_id, user_id)
);
alter table paper_mark_agrees enable row level security;
do $$ begin
  create policy paper_mark_agrees_all on paper_mark_agrees for all using (true) with check (true);
exception when duplicate_object then null; end $$;

-- Replaces the 0018 counter. Returns the new count, so the card shows a number
-- it did not have to guess at.
drop function if exists agree_with_mark(uuid);
create or replace function agree_with_mark(p_me text, p_id uuid, p_on boolean default true)
returns integer language plpgsql security definer as $$
declare n integer;
begin
  if p_me is null or p_id is null then return 0; end if;
  -- You cannot agree with your own mark. It is not a vote, it is a second
  -- person saying the same passage mattered to them.
  if exists (select 1 from paper_annotations where id = p_id and author_id = p_me) then
    select count(*) into n from paper_mark_agrees where mark_id = p_id;
    return coalesce(n, 0);
  end if;
  if coalesce(p_on, true) then
    insert into paper_mark_agrees (mark_id, user_id) values (p_id, p_me)
    on conflict do nothing;
  else
    delete from paper_mark_agrees where mark_id = p_id and user_id = p_me;
  end if;
  select count(*) into n from paper_mark_agrees where mark_id = p_id;
  update paper_annotations set agree_count = coalesce(n, 0) where id = p_id;
  return coalesce(n, 0);
end $$;

-- ======================================================== 3 · owning a mark
-- A VERSION, so two devices cannot silently clobber one note. paper_mark_edit
-- was last-write-wins with nothing to compare against.
alter table paper_annotations add column if not exists version integer not null default 1;

create or replace function paper_mark_edit(
  uid text, p_id uuid, p_patch jsonb, p_version integer default null
) returns paper_annotations language plpgsql security definer as $$
declare r paper_annotations%rowtype; cur integer;
begin
  select version into cur from paper_annotations where id = p_id and author_id = uid;
  if cur is null then return null; end if;
  -- Given a version, the write applies only if the row is still at it. Given
  -- none, it behaves exactly as it did before, so an older client is not
  -- broken by this migration.
  if p_version is not null and p_version <> cur then return null; end if;
  update paper_annotations
     set colour     = coalesce(p_patch->>'colour', colour),
         kind       = coalesce(p_patch->>'kind', kind),
         ring       = coalesce(p_patch->>'ring', ring),
         body       = case when p_patch ? 'body' then p_patch->>'body' else body end,
         style      = coalesce(p_patch->>'style', style),
         version    = cur + 1,
         updated_at = now()
   where id = p_id and author_id = uid
  returning * into r;
  return r;
end $$;

-- THE ONE FUNCTION WITH NO OWNER CHECK. It is called on every load for every
-- mark that lost its place, so an unauthenticated write on anybody's row went
-- out routinely. The status of a mark is a fact about the paper rather than
-- about its author, so any signed-in student may set it — but they have to say
-- who they are, and it is only ever moved to or from 'orphaned'.
create or replace function paper_annotation_status(uid text, p_id uuid, p_status text)
returns boolean language plpgsql security definer as $$
begin
  if uid is null or p_id is null then return false; end if;
  if p_status not in ('ok', 'orphaned') then return false; end if;
  update paper_annotations set status = p_status, updated_at = now()
   where id = p_id and status is distinct from p_status;
  return found;
end $$;

-- ====================================================== 4 · the right seat
-- The locked design scopes LIVE annotation to the right seat rather than to
-- the module at large. The ring vocabulary tops out at 'module', so there has
-- been no value to write. This adds one; which marks are written with it is a
-- product decision and this migration deliberately does not make it — nothing
-- here changes what an existing mark is scoped to.
do $$ begin
  alter table paper_annotations drop constraint if exists paper_annotations_ring_check;
exception when others then null; end $$;
do $$ begin
  alter table paper_annotations add constraint paper_annotations_ring_known
    check (ring in ('solo', 'seat', 'wingman', 'formation', 'module'));
exception when duplicate_object then null; end $$;

-- ===================================================== 5 · what follows you
-- Bookmarks and where you were reading were localStorage, so a second device
-- saw neither and clearing site data lost both.
create table if not exists paper_reading (
  user_id    text        not null,
  paper_id   text        not null,
  page       integer     not null default 1,
  zoom       integer     not null default 100,
  rot        smallint    not null default 0,
  fit        boolean     not null default true,
  bookmarks  integer[]   not null default '{}',
  updated_at timestamptz not null default now(),
  primary key (user_id, paper_id)
);
alter table paper_reading enable row level security;
do $$ begin
  create policy paper_reading_all on paper_reading for all using (true) with check (true);
exception when duplicate_object then null; end $$;

create or replace function paper_reading_set(
  uid text, p_paper text, p_page integer default null, p_zoom integer default null,
  p_rot smallint default null, p_fit boolean default null, p_bookmarks integer[] default null
) returns paper_reading language plpgsql security definer as $$
declare r paper_reading%rowtype;
begin
  if uid is null or p_paper is null then return null; end if;
  insert into paper_reading (user_id, paper_id, page, zoom, rot, fit, bookmarks)
  values (uid, p_paper, coalesce(p_page, 1), coalesce(p_zoom, 100),
          coalesce(p_rot, 0::smallint), coalesce(p_fit, true), coalesce(p_bookmarks, '{}'))
  on conflict (user_id, paper_id) do update
    set page      = coalesce(p_page, paper_reading.page),
        zoom      = coalesce(p_zoom, paper_reading.zoom),
        rot       = coalesce(p_rot, paper_reading.rot),
        fit       = coalesce(p_fit, paper_reading.fit),
        bookmarks = coalesce(p_bookmarks, paper_reading.bookmarks),
        updated_at = now()
  returning * into r;
  return r;
end $$;

create or replace function paper_reading_get(uid text, p_paper text)
returns paper_reading language sql stable as $$
  select * from paper_reading where user_id = uid and paper_id = p_paper;
$$;

-- ============================================================ 6 · realtime
-- 0015 published the discussion and the squadron chat and stopped there, so
-- the reader's only mechanism was a sixty-second poll that re-read every mark
-- on the paper each time. The poll stays — the locked design is explicit that
-- the page never changes on its own and a dot is the whole notification — but
-- it now has something to be a safety net FOR.
do $$ begin alter publication supabase_realtime add table paper_annotations;  exception when others then null; end $$;
do $$ begin alter publication supabase_realtime add table paper_ink;          exception when others then null; end $$;
do $$ begin alter publication supabase_realtime add table paper_mark_agrees;  exception when others then null; end $$;

alter table paper_annotations  replica identity full;
alter table paper_ink          replica identity full;
alter table paper_mark_agrees  replica identity full;

-- ============================================================ 7 · backfill
-- Every agree_count that the 0018 counter left behind is recomputed from the
-- rows that now own it. There are none today — nothing ever called it — so
-- this is a statement of where the number comes from rather than a repair.
update paper_annotations a
   set agree_count = coalesce((select count(*) from paper_mark_agrees g where g.mark_id = a.id), 0)
 where a.agree_count is distinct from
       coalesce((select count(*) from paper_mark_agrees g where g.mark_id = a.id), 0);


-- ############################################################################
-- 0024_mark_edit_keeps_its_fields.sql
-- ############################################################################

-- 0024 — paper_mark_edit gets back the three fields 0023 dropped.
--
-- Run after 0023. Additive, safe to re-run, drops nothing.
--
-- WHAT HAPPENED. 0021 gave paper_mark_edit a whitelist of eight fields:
-- body, colour, ring, kind, style, hint, anonymous and resolved_at. 0023
-- rewrote the function to add optimistic-concurrency checking — given a
-- version, the write applies only if the row is still at it — and in doing so
-- rebuilt the SET list with five. `hint`, `anonymous` and `resolved_at` were
-- not removed on purpose; they were left out of a rewrite, and because the
-- function still returns a row for every other patch, nothing said so.
--
-- resolved_at is the one that matters. R9 of the annotation brief is that a
-- correction leaves the author's queue when the author resolves it, and
-- resolveCorrection() in src/lib/annotations.js is the call that does it. It
-- has no caller in the UI yet, which is exactly why this would have sat there:
-- the library function would have gone on returning a row and changing
-- nothing, and the first screen to wire it up would have been debugging the
-- client.
--
-- Caught by check:paper-db — "R9 · resolving it takes it off the queue" — which
-- drives the real function over the real REST path rather than reading it.
--
-- The version check 0023 added is kept exactly as it is.
--
-- AND ONE MORE, FOUND BY RUNNING IT: 0023's body does
-- `coalesce(p_patch->>'style', style)`, where style is jsonb and ->> is text.
-- That does not compile, and plpgsql does not check a body until it runs — so
-- 0023 installed cleanly and paper_mark_edit threw on every call, for every
-- patch, not only one naming style. Recolouring a mark, converting one,
-- writing a note on one and resolving a correction all went through it.

-- AND THERE WERE TWO OF THEM. 0021 created paper_mark_edit(text, uuid, jsonb).
-- 0023 created paper_mark_edit(text, uuid, jsonb, integer) with the fourth
-- argument defaulted, and did not drop the first — so both matched a
-- three-argument call and Postgres refused it as ambiguous:
--
--   function paper_mark_edit(unknown, uuid, jsonb) is not unique
--
-- Every edit the reader makes is a three-argument call. 0023 dropped the
-- superseded agree_with_mark(uuid) for exactly this reason and missed this
-- one. The old signature goes; the widened one below is the only one left.
drop function if exists paper_mark_edit(text, uuid, jsonb);

create or replace function paper_mark_edit(
  uid text, p_id uuid, p_patch jsonb, p_version integer default null
) returns paper_annotations language plpgsql security definer
set search_path = public, pg_temp as $$
declare r paper_annotations%rowtype; cur integer;
begin
  select version into cur from paper_annotations where id = p_id and author_id = uid;
  if cur is null then return null; end if;
  -- Given a version, the write applies only if the row is still at it. Given
  -- none, it behaves exactly as it did before, so an older client is not
  -- broken by this migration. Unchanged from 0023.
  if p_version is not null and p_version <> cur then return null; end if;
  update paper_annotations
     set colour     = coalesce(p_patch->>'colour', colour),
         kind       = coalesce(p_patch->>'kind', kind),
         ring       = coalesce(p_patch->>'ring', ring),
         body       = case when p_patch ? 'body' then p_patch->>'body' else body end,
         -- style is jsonb. 0023 read it with ->> , which is text, and
         -- `coalesce(text, jsonb)` does not compile — so this function threw
         -- "COALESCE types text and jsonb cannot be matched" on EVERY call,
         -- not only on a patch naming style. plpgsql does not check a body at
         -- creation time, so 0023 installed cleanly and failed at runtime.
         style      = case when p_patch ? 'style' then p_patch->'style' else style end,
         -- the three 0023 left out
         hint       = case when p_patch ? 'hint' then p_patch->'hint' else hint end,
         anonymous  = case when p_patch ? 'anonymous'
                           then (p_patch->>'anonymous')::boolean else anonymous end,
         resolved_at = case when p_patch ? 'resolved_at'
                            then nullif(p_patch->>'resolved_at', '')::timestamptz
                            else resolved_at end,
         version    = cur + 1,
         updated_at = now()
   where id = p_id and author_id = uid
  returning * into r;
  return r;
end $$;

grant execute on function paper_mark_edit(text, uuid, jsonb, integer) to anon, authenticated;

-- Proof, at migration time rather than trusted: a patch naming resolved_at has
-- to reach the column.
do $$
declare v_id uuid; v_out paper_annotations%rowtype;
begin
  insert into paper_annotations (paper_id, module_code, author_id, kind, ring, anchor)
  values ('mig0024_probe', 'M1', 'mig0024_probe', 'correction', 'module',
          '{"quote":"probe","prefix":"","suffix":""}'::jsonb)
  returning id into v_id;
  select * into v_out from paper_mark_edit('mig0024_probe', v_id,
    jsonb_build_object('resolved_at', now()::text));
  if v_out.resolved_at is null then
    delete from paper_annotations where id = v_id;
    raise exception '0024 did not take: resolved_at is still null after an edit that set it';
  end if;
  delete from paper_annotations where id = v_id;
end $$;


-- ############################################################################
-- 0025_one_function_per_name.sql
-- ############################################################################

-- 0025 — two superseded overloads that 0023 left standing.
--
-- Run after 0023 and 0024. Drops nothing but the two old signatures named
-- below, each of which has a wider replacement already in place. Safe to
-- re-run.
--
-- WHAT BROKE, AND HOW IT WAS FOUND. 0023 widened paper_ink_add with three new
-- arguments — opacity, cap and variant — all defaulted, on the stated grounds
-- that "a client that has not been updated keeps working against it". That is
-- true of a function whose old signature is gone, and false of one whose old
-- signature is still there: PostgREST matched the deployed client's call
-- against both and refused to choose.
--
--   300  Could not choose the best candidate function between
--        public.paper_ink_add(uid, p_paper, p_module, p_page, p_points, …)
--
-- Every pen and highlighter stroke on the live site goes through that call, so
-- drawing stopped working the moment 0023 ran, for everyone, with no error the
-- student could see — the stroke stays on the page and never lands, which is
-- precisely the failure the outbox exists to catch and report.
--
-- Caught by asking the database what the DEPLOYED client asks it, rather than
-- what the new branch does. 0024 fixed the same fault in paper_mark_edit; this
-- is the one that came before it in the same migration and was missed.
--
-- THE RULE: widening a function's arguments means dropping the old signature
-- in the same migration. 0023 did exactly that for agree_with_mark(uuid) and
-- not for these two.

-- ------------------------------------------------------------ 1 · the ink
-- 0021's ten-argument version. 0023's takes the same ten plus opacity, cap and
-- variant, all defaulted, so every existing call site still resolves — once
-- there is only one of them.
drop function if exists paper_ink_add(text, text, text, int, jsonb, text, text, real, text, uuid);

-- ---------------------------------------------------- 2 · orphan marking
-- 0014's two-argument version takes no uid and checks nothing: anybody holding
-- the anon key could mark anybody's mark orphaned. 0023 replaced it with
-- paper_annotation_status(uid, p_id, p_status), which writes only where
-- author_id = uid. The arities differ, so this one was not ambiguous — it was
-- simply an unauthenticated door left open beside the locked one.
drop function if exists paper_annotation_status(uuid, text);

-- ---------------------------------------------------------------- 3 · proof
-- Run at migration time rather than trusted. Both names must resolve to
-- exactly one function, and paper_ink_add must still accept the shorter call
-- the deployed client makes.
do $$
declare n integer;
begin
  select count(*) into n from pg_proc p
    join pg_namespace s on s.oid = p.pronamespace
   where s.nspname = 'public' and p.proname = 'paper_ink_add';
  if n <> 1 then raise exception '0025: paper_ink_add still has % signatures', n; end if;

  select count(*) into n from pg_proc p
    join pg_namespace s on s.oid = p.pronamespace
   where s.nspname = 'public' and p.proname = 'paper_annotation_status';
  if n <> 1 then raise exception '0025: paper_annotation_status still has % signatures', n; end if;

  select count(*) into n from pg_proc p
    join pg_namespace s on s.oid = p.pronamespace
   where s.nspname = 'public' and p.proname = 'paper_mark_edit';
  if n <> 1 then raise exception '0025: paper_mark_edit still has % signatures', n; end if;
end $$;

-- And the call the shipped bundle actually makes, end to end: ten arguments,
-- no opacity, no cap, no variant. It has to land.
do $$
declare r paper_ink%rowtype;
begin
  select * into r from paper_ink_add(
    'mig0025_probe', 'mig0025_probe_paper', 'M1', 1,
    '[[0.1,0.1],[0.2,0.2]]'::jsonb, 'pen', 'blue', 0.0032, 'solo', null);
  if r.id is null then
    raise exception '0025: the ten-argument paper_ink_add did not return a row';
  end if;
  delete from paper_ink where id = r.id;
end $$;

grant execute on function paper_ink_add(text, text, text, integer, jsonb, text, text, real, text, real, text, smallint, uuid) to anon, authenticated;
grant execute on function paper_annotation_status(text, uuid, text) to anon, authenticated;


-- ############################################################################
-- 0026_chat_attachments.sql
-- ############################################################################

-- 0026 — attachments in squadron chat: a photo, a file, or a passage from a
-- paper.
--
-- Run after 0025. Additive: one table, two functions, one storage bucket and
-- one storage policy. Drops nothing but its own policy, before recreating it.
-- Safe to re-run.
--
-- ===========================================================================
-- WHY THIS IS NOT THE MIGRATION THAT CAME WITH THE DESIGN
-- ===========================================================================
-- The drop's SQL was written for a Supabase client signed in through a Clerk
-- JWT template: its row policies read `requesting_user_id()` from the token's
-- `sub` claim, and its storage policies are granted `to authenticated`. This
-- client is neither. It sends the anon key as its bearer, `auth.uid()` is NULL
-- on every request (0009's header), and the role Postgres sees is `anon`. As
-- written, every upload and every attachment insert would have been refused,
-- and nothing on screen would have said why.
--
-- Its own brief anticipated that: "if they use a different pattern, match it
-- rather than introducing a second one". The pattern here is 0009, 0011, 0021
-- and 0022 — the rule lives in a SECURITY DEFINER function that takes the
-- caller's id as an argument and checks it against the data. So that is what
-- this does.
--
-- Two further corrections to the drop, found by reading the schema rather
-- than the page: paper ids are text (`M1-B2-13D-…`), not uuid; and the message
-- table is `comms_messages`, keyed by `squadron_id`, with a `module_code` that
-- may not be null.
--
-- ===========================================================================
-- THE STORAGE DECISION, stated rather than buried
-- ===========================================================================
-- The drop wanted a PRIVATE bucket read through one-hour signed URLs, with each
-- upload checked against the uploader's own folder. Signed URLs are minted with
-- a server-side key, and "the uploader's own folder" needs an identity Storage
-- can verify. This project has neither: no Clerk-to-Supabase JWT and no
-- server. Of the two designs that can work without one:
--
--   * private + an anon SELECT policy, so the browser can mint signed URLs —
--     which also lets anyone holding the public key LIST the bucket and read
--     every attachment in every squadron;
--   * public + NO select policy — objects are served only by their exact URL,
--     the path carries a random uuid, and nothing can list the bucket.
--
-- The second is strictly better, so it is the one here. Under it an attachment
-- is readable exactly where its message is readable, because the path lives on
-- a row beside the message. What it gives up against the drop's intent: a
-- link copied out of the app does not expire. The airtight version is the same
-- end state 0021 describes — Clerk as a Supabase third-party auth provider, or
-- a small server function holding the service key.
--
-- What IS enforced, in the policy below, without identity: an upload must land
-- at `{squadron}/{member}/{file}`, and that member must really be in that
-- squadron. The bucket refuses anything over 25 MB and any type not listed.

-- ===================================================================== table
create table if not exists message_attachments (
  id            uuid        primary key default gen_random_uuid(),
  message_id    uuid        not null references comms_messages (id) on delete cascade,
  kind          text        not null check (kind in ('image', 'file', 'passage')),

  -- image and file
  storage_path  text,
  file_name     text,
  mime_type     text,
  byte_size     bigint,
  -- An image's pixel size, so the bubble reserves its space before the image
  -- arrives and the transcript does not jump as photos land.
  width         integer,
  height        integer,

  -- a passage lifted out of a Library paper
  paper_id      text,
  paper_title   text,
  page          integer,
  quote         text,
  anchor        jsonb,

  created_at    timestamptz not null default now(),

  constraint attachment_shape check (
    (kind in ('image', 'file') and storage_path is not null)
    or (kind = 'passage' and quote is not null and paper_id is not null)
  ),
  -- R1 of the annotation layer holds here too. A passage is copied from a mark,
  -- and a mark's anchor is text. A position smuggled in would be a passage
  -- that cannot survive the paper being reflowed.
  constraint attachment_anchor_is_text_only check (
    anchor is null
    or not (anchor ? 'page' or anchor ? 'rect' or anchor ? 'rects' or anchor ? 'bbox')
  )
);

create index if not exists message_attachments_message on message_attachments (message_id);

alter table message_attachments enable row level security;

-- Read: as open as comms_messages, which is what the bubble is read from. The
-- room fetches attachments embedded in the message query, one round trip, and
-- that embed needs SELECT here.
drop policy if exists message_attachments_read on message_attachments;
create policy message_attachments_read on message_attachments for select using (true);

-- Write: never directly. Only add_message_attachments below.
revoke insert, update, delete on message_attachments from anon, authenticated;
grant select on message_attachments to anon, authenticated;

-- ================================================================ writing
-- Attach files and passages to a message you just sent. The rules, all of them
-- checked here rather than trusted from the page:
--   * the message exists, is not deleted, and was written by p_me;
--   * p_me is a member of the message's squadron;
--   * every file row points inside that squadron's folder under p_me's id, so a
--     message cannot claim an object somebody else uploaded;
--   * no more than ten at once.
-- A row that fails the folder check is skipped rather than failing the whole
-- call, so one bad path cannot cost the student the rest of what they sent.
create or replace function add_message_attachments(p_me text, p_message uuid, p_rows jsonb)
returns setof message_attachments
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_sq     uuid;
  v_author text;
begin
  if p_me is null or p_message is null or p_rows is null
     or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then
    return;
  end if;
  if jsonb_array_length(p_rows) > 10 then
    raise exception 'add_message_attachments: at most ten attachments on one message';
  end if;

  select squadron_id, user_id into v_sq, v_author
    from comms_messages where id = p_message and deleted_at is null;
  if v_author is null or v_author <> p_me or v_sq is null then return; end if;
  if not exists (select 1 from squadron_members where squadron_id = v_sq and user_id = p_me) then
    return;
  end if;

  return query
  insert into message_attachments
    (message_id, kind, storage_path, file_name, mime_type, byte_size, width, height,
     paper_id, paper_title, page, quote, anchor)
  select p_message,
         r->>'kind',
         nullif(r->>'storage_path', ''),
         nullif(r->>'file_name', ''),
         nullif(r->>'mime_type', ''),
         nullif(r->>'byte_size', '')::bigint,
         nullif(r->>'width', '')::integer,
         nullif(r->>'height', '')::integer,
         nullif(r->>'paper_id', ''),
         nullif(r->>'paper_title', ''),
         nullif(r->>'page', '')::integer,
         nullif(r->>'quote', ''),
         case when jsonb_typeof(r->'anchor') = 'object' then r->'anchor' else null end
    from jsonb_array_elements(p_rows) as r
   where (r->>'kind') = 'passage'
      or ((r->>'kind') in ('image', 'file')
          and (r->>'storage_path') like (v_sq::text || '/' || p_me || '/%'))
  returning *;
end $$;

-- ============================================================ the picker
-- "Your marks in this module", for the passage picker behind the attach button.
-- Only the caller's own marks, newest first, with the paper's title so a card
-- can say where the words came from. There is no page to return: a mark's
-- anchor is text by rule and its drawing hint is not stored, so the card names
-- the paper and quotes the words, and the reader finds them.
create or replace function my_marks_in_module(uid text, p_module text, p_limit integer default 60)
returns table (
  id uuid, paper_id text, paper_title text, quote text, anchor jsonb,
  colour text, kind text, created_at timestamptz
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select a.id, a.paper_id, coalesce(p.title, a.paper_id), a.anchor->>'quote', a.anchor,
         a.colour, a.kind, a.created_at
    from paper_annotations a
    left join papers p on p.id = a.paper_id
   where a.author_id = uid
     and a.module_code = p_module
     and a.deleted_at is null
     and coalesce(a.anchor->>'quote', '') <> ''
   order by a.created_at desc
   limit greatest(1, least(coalesce(p_limit, 60), 200));
$$;

grant execute on function add_message_attachments(text, uuid, jsonb) to anon, authenticated;
grant execute on function my_marks_in_module(text, text, integer) to anon, authenticated;

-- ================================================================ storage
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'chat-attachments', 'chat-attachments', true, 26214400,
  array[
    'image/jpeg', 'image/png', 'image/webp', 'image/gif', 'image/heic',
    'application/pdf',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.openxmlformats-officedocument.presentationml.presentation',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'text/plain', 'text/csv'
  ]
)
on conflict (id) do update
  set public             = excluded.public,
      file_size_limit    = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- Upload only into `{squadron}/{member}/{file}`, where that member is in that
-- squadron. No SELECT policy on purpose: nothing may list this bucket. No
-- UPDATE or DELETE policy either, so an object cannot be swapped or removed
-- from the browser once it has been sent.
drop policy if exists chat_attachments_member_upload on storage.objects;
create policy chat_attachments_member_upload on storage.objects
  for insert to anon, authenticated
  with check (
    bucket_id = 'chat-attachments'
    and array_length(storage.foldername(name), 1) = 2
    and exists (
      select 1 from public.squadron_members m
       where m.squadron_id::text = (storage.foldername(name))[1]
         and m.user_id = (storage.foldername(name))[2]
    )
  );

-- ================================================================== proof
do $$
declare n integer;
begin
  select count(*) into n from storage.buckets where id = 'chat-attachments' and public;
  if n <> 1 then raise exception '0026: the chat-attachments bucket is missing or not public'; end if;

  select count(*) into n from pg_policies
   where schemaname = 'storage' and tablename = 'objects'
     and policyname = 'chat_attachments_member_upload';
  if n <> 1 then raise exception '0026: the upload policy did not land'; end if;

  select count(*) into n from pg_policies
   where schemaname = 'storage' and tablename = 'objects' and cmd = 'SELECT'
     and qual ilike '%chat-attachments%';
  if n <> 0 then raise exception '0026: something can list chat-attachments, and nothing should'; end if;

  if has_table_privilege('anon', 'message_attachments', 'INSERT') then
    raise exception '0026: anon can write message_attachments directly';
  end if;
end $$;


-- ############################################################################
-- 0027_read_receipts.sql
-- ############################################################################

-- =============================================================================
-- 0027 · READ RECEIPTS THAT TELL THE TRUTH
-- -----------------------------------------------------------------------------
-- A tick in a group chat answers one question: has everybody this went to got
-- it, and has everybody opened it. squadron_members.last_read_at (0022) is one
-- watermark per member. It is enough for an unread badge, but it cannot say
-- WHEN somebody opened a particular message, and nothing recorded delivery at
-- all, so a sender's tick had nothing true to draw.
--
-- One row per message per recipient now: when it reached them, and when they
-- first opened it. Blue ticks need every recipient's read_at — the WhatsApp
-- rule, where one person opening a message does not turn it blue.
--
-- WHO A MESSAGE WENT TO is decided when it is read back, not stored: the
-- members who had joined by the moment it was sent, other than its author, and
-- not cut off from the author by a block in either direction or by having
-- muted them. Somebody joining next week does not turn last week's ticks grey.
--
-- ADDITIVE. One table, one column, two new functions, and mark_squadron_read
-- keeps its exact signature and return type, so the bundle already deployed
-- keeps working before and after this runs.
-- =============================================================================

create table if not exists comms_receipts (
  message_id   uuid        not null references comms_messages (id) on delete cascade,
  user_id      text        not null,
  delivered_at timestamptz not null default now(),
  read_at      timestamptz,
  primary key (message_id, user_id)
);
create index if not exists comms_receipts_user_idx on comms_receipts (user_id);

alter table comms_receipts enable row level security;
-- Open, like every other table in this project: the client is anonymous from
-- Postgres' point of view and access control happens in the app. See 0009's
-- header before writing a policy that mentions auth.uid() here.
do $$ begin
  create policy comms_receipts_open on comms_receipts for all using (true) with check (true);
exception when duplicate_object then null; end $$;

-- How far delivery has been stamped for each member, so a fetch examines only
-- what arrived since the last one.
alter table squadron_members add column if not exists last_delivered_at timestamptz;

-- ============================================================ 1 · delivered
-- Called by a member's app once it has fetched the chat: everything it now
-- holds from other people is on that device. Only messages since the last
-- call are examined, with five minutes of overlap so a message committed late,
-- behind a newer one, is still caught. The primary key makes the overlap free.
create or replace function mark_squadrons_delivered(p_me text, p_squadrons uuid[])
returns integer language plpgsql security definer as $$
declare v_n integer := 0;
begin
  if p_me is null or p_squadrons is null then return 0; end if;
  insert into comms_receipts (message_id, user_id, delivered_at)
  select m.id, p_me, now()
    from squadron_members sm
    join comms_messages m on m.squadron_id = sm.squadron_id
   where sm.user_id = p_me
     and sm.squadron_id = any (p_squadrons)
     and m.user_id <> p_me
     and m.deleted_at is null
     and m.created_at >= sm.joined_at
     and m.created_at > coalesce(sm.last_delivered_at, sm.joined_at) - interval '5 minutes'
  on conflict (message_id, user_id) do nothing;
  get diagnostics v_n = row_count;
  update squadron_members set last_delivered_at = now()
   where user_id = p_me and squadron_id = any (p_squadrons);
  return v_n;
end $$;

-- ================================================================= 2 · read
-- The same signature and return as 0022, so nothing that calls it changes. It
-- still moves the watermark the unread badge counts from, and it now stamps
-- every message it covers. read_at is set once and never moved later, so the
-- time Message info shows is when they first opened it.
create or replace function mark_squadron_read(p_me text, p_squadron uuid)
returns timestamptz language plpgsql security definer as $$
declare
  v_prev timestamptz;
  v_at   timestamptz := now();
begin
  select last_read_at into v_prev from squadron_members
   where squadron_id = p_squadron and user_id = p_me;
  if not found then return null; end if;
  insert into comms_receipts (message_id, user_id, delivered_at, read_at)
  select m.id, p_me, v_at, v_at
    from comms_messages m
    join squadron_members sm on sm.squadron_id = m.squadron_id and sm.user_id = p_me
   where m.squadron_id = p_squadron
     and m.user_id <> p_me
     and m.deleted_at is null
     and m.created_at >= sm.joined_at
     and m.created_at <= v_at
     and m.created_at > v_prev - interval '5 minutes'
  on conflict (message_id, user_id)
    do update set read_at = coalesce(comms_receipts.read_at, excluded.read_at);
  update squadron_members set last_read_at = v_at
   where squadron_id = p_squadron and user_id = p_me;
  return v_at;
end $$;

-- ======================================================= 3 · what a sender sees
-- One row per person each of MY messages went to, with whichever of the two
-- times exist. Only the caller's own messages: who opened a message is its
-- author's business and nobody else's.
create or replace function message_receipts(p_me text, p_messages uuid[])
returns table (message_id uuid, user_id text, delivered_at timestamptz, read_at timestamptz)
language sql stable security definer as $$
  select m.id, sm.user_id, r.delivered_at, r.read_at
    from comms_messages m
    join squadron_members sm
      on sm.squadron_id = m.squadron_id
     and sm.user_id <> m.user_id
     and sm.joined_at <= m.created_at
    left join comms_receipts r on r.message_id = m.id and r.user_id = sm.user_id
   where m.id = any (p_messages)
     and m.user_id = p_me
     and not exists (select 1 from blocks b
                      where (b.user_id = m.user_id and b.blocked_id = sm.user_id)
                         or (b.user_id = sm.user_id and b.blocked_id = m.user_id))
     and not exists (select 1 from mutes u
                      where u.user_id = sm.user_id and u.muted_id = m.user_id);
$$;

-- ======================================================= 4 · what 0022 knew
-- A member whose watermark is past a message had opened it by then. That is
-- all the old column can say, so these rows carry the watermark as both times,
-- the closest true value there is. Anything after the watermark gets its
-- receipt the next time that member's app fetches the chat.
insert into comms_receipts (message_id, user_id, delivered_at, read_at)
select m.id, sm.user_id, sm.last_read_at, sm.last_read_at
  from comms_messages m
  join squadron_members sm on sm.squadron_id = m.squadron_id
 where m.squadron_id is not null
   and m.user_id <> sm.user_id
   and m.deleted_at is null
   and m.created_at >= sm.joined_at
   and m.created_at <= sm.last_read_at
on conflict (message_id, user_id) do nothing;

-- ================================================================= 5 · live
-- Live, like the messages themselves (0015), so a tick turns blue while the
-- sender is looking at it.
do $$ begin
  alter publication supabase_realtime add table comms_receipts;
exception when duplicate_object then null; when undefined_object then null; end $$;


-- ############################################################################
-- 0028_saves.sql
-- ############################################################################

-- 0028 — one list of what each student saved: questions, study cards, videos
-- and pages.
--
-- Run after 0027. Additive: one table, one index, four policies. Drops nothing.
-- Safe to re-run.
--
-- ===========================================================================
-- WHY THIS IS NOT THE MIGRATION THAT CAME WITH THE DESIGN
-- ===========================================================================
-- The drop's SQL defaulted user_id to `auth.jwt() ->> 'sub'` and wrote four
-- policies comparing user_id against the same claim. That is the shape for a
-- Supabase client signed in through a Clerk JWT template. This client is not
-- one: src/lib/supabaseClient.js is a bare PostgrestClient sending the anon key
-- as its own bearer, so there is no token, `auth.jwt()` is NULL on every
-- request, and the role Postgres sees is `anon`.
--
-- As written, every insert would have failed the NOT NULL on user_id and every
-- select would have returned nothing — and 0009's header is about exactly this:
-- a policy referencing a NULL claim denies every row rather than failing, so
-- nothing on screen would have said why.
--
-- Its own brief anticipated it: "Mirror the comments auth pattern if it differs
-- from auth.jwt()->>'sub'". That pattern is 0000's `user_progress`, 0008's
-- `lesson_threads` and 0014's `paper_annotations`: user_id is the CLERK id as
-- text, passed by the app, RLS is on with open policies, and the scoping is
-- `.eq('user_id', …)` in the client. So that is what this does.
--
-- WHAT THAT COSTS, STATED RATHER THAN BURIED. The brief's R1 check — "with B's
-- token, a direct select on A's rows returns nothing" — cannot be true here,
-- for saves or for any other table in this database. Anyone holding the
-- publishable key can read the `saves` table. That is the architecture's
-- standing trade, not a new hole opened by this migration, and a bookmark list
-- is the least sensitive thing already inside it (notes, threads and progress
-- are all there). Changing it means a Clerk JWT template and an authenticated
-- client for all 65 call sites, which is a project, not a line. It is in
-- claude/backlog-bookmarks.md as one.
--
-- ===========================================================================
-- THE SHAPE
-- ===========================================================================
-- ref_id is text and holds a different id per kind — a question id for
-- question/card, a lesson id for video, a paper id for page — because those
-- three id spaces are text here and none of them is a uuid (paper ids read
-- `M1-B2-13D-…`). One column with a kind beside it beats four nullable ones.
--
-- A question saved from the quiz and the same question saved from its card set
-- are TWO rows and that is deliberate: one is practised as a quiz and the other
-- is flipped as a card, so `kind` is part of what identifies a save.
--
-- The unique constraint is what stops a double tap making two of anything. It
-- carries `page` because two pages of one paper are two different saves, and it
-- is NULLS NOT DISTINCT (PG15+; the project runs 17.6) so that the three kinds
-- with no page still collide with themselves rather than slipping past a NULL.
-- A lesson saved twice is one row whose second MOVES — which is why at_seconds
-- is outside the constraint.

create table if not exists public.saves (
  id          uuid primary key default gen_random_uuid(),
  user_id     text not null,                -- the Clerk id, passed by the app
  module_id   text not null,
  kind        text not null check (kind in ('question', 'card', 'video', 'page')),
  ref_id      text not null,                -- question id (question/card), lesson id (video), paper id (page)
  chapter     int,
  at_seconds  int check (at_seconds is null or at_seconds >= 0),
  page        int check (page is null or page >= 1),
  created_at  timestamptz not null default now(),

  constraint saves_one_per_thing unique nulls not distinct (user_id, kind, ref_id, page),
  constraint saves_video_has_second check (kind <> 'video' or at_seconds is not null),
  constraint saves_page_has_page    check ((kind = 'page') = (page is not null))
);

-- The one query the app makes: this student's saves, newest first. module_id is
-- in the index because every screen is filtered to one module.
create index if not exists saves_user_module_recent on public.saves (user_id, module_id, created_at desc);

alter table public.saves enable row level security;

-- Open, like every other table here, and for the reason in the header: the
-- client is anonymous from Postgres' point of view, so a policy that named a
-- user would deny every row. Scoping is `.eq('user_id', …)` in savesStore.js,
-- which is the only file that reads or writes this table.
do $$
begin
  if not exists (select 1 from pg_policies where tablename = 'saves' and policyname = 'saves_read') then
    create policy saves_read   on public.saves for select using (true);
  end if;
  if not exists (select 1 from pg_policies where tablename = 'saves' and policyname = 'saves_write') then
    create policy saves_write  on public.saves for insert with check (true);
  end if;
  if not exists (select 1 from pg_policies where tablename = 'saves' and policyname = 'saves_change') then
    create policy saves_change on public.saves for update using (true) with check (true);
  end if;
  if not exists (select 1 from pg_policies where tablename = 'saves' and policyname = 'saves_remove') then
    create policy saves_remove on public.saves for delete using (true);
  end if;
end $$;

grant select, insert, update, delete on public.saves to anon, authenticated;


-- ############################################################################
-- 0029_stamp.sql
-- ############################################################################

-- 0029 — the stamp a pilot issues once, and never changes.
--
-- Run after 0028. Additive: eight columns on pilot_profiles, four CHECKs and
-- one function. Drops nothing. Safe to re-run.
--
-- ===========================================================================
-- WHY IT IS COLUMNS AND NOT A JSONB BLOB
-- ===========================================================================
-- The handoff writes the model as an object —
--   stamp { shape, code, rim, ring, pattern, ink, seed, issued_at }
-- — and it would fit in one jsonb column. It is eight columns instead, for the
-- reason 0016 gave for `code`: "the CHECK below is that alphabet, written
-- where it cannot be bypassed". A jsonb blob can hold a shape this app cannot
-- draw, an ink that is not in the palette, or a code with a bracket in it, and
-- nothing would notice until a licence rendered wrong for one person. Every
-- constraint below mirrors src/lib/stamp.js, and npm run check:stamp holds the
-- two together.
--
-- ===========================================================================
-- ISSUING IS ONE TIME ONLY, AND THAT IS ENFORCED HERE
-- ===========================================================================
-- §4: "Issuing is one time only. The server rejects changes once issued_at is
-- set." A client-side check cannot make that true — this client is anonymous
-- from Postgres' point of view (0009's header) and anyone with the publishable
-- key can PATCH a row. So the columns are written through `issue_stamp` only,
-- a SECURITY DEFINER function that refuses a second call, and the direct
-- UPDATE path is closed by a trigger rather than by a policy: a policy naming
-- a user would deny every row, because auth.jwt() is NULL on every request.
--
-- The seed is the SERVER'S, not the client's. It is what gives an account its
-- own permanent ink texture, and a client that chose it could choose somebody
-- else's.

alter table pilot_profiles add column if not exists stamp_shape     text;
alter table pilot_profiles add column if not exists stamp_code      text;
alter table pilot_profiles add column if not exists stamp_rim       boolean;
alter table pilot_profiles add column if not exists stamp_ring      text;
alter table pilot_profiles add column if not exists stamp_pattern   text;
alter table pilot_profiles add column if not exists stamp_ink       text;
alter table pilot_profiles add column if not exists stamp_seed      integer;
alter table pilot_profiles add column if not exists stamp_issued_at timestamptz;

do $$
begin
  -- The six shapes and the six patterns the renderer can draw, and nothing else.
  if not exists (select 1 from pg_constraint where conname = 'stamp_shape_known') then
    alter table pilot_profiles add constraint stamp_shape_known
      check (stamp_shape is null or stamp_shape in ('seal','roundel','window','gauge','postage','tag'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'stamp_pattern_known') then
    alter table pilot_profiles add constraint stamp_pattern_known
      check (stamp_pattern is null or stamp_pattern in ('none','rays','waves','checks','swirl','guilloche'));
  end if;
  -- §4: "a code of 1-3 characters, A-Z or 0-9, required. There are no symbols."
  if not exists (select 1 from pg_constraint where conname = 'stamp_code_shape') then
    alter table pilot_profiles add constraint stamp_code_shape
      check (stamp_code is null or stamp_code ~ '^[A-Z0-9]{1,3}$');
  end if;
  -- The rim text is the student's own, at most ten, from an alphabet that
  -- cannot close an SVG tag. src/lib/stamp.js cleans it; this is the floor.
  if not exists (select 1 from pg_constraint where conname = 'stamp_ring_shape') then
    alter table pilot_profiles add constraint stamp_ring_shape
      check (stamp_ring is null or stamp_ring ~ '^[A-Z0-9 .''-]{0,10}$');
  end if;
  -- An ink is a NAME from the palette. Storing the colour would mean a
  -- re-tuned palette could never reach the stamps already issued.
  if not exists (select 1 from pg_constraint where conname = 'stamp_ink_known') then
    alter table pilot_profiles add constraint stamp_ink_known
      check (stamp_ink is null or stamp_ink in (
        'Midnight','Lapiz','Miami','Baby','Powder','Glacier','Teal','Seafoam','Emerald','Racing','Sage','Matcha',
        'Olive','Khaki','Sand','Butter','Honey','Papaya','Clementine','Coral','Ruby','Cherry','Peach','Latte',
        'Mocha','Espresso','Nardo','Gunmetal','Chalk','Mauve','Blush','Bubblegum','Barbie','Lilac','Lavender','Plum'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'stamp_seed_whole') then
    alter table pilot_profiles add constraint stamp_seed_whole
      check (stamp_seed is null or stamp_seed between 1 and 999999);
  end if;
end $$;

-- ISSUE IT ONCE. Returns the row as issued; raises if there already is one.
create or replace function issue_stamp(
  uid text, p_shape text, p_code text, p_rim boolean,
  p_ring text, p_pattern text, p_ink text)
returns pilot_profiles
language plpgsql
security definer
set search_path = public
as $$
declare out_row pilot_profiles;
begin
  if uid is null or uid = '' then raise exception 'no pilot'; end if;

  insert into pilot_profiles (user_id) values (uid)
  on conflict (user_id) do nothing;

  -- The one rule this function exists for.
  if exists (select 1 from pilot_profiles p where p.user_id = uid and p.stamp_issued_at is not null) then
    raise exception 'that stamp is already issued';
  end if;

  update pilot_profiles p set
    stamp_shape = p_shape,
    -- Cleaned here as well as in the UI: this is the last gate before storage.
    stamp_code = upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g')),
    stamp_rim = coalesce(p_rim, true),
    stamp_ring = nullif(left(upper(regexp_replace(coalesce(p_ring, ''), '[^A-Za-z0-9 .''-]', '', 'g')), 10), ''),
    stamp_pattern = coalesce(p_pattern, 'none'),
    stamp_ink = p_ink,
    -- The server's, not the client's.
    stamp_seed = 1 + floor(random() * 999998)::int,
    stamp_issued_at = now()
  where p.user_id = uid
  returning p.* into out_row;

  if out_row.stamp_code is null or out_row.stamp_code = '' then
    raise exception 'a stamp needs a code';
  end if;
  return out_row;
end $$;

-- AND THE DIRECT PATH IS CLOSED. Without this, `issued once` is a promise the
-- function keeps and a PATCH ignores.
create or replace function stamp_is_permanent() returns trigger
language plpgsql as $$
begin
  if old.stamp_issued_at is not null and (
       new.stamp_shape   is distinct from old.stamp_shape
    or new.stamp_code    is distinct from old.stamp_code
    or new.stamp_rim     is distinct from old.stamp_rim
    or new.stamp_ring    is distinct from old.stamp_ring
    or new.stamp_pattern is distinct from old.stamp_pattern
    or new.stamp_ink     is distinct from old.stamp_ink
    or new.stamp_seed    is distinct from old.stamp_seed
    or new.stamp_issued_at is distinct from old.stamp_issued_at)
  then
    raise exception 'a stamp cannot be changed once it is issued';
  end if;
  return new;
end $$;

drop trigger if exists pilot_stamp_permanent on pilot_profiles;
create trigger pilot_stamp_permanent
  before update on pilot_profiles
  for each row execute function stamp_is_permanent();

grant execute on function issue_stamp(text, text, text, boolean, text, text, text) to anon, authenticated;


-- ############################################################################
-- 0030_licence_card.sql
-- ############################################################################

-- 0030 — the licence card: what is on it that nothing else already stores.
--
-- Run after 0029. Additive: five columns on pilot_profiles, four CHECKs and
-- one read function. Drops nothing. Safe to re-run.
--
-- ===========================================================================
-- WHY THESE FIVE AND NOT MORE
-- ===========================================================================
-- §5 lists the card as cover, photo, callsign, full name, bio, phrase, stats
-- and stamp. Most of that is already somewhere and must not be copied here:
--
--   callsign, real_name    pilot_profiles, since 0005 and 0012
--   the stamp              pilot_profiles, since 0029
--   the photo              CLERK. It is the account's picture, the same one
--                          the app bar draws, and a second copy in Postgres
--                          would be a second answer to "what do they look
--                          like". Fly solo hides it in one place as a result.
--   hours flown            pw-hobbs, through merge_progress
--   lessons signed off     chapter_completions / the account's own progress
--   days flown             derived from those; nothing new is stored for it
--
-- What is left is the four things the card invented — a cover, its ink, an
-- optional uploaded image for it, and a phrase — plus the bio, which existed
-- as `pw-bio` in the account's private progress and therefore could not be
-- read by the person looking at the card. That is the bug this migration
-- fixes as much as it is a new feature: a bio nobody else can see is not a
-- bio, it is a note to self.
--
-- ===========================================================================
-- THE CHECKS MIRROR src/lib/cover.js, FOR 0029's REASON
-- ===========================================================================
-- The browser holds the anon key, so a rule the client enforces is not a rule.
-- A cover id this app cannot draw, or an ink outside the palette, would render
-- as a hole in one person's card and nowhere else. npm run check:licence holds
-- the two lists together.
--
-- The phrase is one of exactly three (§5). It is a CHECK and not a lookup
-- table because three is not a table, and because the constraint is then
-- visible in the same place as the others.

alter table pilot_profiles add column if not exists bio         text;
alter table pilot_profiles add column if not exists phrase      text;
alter table pilot_profiles add column if not exists cover       text;
alter table pilot_profiles add column if not exists cover_ink   text;
alter table pilot_profiles add column if not exists cover_image text;

-- ===========================================================================
-- THE THREE STATS, AND WHY THEY ARE COLUMNS HERE
-- ===========================================================================
-- §5: "three that everyone fills just by using the app: Hours flown · Lessons
-- signed off · Days flown. They come from real data."
--
-- The real data is the ACCOUNT'S OWN PROGRESS — pw-hobbs, pw-lesson-done and
-- pw-days, in user_progress, which is private and has exactly one reader. The
-- card is opened by other people, so the numbers have to be readable by other
-- people, and there is no query that can reach another pilot's progress.
--
-- So these three are a PROJECTION, written by their owner, exactly as
-- callsign and real_name already are: "Clerk is not queryable from Postgres,
-- and the callsign is what the whole social layer reads" (Profile.jsx). The
-- truth stays in user_progress; this is the copy other people are allowed to
-- see. A projection that drifts shows a stale number on somebody else's
-- screen, which is the worst this can do — it cannot make the owner's own
-- Flight Deck wrong, because that reads the truth.
--
-- Seconds, not a formatted string: how "13h 54m" is spelled is a decision for
-- the screen, and a different screen may spell it differently.
alter table pilot_profiles add column if not exists hours_s       integer not null default 0;
alter table pilot_profiles add column if not exists lessons_signed integer not null default 0;
alter table pilot_profiles add column if not exists days_flown     integer not null default 0;

do $$
begin
  -- The five drawn sets, plus 'image' for an uploaded one.
  if not exists (select 1 from pg_constraint where conname = 'cover_known') then
    alter table pilot_profiles add constraint cover_known
      check (cover is null or cover in ('contour','panels','runway','flight','chart','image'));
  end if;
  -- The same thirty-six names 0029 holds the stamp's ink to, and for the same
  -- reason: a name survives a re-tuned palette, a colour does not.
  if not exists (select 1 from pg_constraint where conname = 'cover_ink_known') then
    alter table pilot_profiles add constraint cover_ink_known
      check (cover_ink is null or cover_ink in (
        'Midnight','Lapiz','Miami','Baby','Powder','Glacier','Teal','Seafoam','Emerald','Racing','Sage','Matcha',
        'Olive','Khaki','Sand','Butter','Honey','Papaya','Clementine','Coral','Ruby','Cherry','Peach','Latte',
        'Mocha','Espresso','Nardo','Gunmetal','Chalk','Mauve','Blush','Bubblegum','Barbie','Lilac','Lavender','Plum'));
  end if;
  -- §5: "one line, max 80 characters". Enforced where it cannot be argued with.
  if not exists (select 1 from pg_constraint where conname = 'bio_one_line') then
    alter table pilot_profiles add constraint bio_one_line
      check (bio is null or (length(bio) <= 80 and bio !~ '[\n\r]'));
  end if;
  -- Exactly three, and they are these three.
  if not exists (select 1 from pg_constraint where conname = 'phrase_is_one_of_three') then
    alter table pilot_profiles add constraint phrase_is_one_of_three
      check (phrase is null or phrase in (
        'Torqued to spec. Emotionally too.',
        'It''s not a leak, it''s a seep.',
        'Could not duplicate.'));
  end if;
  -- An uploaded cover is a URL in the app's own public bucket, and nothing
  -- else. Without this the column is a place to park any string a client
  -- likes, and the card renders it into a background-image.
  -- Nothing negative, and nothing a typo could make absurd. A projection is
  -- still a number somebody else reads off a card.
  if not exists (select 1 from pg_constraint where conname = 'stats_are_sane') then
    alter table pilot_profiles add constraint stats_are_sane
      check (hours_s >= 0 and hours_s <= 100000000
         and lessons_signed >= 0 and lessons_signed <= 100000
         and days_flown >= 0 and days_flown <= 100000);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'cover_image_is_ours') then
    alter table pilot_profiles add constraint cover_image_is_ours
      check (cover_image is null or cover_image ~ '^https://[a-z0-9-]+\.supabase\.co/storage/v1/object/public/');
  end if;
end $$;

-- ===========================================================================
-- READING SOMEBODY ELSE'S CARD
-- ===========================================================================
-- §5: "tapping any face or stamp anywhere opens this card for that person".
-- So the card is read for a user who is NOT the viewer, and what comes back
-- has to be exactly what a card draws and nothing more — this table also
-- carries notify settings, discoverability, an exam window and a timezone,
-- none of which is anybody else's business. A function rather than a select,
-- so the column list is the boundary and is written down once.
--
-- IT RESPECTS FLY SOLO. `invisible` is that switch (0005), and a pilot who has
-- it on is not on any card anybody opens: the function returns no row, and the
-- viewer's screen says nothing was found rather than drawing a blank card.
create or replace function licence_card(p_viewer text, p_user text)
returns table (
  user_id text, callsign text, real_name text, code text,
  bio text, phrase text, cover text, cover_ink text, cover_image text,
  is_staff boolean, hours_s integer, lessons_signed integer, days_flown integer,
  stamp_shape text, stamp_code text, stamp_rim boolean, stamp_ring text,
  stamp_pattern text, stamp_ink text, stamp_seed integer, stamp_issued_at timestamptz
)
language sql
stable
security definer
set search_path = public
as $$
  select p.user_id, p.callsign, p.real_name, p.code,
         p.bio, p.phrase, p.cover, p.cover_ink, p.cover_image,
         p.is_staff, p.hours_s, p.lessons_signed, p.days_flown,
         p.stamp_shape, p.stamp_code, p.stamp_rim, p.stamp_ring,
         p.stamp_pattern, p.stamp_ink, p.stamp_seed, p.stamp_issued_at
    from pilot_profiles p
   where p.user_id = p_user
     -- Your own card is always yours to see, Fly solo or not.
     and (p.user_id = p_viewer or p.invisible = false)
     -- And a block cuts both ways, as it does everywhere else (0006).
     -- The columns are user_id/blocked_id (0005), not blocker_id.
     and not exists (
       select 1 from blocks b
        where (b.user_id = p_viewer and b.blocked_id = p_user)
           or (b.user_id = p_user   and b.blocked_id = p_viewer))
$$;

-- ================================================================ storage
-- §5: "Image upload needs size and type limits, storage, and a crop that
-- fills 640x128." The crop is the browser's (src/lib/coverImage.js); this is
-- the other two, stated where they cannot be argued with.
--
-- PUBLIC, LIKE THE OTHER THREE. A licence card is opened by other people; a
-- signed URL for a picture that every viewer is allowed to see is a round
-- trip per view and an expiry to get wrong. The bucket is public and, like
-- chat-attachments, has NO select policy — it can be read by path and not
-- listed, so one person's cover cannot be used to enumerate everybody's.
--
-- 1MB and four types. What is uploaded is a 640x128 WEBP the browser rendered
-- — about 40KB — so a megabyte is already ten times the room it needs, and
-- anything larger did not come from this app.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('covers', 'covers', true, 1048576,
        array['image/webp', 'image/png', 'image/jpeg', 'image/gif'])
on conflict (id) do update
  set public             = excluded.public,
      file_size_limit    = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

-- ONE OBJECT PER PILOT, AT THEIR OWN ID. `{user}/cover.webp` and nothing
-- else, so an upload cannot land under somebody else's folder and a second
-- cover replaces the first rather than filling the bucket. Update is allowed
-- for exactly that reason — the path is stable and the contents change.
-- Delete is not: there is no screen that removes a cover, only ones that
-- replace it.
drop policy if exists covers_upload on storage.objects;
create policy covers_upload on storage.objects
  for insert to public
  with check (
    bucket_id = 'covers'
    and array_length(storage.foldername(name), 1) = 1
    and name = (storage.foldername(name))[1] || '/cover.webp'
  );

-- AND IT NEEDS A SELECT POLICY TO BE ABLE TO INSERT AT ALL, which is not
-- obvious and cost an afternoon. An upload with `x-upsert: true` makes
-- storage-api LOOK FIRST to see whether the object is already there; with no
-- select policy that look returns nothing it is allowed to see, and the API
-- reports the whole request as "new row violates row-level security policy" —
-- an insert error for a select that was refused. 0026 left it out of
-- chat-attachments on purpose ("nothing may list this bucket") and that is
-- why chat attachments have never uploaded either; 0031 fixes that one.
--
-- Listing covers gives away nothing the bucket does not already give away:
-- it is public, the path is <user>/cover.webp, and a user id is on screen
-- wherever a person is.
drop policy if exists covers_read on storage.objects;
create policy covers_read on storage.objects
  for select to public
  using (bucket_id = 'covers');

drop policy if exists covers_replace on storage.objects;
create policy covers_replace on storage.objects
  for update to public
  using (bucket_id = 'covers')
  with check (
    bucket_id = 'covers'
    and name = (storage.foldername(name))[1] || '/cover.webp'
  );

do $$
declare n integer;
begin
  select count(*) into n from storage.buckets where id = 'covers' and public;
  if n <> 1 then raise exception '0030: the covers bucket is missing or not public'; end if;
  -- All three, and the select one especially: without it nothing uploads.
  select count(*) into n from pg_policies
   where schemaname = 'storage' and tablename = 'objects'
     and policyname in ('covers_upload', 'covers_read', 'covers_replace');
  if n <> 3 then raise exception '0030: the covers policies are incomplete (%)', n; end if;
end $$;


-- ############################################################################
-- 0031_chat_attachments_can_upload.sql
-- ############################################################################

-- 0031 — chat attachments have never uploaded, and this is why.
--
-- Run after 0030. Additive: one policy. Drops nothing. Safe to re-run.
--
-- ===========================================================================
-- AN UPLOAD NEEDS A SELECT POLICY, AND 0026 LEFT IT OUT ON PURPOSE
-- ===========================================================================
-- 0026 created the chat-attachments bucket with an INSERT policy and said, in
-- the margin: "No SELECT policy on purpose: nothing may list this bucket."
--
-- That reasoning is sound and the consequence was not foreseen. Supabase's
-- storage API uploads with `x-upsert: true`, which makes it LOOK FIRST to see
-- whether the object is already there. With no select policy that look is
-- refused, and the API reports the whole request as
--
--     403  new row violates row-level security policy
--
-- — an INSERT error for a SELECT that was denied. So every attachment upload
-- in the Ready Room has failed since 0026 shipped, with a message that points
-- at the wrong statement. Found on 2026-09-19 while building the licence
-- card's cover upload, which hit the identical wall on a brand new bucket.
--
-- ===========================================================================
-- WHAT THIS TRADES, STATED RATHER THAN GLOSSED
-- ===========================================================================
-- A select policy permits LISTING, and this one permits listing the bucket to
-- anybody holding the publishable key. It cannot be narrowed to the viewer:
-- `auth.uid()` is NULL on every request in this architecture (0009's header),
-- which is the same reason 0026's insert policy checks that the path names
-- SOMEBODY in that squadron rather than the person asking.
--
-- What it gives away is a list of paths in a bucket that is already public —
-- the objects themselves have always been readable by URL, and a squadron id
-- and a member id are both on screen wherever that squadron is. It is a real
-- reduction and it is the price of the feature working at all.
--
-- The narrower alternative is to stop using x-upsert for attachments, which
-- would need a client change and would make a retried upload fail instead.
-- Written down here so the choice is visible rather than inherited.

drop policy if exists chat_attachments_read on storage.objects;
create policy chat_attachments_read on storage.objects
  for select to public
  using (bucket_id = 'chat-attachments');

do $$
declare n integer;
begin
  select count(*) into n from pg_policies
   where schemaname = 'storage' and tablename = 'objects'
     and policyname in ('chat_attachments_member_upload', 'chat_attachments_read');
  if n <> 2 then raise exception '0031: chat attachments still cannot upload (%)', n; end if;
end $$;


-- ############################################################################
-- 0032_fly_solo_on_the_server.sql
-- ############################################################################

-- 0032 — Fly solo hides you from search, and from the roster, on the server.
--
-- Run after 0031. Replaces two functions in place; adds no columns and drops
-- nothing. Safe to re-run.
--
-- ===========================================================================
-- WHAT WAS LEAKING
-- ===========================================================================
-- §6 of the launch handoff: "Fly solo must actually hide the student from
-- Crew, the route strip, the radar and presence, and hide others from them."
--
-- Most of that already held, and each in the strongest way available:
--
--   presence      gated at the WRITE, and the row is deleted (presence.js).
--                 There is nothing left for anybody to read, so no reader has
--                 to cooperate. right_seat reads presence, so it follows.
--   Crew          crew.js selects `invisible` and drops those rows.
--   the roster     squadron.js asks for `.eq("invisible", false)`.
--   the licence    0030's licence_card refuses a pilot who is invisible.
--
-- `people_search` did not. It filters on `discoverable`, which is 0011's
-- separate opt-out of BEING SUGGESTED, and a student who had never touched
-- that setting stayed findable by callsign while flying solo. Type somebody's
-- name into Discover and there they were, having asked not to be seen.
--
-- The two settings are not the same thing and neither replaces the other:
-- `discoverable` is "don't put me forward", Fly solo is "I am not here". The
-- second has to imply the first.
--
-- `squadron_roster` did not either. squadron.js already hides them from the
-- member list on its own query, which is exactly the shape 0009's header warns
-- about: a rule the client enforces is not a rule. The server says it too now,
-- so the two cannot drift.
--
-- ===========================================================================
-- WHAT THIS DELIBERATELY DOES NOT DO
-- ===========================================================================
-- It does not remove a solo student from their squadron, from a thread they
-- wrote in, or from anything they did. Fly solo is about being SEEN standing
-- somewhere, not about unwriting the past — and a message with no author is a
-- worse surface than a message from somebody quiet. Their words stay; their
-- presence goes.

-- BODY COPIED FROM THE LIVE DEFINITION, with one line added — the same
-- discipline 0013 used: "Body copied from the live definition
-- (pg_get_functiondef) ... Nothing else changed." 0011 wrote this function and
-- 0012 replaced it: the live one returns `display_name`, not `callsign`, and
-- carries the identity_display rule. Replacing 0011's text would have changed
-- the return type, which Postgres refuses, and would have silently undone
-- 0012's rule if it had not.
create or replace function people_search(p_me text, p_q text)
returns table (user_id text, display_name text, module_code text, shares_squadron boolean)
language sql
stable
as $$
  with me_prefs as (select p_me as uid)
  select
    p.user_id,
    /* What the searcher is allowed to see them as. Never coalesce to real_name
       for somebody who goes by callsign — that is the leak. */
    case when coalesce(up.identity_display, 'real') = 'username'
         then p.callsign
         else coalesce(p.real_name, p.callsign) end as display_name,
    (select c.module_code from chapter_completions c
      where c.user_id = p.user_id order by c.completed_at desc limit 1) as module_code,
    exists (
      select 1 from squadron_members a
      join squadron_members b on b.squadron_id = a.squadron_id
      where a.user_id = p_me and b.user_id = p.user_id
    ) as shares_squadron
  from pilot_profiles p
  left join user_prefs up on up.user_id = p.user_id
  cross join me_prefs
  where p.discoverable
    -- Fly solo. The one line this migration exists for.
    and not coalesce(p.invisible, false)
    and in_my_orbit(p_me, p.user_id)
    and not exists (select 1 from blocks b
                    where (b.user_id = p_me and b.blocked_id = p.user_id)
                       or (b.user_id = p.user_id and b.blocked_id = p_me))
    and coalesce(btrim(p_q), '') <> ''
    and (
      p.callsign ilike '%' || btrim(p_q) || '%'
      /* The real name is matchable ONLY while they have not chosen otherwise. */
      or (coalesce(up.identity_display, 'real') <> 'username'
          and p.real_name ilike '%' || btrim(p_q) || '%')
    )
  order by shares_squadron desc, display_name
  limit 20;
$$;

-- Body as 0013 rebuilt it (without the livery column), with the same one line.
-- YOU ARE STILL ON YOUR OWN ROSTER: hiding yourself from the squadron you are
-- looking at would make your own membership look like it had lapsed.
create or replace function squadron_roster(uid text, sid uuid)
returns table (user_id text, callsign text, marking text, is_staff boolean, joined_at timestamptz)
language sql
stable
as $$
  select m.user_id, p.callsign, m.marking,
         coalesce(p.is_staff, false), m.joined_at
    from squadron_members m
    left join pilot_profiles p on p.user_id = m.user_id
   where m.squadron_id = sid
     and (m.user_id = uid or not coalesce(p.invisible, false))
     and m.user_id not in (select blocked_id from blocks where blocks.user_id = uid)
     and m.user_id not in (select b.user_id from blocks b where b.blocked_id = uid)
   order by m.joined_at;
$$;

do $$
declare n integer;
begin
  select count(*) into n from pg_proc
   where proname in ('people_search', 'squadron_roster')
     and prosrc like '%invisible%';
  if n <> 2 then raise exception '0032: Fly solo is still not on the server (%)', n; end if;
end $$;

-- ===========================================================================
-- AND PRESENCE READS IT TOO, BECAUSE THE WRITE SIDE IS PER-DEVICE
-- ===========================================================================
-- presence.js gates the WRITE and deletes the row, which is the strongest
-- shape available: nothing is left for anybody to read, so no reader has to
-- cooperate. That is true, and it is true PER DEVICE.
--
-- The switch is stored twice on purpose (flySolo.js): `pilot_profiles.invisible`
-- is the account, and a localStorage mirror is what the plain functions read
-- synchronously. Only the second one gates the heartbeat — so a student who
-- turns Fly solo on on their phone is hidden from their phone, and their
-- LAPTOP, still open on a module, carries on writing presence rows for them
-- every forty-five seconds. Nobody sees them, except everybody.
--
-- The same gap swallows a row when the switch goes on with the tab already
-- closed: the delete never runs and the row sits there until the window
-- expires.
--
-- So the read cooperates as well. `presence_visible` is the presence table
-- minus anybody whose account says invisible, and it is a view so every
-- existing reader becomes one string different rather than one query more.
create or replace view presence_visible as
  select p.*
    from presence p
    left join pilot_profiles pp on pp.user_id = p.user_id
   where not coalesce(pp.invisible, false);

grant select on presence_visible to anon, authenticated;

do $$
declare n integer;
begin
  select count(*) into n from pg_views where viewname = 'presence_visible';
  if n <> 1 then raise exception '0032: presence_visible is missing'; end if;
end $$;


-- ############################################################################
-- 0033_the_avatar_is_ours.sql
-- ############################################################################

-- 0033 — the photo on a licence is this app's, not Clerk's.
--
-- Run after 0032. Additive: four columns and one bucket. Drops nothing.
-- Safe to re-run.
--
-- ===========================================================================
-- THE BUG THIS EXISTS FOR
-- ===========================================================================
-- The licence card read Clerk's `user.imageUrl`:
--
--     const photo = !flySolo && user?.imageUrl ? user.imageUrl : null;
--
-- `user.imageUrl` is NEVER null. With no photo set, Clerk serves a generated
-- default from img.clerk.com — a grey glyph with the account's initials baked
-- into it. So the falsy branch was unreachable, the app's own initials
-- component never rendered, and the colour somebody picked had nothing to
-- paint.
--
-- "Use your initials" made it worse: it called
-- `user.setProfileImage({ file: null })`, which throws — that is the error the
-- owner sees — and on the versions where it does not, Clerk simply goes back
-- to serving its default.
--
-- So the photo moves here. Clerk is the sign-in provider; it is not the avatar
-- store. `photo_url` null means initials, and that is a state this app can
-- actually reach.
--
-- ===========================================================================
-- WHY THE POSITION IS STORED AND THE CROP IS NOT
-- ===========================================================================
-- The cover is cropped on the way in (0030): what is uploaded is a 640x128
-- canvas, because a cover is a band and a photo is not that shape. An avatar
-- is a circle over a square, and keeping the square lets somebody re-centre it
-- later without re-uploading — which is what the reference's crop does, with a
-- zoom and a drag that it stores as three numbers rather than baking in.
--
-- photo_zoom is a percentage (100 = fit), photo_x/photo_y are percentages of
-- the frame, both clamped to the slack the zoom creates. The reference's own
-- limits: `lim = (z - 1) * 50`.

alter table pilot_profiles add column if not exists photo_url  text;
alter table pilot_profiles add column if not exists photo_zoom integer not null default 100;
alter table pilot_profiles add column if not exists photo_x    integer not null default 0;
alter table pilot_profiles add column if not exists photo_y    integer not null default 0;

do $$
begin
  -- The same rule 0030 puts on cover_image: a URL in this project's own public
  -- storage and nothing else. Without it the column is a place to park any
  -- string, and the card renders it into an <img src>.
  if not exists (select 1 from pg_constraint where conname = 'photo_url_is_ours') then
    alter table pilot_profiles add constraint photo_url_is_ours
      check (photo_url is null or photo_url ~ '^https://[a-z0-9-]+\.supabase\.co/storage/v1/object/public/');
  end if;
  -- The reference's slider is 100 to 300 and its pan is +/- (z-1)*50, which at
  -- the maximum is +/- 100. Stored wider than the UI allows on purpose: a
  -- value the server refuses is a save that fails for a reason nobody can see.
  if not exists (select 1 from pg_constraint where conname = 'photo_frame_sane') then
    alter table pilot_profiles add constraint photo_frame_sane
      check (photo_zoom between 100 and 400
         and photo_x between -100 and 100
         and photo_y between -100 and 100);
  end if;
end $$;

-- ===========================================================================
-- AND NOTHING FROM img.clerk.com MAY BE STORED
-- ===========================================================================
-- Belt and braces for the guard in src/lib/avatar.js. If a Clerk URL ever
-- reached this column the bug would be back, silently, and it would look like
-- the app's own photo.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'photo_url_not_clerk') then
    alter table pilot_profiles add constraint photo_url_not_clerk
      check (photo_url is null or photo_url !~* 'clerk\.com');
  end if;
end $$;

-- ================================================================ storage
-- Its own bucket rather than a corner of `covers`: an avatar is square and a
-- cover is a 5:1 band, they are replaced independently, and a bucket named
-- `covers` holding avatars is the kind of thing that is true for a year and
-- then confusing for ever.
--
-- AND IT NEEDS A SELECT POLICY TO BE ABLE TO INSERT AT ALL — see 0031. An
-- upload with x-upsert makes storage-api look first; with no select policy
-- that look is refused and the API reports the whole request as an insert
-- violation. That cost an afternoon once already.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('avatars', 'avatars', true, 1048576,
        array['image/webp', 'image/png', 'image/jpeg', 'image/gif'])
on conflict (id) do update
  set public             = excluded.public,
      file_size_limit    = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists avatars_read on storage.objects;
create policy avatars_read on storage.objects
  for select to public
  using (bucket_id = 'avatars');

drop policy if exists avatars_upload on storage.objects;
create policy avatars_upload on storage.objects
  for insert to public
  with check (
    bucket_id = 'avatars'
    and array_length(storage.foldername(name), 1) = 1
    and name = (storage.foldername(name))[1] || '/avatar.webp'
  );

drop policy if exists avatars_replace on storage.objects;
create policy avatars_replace on storage.objects
  for update to public
  using (bucket_id = 'avatars')
  with check (
    bucket_id = 'avatars'
    and name = (storage.foldername(name))[1] || '/avatar.webp'
  );

-- ===========================================================================
-- THE VIEWER'S READ CARRIES THE FACE
-- ===========================================================================
-- 0030's licence_card returns a fixed column list. A card without the photo is
-- a card that draws the wrong face for everybody but its owner, so the four
-- go on the end. Everything else about that function is unchanged, including
-- the Fly solo and block rules.
--
-- DROPPED AND RECREATED, because a function's return columns cannot be
-- widened in place — 0017 hit the same wall and took a new name for it. This
-- one is three days old and this repo owns its only caller, so it can simply
-- be replaced; the drop and the create are in one script and therefore one
-- transaction, so there is no moment when it is missing.
drop function if exists licence_card(text, text);
create or replace function licence_card(p_viewer text, p_user text)
returns table (
  user_id text, callsign text, real_name text, code text,
  bio text, phrase text, cover text, cover_ink text, cover_image text,
  is_staff boolean, hours_s integer, lessons_signed integer, days_flown integer,
  stamp_shape text, stamp_code text, stamp_rim boolean, stamp_ring text,
  stamp_pattern text, stamp_ink text, stamp_seed integer, stamp_issued_at timestamptz,
  photo_url text, photo_zoom integer, photo_x integer, photo_y integer
)
language sql
stable
security definer
set search_path = public
as $$
  select p.user_id, p.callsign, p.real_name, p.code,
         p.bio, p.phrase, p.cover, p.cover_ink, p.cover_image,
         p.is_staff, p.hours_s, p.lessons_signed, p.days_flown,
         p.stamp_shape, p.stamp_code, p.stamp_rim, p.stamp_ring,
         p.stamp_pattern, p.stamp_ink, p.stamp_seed, p.stamp_issued_at,
         p.photo_url, p.photo_zoom, p.photo_x, p.photo_y
    from pilot_profiles p
   where p.user_id = p_user
     and (p.user_id = p_viewer or p.invisible = false)
     and not exists (
       select 1 from blocks b
        where (b.user_id = p_viewer and b.blocked_id = p_user)
           or (b.user_id = p_user   and b.blocked_id = p_viewer))
$$;

do $$
declare n integer;
begin
  select count(*) into n from information_schema.columns
   where table_name = 'pilot_profiles'
     and column_name in ('photo_url', 'photo_zoom', 'photo_x', 'photo_y');
  if n <> 4 then raise exception '0033: the photo columns are missing (%)', n; end if;

  select count(*) into n from storage.buckets where id = 'avatars' and public;
  if n <> 1 then raise exception '0033: the avatars bucket is missing or not public'; end if;

  select count(*) into n from pg_policies
   where schemaname = 'storage' and tablename = 'objects'
     and policyname in ('avatars_upload', 'avatars_read', 'avatars_replace');
  if n <> 3 then raise exception '0033: the avatars policies are incomplete (%)', n; end if;
end $$;


-- ############################################################################
-- 0034_quiz_runs_and_the_board.sql
-- ############################################################################

-- 0034 — every sitting is a row, and the board is ranked on the server.
--
-- R5 and R6 of the exam brief (docs/launch/BRIEF-exam.md), which the owner
-- asked for as drawn. Conflict 1 of BRIEF-exam-conflicts.md, now settled.
--
-- WHAT DID NOT EXIST. A quiz score lived in `pw-quiz-scores`, one number per
-- chapter, inside the student's own `user_progress` row. It was the LATEST
-- score, overwritten by the next sitting, private to that account, and carried
-- no time at all. `question_attempts` is per question rather than per sitting,
-- so it cannot say how long a paper took either. There was nothing to rank.
--
-- ADDITIVE. Nothing is dropped, nothing is rewritten, nothing is migrated out
-- of `pw-quiz-scores` — the Library row and the Flight Deck's gyro keep
-- reading it exactly as they do, and this sits beside them.
--
-- ------------------------------------------------------------------ the time
-- R5: "Time is submittedAt − startedAt in real seconds, decided server-side,
-- never from the countdown in the browser."
--
-- Taken literally, and that is a decision with a cost worth writing down. A
-- paper in this app is RESUMABLE: the attempt is saved on every change, the
-- clock stops when the paper leaves the screen, and "Leave it for now" is a
-- first-class choice in the end-exam dialog. So a student who starts a paper,
-- leaves it overnight and finishes it in the morning has a wall clock of
-- fourteen hours and a countdown that barely moved.
--
-- The wall clock is what is stored, because it is the only number the browser
-- cannot make up, and R5 exists to stop the browser making it up. The cost is
-- bounded by the ordering itself: rank is SCORE first and time only splits
-- ties, so leaving a paper costs you nothing unless somebody matched your
-- score exactly. The board says "Ranked on score, then time taken", which is
-- true of the wall clock in a way it would not be of a paused countdown.
--
-- Both ends are stamped by THIS function, never sent: `start_quiz_run` writes
-- started_at = now(), `finish_quiz_run` writes submitted_at = now().
--
-- ------------------------------------------------------- an unfinished run
-- R5's own test list ends "an unfinished attempt never appearing". A run is
-- inserted when the paper opens, with submitted_at null, and the board filters
-- those out. Re-opening a paper you already started returns the SAME row
-- rather than a second one, because resuming a paper is not a new sitting and
-- must not restart the clock.
--
-- ------------------------------------------------------ the callsign is per run
-- R6: "One account can appear several times under different callsigns, each
-- ranked normally." A callsign here is one per account, claimed and unique, so
-- there is nothing to pick per run. What there is instead is TIME: the run
-- snapshots the callsign and the three-character code the account had at the
-- moment it was handed in. Change your callsign and sit the paper again and
-- the board shows two rows, under two names, against one code — which is
-- exactly the shape R6 describes, without inventing a second identity system
-- for one screen. `[CODE] Callsign` is what a row reads.
--
-- -------------------------------------------------------------- who is on it
-- Everyone on the module, minus two:
--   · anyone flying solo (`pilot_profiles.invisible`) — 0032 is explicit that
--     Fly solo means "I am not here", and a leaderboard is the loudest place
--     to be somewhere;
--   · anyone blocked either way.
-- YOU ARE ALWAYS ON YOUR OWN BOARD, flying solo or not, for the same reason
-- 0032 keeps you on your own roster: a board that leaves you off cannot tell
-- you where you came, and "You're 3rd of 12" would be a lie about a list you
-- are not in.
--
-- ---------------------------------------------------------------- the policies
-- Open, like every other table here: the client is a bare PostgrestClient
-- sending the publishable key as its own bearer, so `auth.uid()` and
-- `auth.jwt()` are NULL on every request (0009's header). The cost is the same
-- one 0028 states: anyone holding the publishable key can read `quiz_runs`.
-- What that exposes is what the board already shows to everyone on the module.

create table if not exists quiz_runs (
  id           uuid        primary key default gen_random_uuid(),
  user_id      text        not null,
  module_code  text        not null,
  chapter_id   text        not null,
  quiz_id      text        not null,
  total        integer     not null,
  score        integer,
  callsign     text,
  code         text,
  started_at   timestamptz not null default now(),
  submitted_at timestamptz,
  constraint quiz_runs_total_positive check (total > 0),
  constraint quiz_runs_score_in_range check (score is null or (score >= 0 and score <= total)),
  -- A run is either open or finished. A score without a time, or a time
  -- without a score, is a row nothing can rank and nothing can resume.
  constraint quiz_runs_finished_together check (
    (submitted_at is null and score is null) or (submitted_at is not null and score is not null)),
  constraint quiz_runs_not_before_it_started check (
    submitted_at is null or submitted_at >= started_at)
);

create index if not exists quiz_runs_board_idx
  on quiz_runs (quiz_id, score desc, submitted_at)
  where submitted_at is not null;
-- The open run a student comes back to. Partial, so it is small however many
-- sittings the table ends up holding.
create index if not exists quiz_runs_open_idx
  on quiz_runs (user_id, quiz_id) where submitted_at is null;

alter table quiz_runs enable row level security;
drop policy if exists quiz_runs_open on quiz_runs;
create policy quiz_runs_open on quiz_runs for all using (true) with check (true);

-- --------------------------------------------------------------- the writes
-- Opening a paper. Returns the run to carry, which is the one already open if
-- there is one: coming back to a paper is the same sitting.
create or replace function start_quiz_run(
  uid text, p_module text, p_chapter text, p_quiz text, p_total integer)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare v_id uuid;
begin
  if uid is null or p_quiz is null or coalesce(p_total, 0) <= 0 then return null; end if;

  select id into v_id from quiz_runs
   where user_id = uid and quiz_id = p_quiz and submitted_at is null
   order by started_at desc limit 1;
  if v_id is not null then return v_id; end if;

  insert into quiz_runs (user_id, module_code, chapter_id, quiz_id, total)
       values (uid, p_module, p_chapter, p_quiz, p_total)
    returning id into v_id;
  return v_id;
end $$;

-- Handing it in. The time is decided here and the name is snapshotted here.
-- Idempotent: a second call on a finished run changes nothing, so a retry
-- after a dropped connection cannot move somebody's time.
create or replace function finish_quiz_run(uid text, p_run uuid, p_score integer)
returns quiz_runs
language plpgsql
security definer
set search_path = public
as $$
declare v_row quiz_runs;
begin
  update quiz_runs r
     set submitted_at = now(),
         score        = greatest(0, least(p_score, r.total)),
         callsign     = (select p.callsign from pilot_profiles p where p.user_id = uid),
         code         = (select p.code     from pilot_profiles p where p.user_id = uid)
   where r.id = p_run and r.user_id = uid and r.submitted_at is null
  returning * into v_row;

  if v_row.id is null then
    select * into v_row from quiz_runs where id = p_run and user_id = uid;
  end if;
  return v_row;
end $$;

-- ---------------------------------------------------------------- the board
-- R5: the client only formats. Rank, seconds and place all come from here —
-- and so does the STAMP, in the same answer, because R7 puts one on every row
-- and a board of fifty rows must not be fifty more round trips.
--
-- The stamp is the account's CURRENT one, not a snapshot like the callsign
-- beside it. That is R7 rather than an oversight: "One mark per student ...
-- Changing a student's ink changes the mark in both places at once." A
-- callsign names a sitting; a stamp is who signed it.
--
-- DROPPED AND CREATED, not replaced: a function's return columns cannot be
-- widened in place (0017 learned this the hard way and had to take a new
-- name). Nothing is deployed against this one yet, so it can keep its name.
drop function if exists quiz_leaderboard(text, text, integer);
create or replace function quiz_leaderboard(uid text, p_quiz text, p_limit integer default 50)
returns table (
  rank        bigint,
  run_id      uuid,
  user_id     text,
  callsign    text,
  code        text,
  score       integer,
  total       integer,
  seconds     integer,
  is_you      boolean,
  runs_total  bigint,
  stamp_shape     text,
  stamp_code      text,
  stamp_rim       boolean,
  stamp_ring      text,
  stamp_pattern   text,
  stamp_ink       text,
  stamp_seed      integer,
  stamp_issued_at timestamptz
)
language sql
stable
security definer
set search_path = public
as $$
  with visible as (
    select r.*
      from quiz_runs r
      left join pilot_profiles p on p.user_id = r.user_id
     where r.quiz_id = p_quiz
       and r.submitted_at is not null
       and (
         r.user_id = uid                                   -- always on your own board
         or (
           not coalesce(p.invisible, false)                -- Fly solo means not here
           and not exists (select 1 from blocks b
                            where (b.user_id = uid      and b.blocked_id = r.user_id)
                               or (b.user_id = r.user_id and b.blocked_id = uid))
         )
       )
  ),
  ranked as (
    select
      row_number() over (
        order by v.score desc,
                 extract(epoch from (v.submitted_at - v.started_at)) asc,
                 v.submitted_at asc)                       -- a stable third key
        as rank,
      v.id as run_id,
      v.user_id,
      coalesce(nullif(btrim(v.callsign), ''), 'Someone') as callsign,
      coalesce(nullif(btrim(v.code), ''), '---')          as code,
      v.score,
      v.total,
      greatest(0, floor(extract(epoch from (v.submitted_at - v.started_at)))::integer) as seconds,
      (v.user_id = uid) as is_you,
      count(*) over () as runs_total,
      sp.stamp_shape, sp.stamp_code, sp.stamp_rim, sp.stamp_ring,
      sp.stamp_pattern, sp.stamp_ink, sp.stamp_seed, sp.stamp_issued_at
    from visible v
    left join pilot_profiles sp on sp.user_id = v.user_id
  )
  select rank, run_id, user_id, callsign, code, score, total, seconds, is_you, runs_total,
         stamp_shape, stamp_code, stamp_rim, stamp_ring,
         stamp_pattern, stamp_ink, stamp_seed, stamp_issued_at
    from ranked
   order by rank
   limit greatest(1, least(coalesce(p_limit, 50), 200));
$$;

do $$
declare n integer;
begin
  select count(*) into n from information_schema.tables
   where table_schema = 'public' and table_name = 'quiz_runs';
  if n <> 1 then raise exception '0034: quiz_runs is missing'; end if;

  select count(*) into n from pg_constraint
   where conname in ('quiz_runs_total_positive', 'quiz_runs_score_in_range',
                     'quiz_runs_finished_together', 'quiz_runs_not_before_it_started');
  if n <> 4 then raise exception '0034: the run constraints are incomplete (%)', n; end if;

  select count(*) into n from pg_proc
   where proname in ('start_quiz_run', 'finish_quiz_run', 'quiz_leaderboard');
  if n <> 3 then raise exception '0034: the run functions are incomplete (%)', n; end if;

  select count(*) into n from pg_policies
   where schemaname = 'public' and tablename = 'quiz_runs';
  if n < 1 then raise exception '0034: quiz_runs has no policy'; end if;
end $$;


-- ############################################################################
-- 0035_the_code_is_the_stamp.sql
-- ############################################################################

-- =============================================================================
-- 0035 — THE CODE IS THE STAMP.
-- -----------------------------------------------------------------------------
-- Until now they were two things. 0016's code was claimed at signup, or on the
-- first visit to the licence, from a 31-character alphabet. 0029's stamp
-- carried a code of its own, typed in the creator and never claimed. So a
-- student could issue a stamp reading one code while their account held
-- another. The owner (2026-09-21): "the code is the stamp and the stamp is the
-- code, they are issued together".
--
--   1. issue_licence claims the code AND issues the stamp around it, in one
--      statement. Either both happen or neither does, and they cannot differ.
--   2. The code takes any letter and any digit. 0016 left out 0, 1, O, I and L
--      so that a code read off a photograph could not be misread. But a
--      student typing "A10" watched the 1 and the 0 vanish, and read that as
--      "only letters". SUGGESTIONS still avoid those five (suggest_code is
--      unchanged), so nobody is handed an ambiguous one; they can choose one.
--   3. Once the stamp is issued, the code is as permanent as the stamp. claim_code
--      refuses to move it, and the trigger 0029 wrote refuses it too.
--
-- ADDITIVE. The constraint is replaced, not the column. issue_stamp and
-- claim_code keep their signatures, so a bundle deployed before this keeps
-- working until the new one lands.
-- =============================================================================

alter table pilot_profiles drop constraint if exists pilot_code_shape;
alter table pilot_profiles
  add constraint pilot_code_shape check (code is null or code ~ '^[A-Z0-9]{3}$');

create or replace function claim_code(uid text, want text)
returns text
language plpgsql
volatile
as $$
declare taken boolean;
begin
  if want is null or want !~ '^[A-Z0-9]{3}$' then
    return null;
  end if;

  -- An issued stamp carries its code. Moving one would reprint every stamp.
  if exists (select 1 from pilot_profiles p
              where p.user_id = uid and p.stamp_issued_at is not null
                and p.code is distinct from want) then
    return null;
  end if;

  select exists (
    select 1 from pilot_profiles p where p.code = want and p.user_id <> uid
  ) into taken;
  if taken then return null; end if;

  insert into pilot_profiles (user_id, code) values (uid, want)
  on conflict (user_id) do update set code = excluded.code;

  return want;
exception
  when unique_violation then return null;
end $$;

create or replace function issue_licence(
  uid text, p_code text, p_shape text, p_rim boolean,
  p_ring text, p_pattern text, p_ink text)
returns pilot_profiles
language plpgsql
security definer
set search_path = public
as $$
declare
  want text;
  out_row pilot_profiles;
begin
  if uid is null or uid = '' then raise exception 'no pilot'; end if;

  want := upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'));
  if want !~ '^[A-Z0-9]{3}$' then
    raise exception 'a licence needs a three-character code';
  end if;

  insert into pilot_profiles (user_id) values (uid)
  on conflict (user_id) do nothing;

  if exists (select 1 from pilot_profiles p where p.user_id = uid and p.stamp_issued_at is not null) then
    raise exception 'that stamp is already issued';
  end if;

  if exists (select 1 from pilot_profiles p where p.code = want and p.user_id <> uid) then
    raise exception 'that code is taken';
  end if;

  update pilot_profiles p set
    code = want,
    stamp_code = want,
    stamp_shape = p_shape,
    stamp_rim = coalesce(p_rim, true),
    stamp_ring = nullif(left(upper(regexp_replace(coalesce(p_ring, ''), '[^A-Za-z0-9 .''-]', '', 'g')), 10), ''),
    stamp_pattern = coalesce(p_pattern, 'none'),
    stamp_ink = p_ink,
    stamp_seed = 1 + floor(random() * 999998)::int,
    stamp_issued_at = now()
  where p.user_id = uid
  returning p.* into out_row;

  return out_row;
exception
  -- Somebody took it between the check and the write.
  when unique_violation then raise exception 'that code is taken';
end $$;

grant execute on function issue_licence(text, text, text, boolean, text, text, text) to anon, authenticated;

-- 0029's trigger, with the code added to what an issued stamp holds still.
create or replace function stamp_is_permanent() returns trigger
language plpgsql as $$
begin
  if old.stamp_issued_at is not null and (
       new.stamp_shape   is distinct from old.stamp_shape
    or new.stamp_code    is distinct from old.stamp_code
    or new.stamp_rim     is distinct from old.stamp_rim
    or new.stamp_ring    is distinct from old.stamp_ring
    or new.stamp_pattern is distinct from old.stamp_pattern
    or new.stamp_ink     is distinct from old.stamp_ink
    or new.stamp_seed    is distinct from old.stamp_seed
    or new.stamp_issued_at is distinct from old.stamp_issued_at
    or new.code          is distinct from old.code)
  then
    raise exception 'a stamp cannot be changed once it is issued';
  end if;
  return new;
end $$;


-- ############################################################################
-- 0036_the_stamp_engine_of_20_september.sql
-- ############################################################################

-- =============================================================================
-- 0036 — THE STAMP ENGINE OF 20 SEPTEMBER, ALL OF IT.
-- -----------------------------------------------------------------------------
-- The owner (2026-09-21) replaced the stamp engine and the creator with the
-- launch pack's own (docs/launch/code/05, 15, 03). Measured against the live
-- database before writing this, 0029's checks still described the stamp of
-- an earlier pack:
--
--   stamp_shape_known    seal, roundel, window, gauge, postage, tag
--   stamp_pattern_known  none, rays, waves, checks, swirl, guilloche
--
-- so a student who chose Crochet or Knurl — two of the six patterns the
-- creator has offered since 20 September — could not issue their stamp at
-- all, and shield and hex could never be stored. And the creator's three
-- other choices had nowhere to go: where the pattern sits (Both / Centre /
-- Rim), the pattern's own ink, and the code's own ink.
--
--   1. The shape check takes all eight shapes.
--   2. The pattern check takes the six, AND the two retired names (waves,
--      swirl): a check is re-validated against every existing row, and a
--      stamp is permanent, so a name that was ever issuable stays storable.
--   3. Three columns: stamp_pscope, stamp_pink, stamp_cink. Inks are stored
--      by NAME, like stamp_ink, and held to the same thirty-six.
--   4. They are as permanent as the rest of the stamp (the 0029 trigger).
--   5. issue_licence gains the three, as a NEW overload. PostgREST picks an
--      overload by the names of the arguments it is sent, so the bundle
--      deployed before this — which sends seven — keeps reaching the old
--      one, and the new bundle, which sends ten, reaches this one.
--
-- ADDITIVE for the data: no column or row is dropped. Two READ functions are
-- dropped and recreated wider, in this same transaction — see the foot.
-- =============================================================================

alter table pilot_profiles drop constraint if exists stamp_shape_known;
alter table pilot_profiles add constraint stamp_shape_known
  check (stamp_shape is null or stamp_shape in
    ('seal','roundel','window','gauge','postage','tag','shield','hex'));

alter table pilot_profiles drop constraint if exists stamp_pattern_known;
alter table pilot_profiles add constraint stamp_pattern_known
  check (stamp_pattern is null or stamp_pattern in
    ('none','rays','checks','guilloche','crochet','knurl','waves','swirl'));

alter table pilot_profiles add column if not exists stamp_pscope text;
alter table pilot_profiles add column if not exists stamp_pink   text;
alter table pilot_profiles add column if not exists stamp_cink   text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'stamp_pscope_known') then
    alter table pilot_profiles add constraint stamp_pscope_known
      check (stamp_pscope is null or stamp_pscope in ('both','centre','rim'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'stamp_pink_known') then
    alter table pilot_profiles add constraint stamp_pink_known
      check (stamp_pink is null or stamp_pink in (
        'Midnight','Lapiz','Miami','Baby','Powder','Glacier','Teal','Seafoam','Emerald','Racing','Sage','Matcha',
        'Olive','Khaki','Sand','Butter','Honey','Papaya','Clementine','Coral','Ruby','Cherry','Peach','Latte',
        'Mocha','Espresso','Nardo','Gunmetal','Chalk','Mauve','Blush','Bubblegum','Barbie','Lilac','Lavender','Plum'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'stamp_cink_known') then
    alter table pilot_profiles add constraint stamp_cink_known
      check (stamp_cink is null or stamp_cink in (
        'Midnight','Lapiz','Miami','Baby','Powder','Glacier','Teal','Seafoam','Emerald','Racing','Sage','Matcha',
        'Olive','Khaki','Sand','Butter','Honey','Papaya','Clementine','Coral','Ruby','Cherry','Peach','Latte',
        'Mocha','Espresso','Nardo','Gunmetal','Chalk','Mauve','Blush','Bubblegum','Barbie','Lilac','Lavender','Plum'));
  end if;
end $$;

create or replace function stamp_is_permanent() returns trigger
language plpgsql as $$
begin
  if old.stamp_issued_at is not null and (
       new.stamp_shape   is distinct from old.stamp_shape
    or new.stamp_code    is distinct from old.stamp_code
    or new.stamp_rim     is distinct from old.stamp_rim
    or new.stamp_ring    is distinct from old.stamp_ring
    or new.stamp_pattern is distinct from old.stamp_pattern
    or new.stamp_pscope  is distinct from old.stamp_pscope
    or new.stamp_ink     is distinct from old.stamp_ink
    or new.stamp_pink    is distinct from old.stamp_pink
    or new.stamp_cink    is distinct from old.stamp_cink
    or new.stamp_seed    is distinct from old.stamp_seed
    or new.stamp_issued_at is distinct from old.stamp_issued_at
    or new.code          is distinct from old.code)
  then
    raise exception 'a stamp cannot be changed once it is issued';
  end if;
  return new;
end $$;

create or replace function issue_licence(
  uid text, p_code text, p_shape text, p_rim boolean,
  p_ring text, p_pattern text, p_ink text,
  p_pscope text, p_pink text, p_cink text)
returns pilot_profiles
language plpgsql
security definer
set search_path = public
as $$
declare
  want text;
  out_row pilot_profiles;
begin
  if uid is null or uid = '' then raise exception 'no pilot'; end if;

  want := upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'));
  if want !~ '^[A-Z0-9]{3}$' then
    raise exception 'a licence needs a three-character code';
  end if;

  insert into pilot_profiles (user_id) values (uid)
  on conflict (user_id) do nothing;

  if exists (select 1 from pilot_profiles p where p.user_id = uid and p.stamp_issued_at is not null) then
    raise exception 'that stamp is already issued';
  end if;

  if exists (select 1 from pilot_profiles p where p.code = want and p.user_id <> uid) then
    raise exception 'that code is taken';
  end if;

  update pilot_profiles p set
    code = want,
    stamp_code = want,
    stamp_shape = p_shape,
    stamp_rim = coalesce(p_rim, true),
    stamp_ring = nullif(left(upper(regexp_replace(coalesce(p_ring, ''), '[^A-Za-z0-9 .''-]', '', 'g')), 10), ''),
    stamp_pattern = coalesce(p_pattern, 'none'),
    stamp_pscope = case when coalesce(p_pattern, 'none') = 'none' then null else coalesce(p_pscope, 'both') end,
    stamp_ink = p_ink,
    stamp_pink = case when coalesce(p_pattern, 'none') = 'none' then null else p_pink end,
    stamp_cink = p_cink,
    stamp_seed = 1 + floor(random() * 999998)::int,
    stamp_issued_at = now()
  where p.user_id = uid
  returning p.* into out_row;

  return out_row;
exception
  when unique_violation then raise exception 'that code is taken';
end $$;

grant execute on function issue_licence(text, text, text, boolean, text, text, text, text, text, text) to anon, authenticated;

-- ===========================================================================
-- AND EVERYBODY ELSE SEES ALL OF IT
-- ===========================================================================
-- licence_card (what a classmate opens) and quiz_leaderboard (the stamp beside
-- a run) return fixed column lists, so a stamp read through either would be
-- drawn without where its pattern sits or its two extra inks. The three go on
-- the end of each. DROPPED AND RECREATED, as 0033 and 0034 did and for their
-- reason: a function's return columns cannot be widened in place. Each drop
-- and create is in this one script and therefore one transaction, so there is
-- no moment when either is missing; and a bundle deployed before this reads
-- the columns it knows and ignores three more.
drop function if exists licence_card(text, text);
create or replace function licence_card(p_viewer text, p_user text)
returns table (
  user_id text, callsign text, real_name text, code text,
  bio text, phrase text, cover text, cover_ink text, cover_image text,
  is_staff boolean, hours_s integer, lessons_signed integer, days_flown integer,
  stamp_shape text, stamp_code text, stamp_rim boolean, stamp_ring text,
  stamp_pattern text, stamp_ink text, stamp_seed integer, stamp_issued_at timestamptz,
  photo_url text, photo_zoom integer, photo_x integer, photo_y integer,
  stamp_pscope text, stamp_pink text, stamp_cink text
)
language sql
stable
security definer
set search_path = public
as $$
  select p.user_id, p.callsign, p.real_name, p.code,
         p.bio, p.phrase, p.cover, p.cover_ink, p.cover_image,
         p.is_staff, p.hours_s, p.lessons_signed, p.days_flown,
         p.stamp_shape, p.stamp_code, p.stamp_rim, p.stamp_ring,
         p.stamp_pattern, p.stamp_ink, p.stamp_seed, p.stamp_issued_at,
         p.photo_url, p.photo_zoom, p.photo_x, p.photo_y,
         p.stamp_pscope, p.stamp_pink, p.stamp_cink
    from pilot_profiles p
   where p.user_id = p_user
     and (p.user_id = p_viewer or p.invisible = false)
     and not exists (
       select 1 from blocks b
        where (b.user_id = p_viewer and b.blocked_id = p_user)
           or (b.user_id = p_user   and b.blocked_id = p_viewer))
$$;

drop function if exists quiz_leaderboard(text, text, integer);
create or replace function quiz_leaderboard(uid text, p_quiz text, p_limit integer default 50)
returns table (
  rank        bigint,
  run_id      uuid,
  user_id     text,
  callsign    text,
  code        text,
  score       integer,
  total       integer,
  seconds     integer,
  is_you      boolean,
  runs_total  bigint,
  stamp_shape     text,
  stamp_code      text,
  stamp_rim       boolean,
  stamp_ring      text,
  stamp_pattern   text,
  stamp_ink       text,
  stamp_seed      integer,
  stamp_issued_at timestamptz,
  stamp_pscope    text,
  stamp_pink      text,
  stamp_cink      text
)
language sql
stable
security definer
set search_path = public
as $$
  with visible as (
    select r.*
      from quiz_runs r
      left join pilot_profiles p on p.user_id = r.user_id
     where r.quiz_id = p_quiz
       and r.submitted_at is not null
       and (
         r.user_id = uid                                   -- always on your own board
         or (
           not coalesce(p.invisible, false)                -- Fly solo means not here
           and not exists (select 1 from blocks b
                            where (b.user_id = uid      and b.blocked_id = r.user_id)
                               or (b.user_id = r.user_id and b.blocked_id = uid))
         )
       )
  ),
  ranked as (
    select
      row_number() over (
        order by v.score desc,
                 extract(epoch from (v.submitted_at - v.started_at)) asc,
                 v.submitted_at asc)                       -- a stable third key
        as rank,
      v.id as run_id,
      v.user_id,
      coalesce(nullif(btrim(v.callsign), ''), 'Someone') as callsign,
      coalesce(nullif(btrim(v.code), ''), '---')          as code,
      v.score,
      v.total,
      greatest(0, floor(extract(epoch from (v.submitted_at - v.started_at)))::integer) as seconds,
      (v.user_id = uid) as is_you,
      count(*) over () as runs_total,
      sp.stamp_shape, sp.stamp_code, sp.stamp_rim, sp.stamp_ring,
      sp.stamp_pattern, sp.stamp_ink, sp.stamp_seed, sp.stamp_issued_at,
      sp.stamp_pscope, sp.stamp_pink, sp.stamp_cink
    from visible v
    left join pilot_profiles sp on sp.user_id = v.user_id
  )
  select rank, run_id, user_id, callsign, code, score, total, seconds, is_you, runs_total,
         stamp_shape, stamp_code, stamp_rim, stamp_ring,
         stamp_pattern, stamp_ink, stamp_seed, stamp_issued_at,
         stamp_pscope, stamp_pink, stamp_cink
    from ranked
   order by rank
   limit greatest(1, least(coalesce(p_limit, 50), 200));
$$;


-- ############################################################################
-- 0037_six_shapes_again.sql
-- ############################################################################

-- =============================================================================
-- 0037 — SIX SHAPES, AGAIN.
-- -----------------------------------------------------------------------------
-- 0036 let the database take all eight of the engine's shapes. The same day
-- the owner took the shield and the hex out of the creator ("no hex bolt no
-- shield" — the hex reads as a bolt head), so the server goes back to
-- refusing both, as 0029 did: §4 asks for the shape to be validated on the
-- server as well as in the UI, and a shape the UI does not offer is one only
-- a hand-written request could send.
--
-- Checked against the live database before writing this: no row carries
-- either shape, so the narrower check validates cleanly. The engine still
-- draws both (src/lib/stamp-engine.js is the reference byte for byte).
-- =============================================================================

alter table pilot_profiles drop constraint if exists stamp_shape_known;
alter table pilot_profiles add constraint stamp_shape_known
  check (stamp_shape is null or stamp_shape in
    ('seal','roundel','window','gauge','postage','tag'));


-- ############################################################################
-- 0038_who_has_finished_a_quiz.sql
-- ############################################################################

-- =============================================================================
-- 0038 — WHO HAS FINISHED A QUIZ.
-- -----------------------------------------------------------------------------
-- Rule 4 of the quiz-stamps brief (2026-09-23): each Library quiz row carries a
-- line of finisher stamps underneath — one per person, their most recent finish
-- first, at most eleven, then "+n", then the count in words.
--
--   1. ONE ROW PER PERSON, not per run. The brief keeps the board's rows as
--      runs and de-duplicates at render; this line is about PEOPLE, and a
--      student who sat a paper four times is one stamp. So the grouping is in
--      the query — `max(submitted_at)` is that person's most recent finish —
--      while `quiz_leaderboard` is untouched and still returns every run.
--   2. YOURS FIRST (owner, 2026-09-23, on the brief's open question 2), then
--      recency. It is in the ordering rather than the client so that the cap
--      cannot drop you: a student who finished first and is now thirtieth by
--      recency would otherwise never see their own stamp on the row.
--   3. `finishers` is the whole count for that quiz, not the capped one — it
--      is what the row says in words, and "+n" is the difference.
--   4. FLY SOLO AND BLOCKS, exactly as 0034's board has them: somebody
--      invisible is on nobody else's line, a block cuts both ways, and you are
--      always on your own.
--   5. Several quizzes in one call, because the Library draws a row per
--      chapter and a call per row is a call per row.
--
-- The stamp columns are the account's CURRENT ones (0029, 0036), like the
-- board's: a stamp is who signed it, not a snapshot of a night's run.
-- =============================================================================

create or replace function quiz_finishers(uid text, p_quizzes text[], p_cap integer default 11)
returns table (
  quiz_id         text,
  user_id         text,
  callsign        text,
  code            text,
  finished_at     timestamptz,
  is_you          boolean,
  finishers       integer,
  stamp_shape     text,
  stamp_code      text,
  stamp_rim       boolean,
  stamp_ring      text,
  stamp_pattern   text,
  stamp_pscope    text,
  stamp_ink       text,
  stamp_pink      text,
  stamp_cink      text,
  stamp_seed      integer,
  stamp_issued_at timestamptz
)
language sql
stable
security definer
set search_path = public
as $$
  with visible as (
    select r.quiz_id, r.user_id, r.submitted_at
      from quiz_runs r
      left join pilot_profiles p on p.user_id = r.user_id
     where r.quiz_id = any(coalesce(p_quizzes, array[]::text[]))
       and r.submitted_at is not null
       and (
         r.user_id = uid                                   -- always on your own
         or (
           not coalesce(p.invisible, false)                -- Fly solo means not here
           and not exists (select 1 from blocks b
                            where (b.user_id = uid       and b.blocked_id = r.user_id)
                               or (b.user_id = r.user_id and b.blocked_id = uid))
         )
       )
  ),
  people as (
    select v.quiz_id, v.user_id, max(v.submitted_at) as finished_at
      from visible v
     group by v.quiz_id, v.user_id
  ),
  ranked as (
    select
      pe.quiz_id, pe.user_id, pe.finished_at,
      count(*) over (partition by pe.quiz_id)                      as finishers,
      row_number() over (
        partition by pe.quiz_id
        order by (pe.user_id = uid) desc, pe.finished_at desc, pe.user_id) as rn
      from people pe
  )
  select
    r.quiz_id,
    r.user_id,
    coalesce(nullif(btrim(pp.callsign), ''), 'Someone') as callsign,
    coalesce(nullif(btrim(pp.code), ''), '---')         as code,
    r.finished_at,
    (r.user_id = uid)                                    as is_you,
    r.finishers::integer,
    pp.stamp_shape, pp.stamp_code, pp.stamp_rim, pp.stamp_ring,
    pp.stamp_pattern, pp.stamp_pscope, pp.stamp_ink, pp.stamp_pink, pp.stamp_cink,
    pp.stamp_seed, pp.stamp_issued_at
    from ranked r
    left join pilot_profiles pp on pp.user_id = r.user_id
   where r.rn <= greatest(1, least(coalesce(p_cap, 11), 24))
   order by r.quiz_id, r.rn
$$;

grant execute on function quiz_finishers(text, text[], integer) to anon, authenticated;

do $$
declare n integer;
begin
  select count(*) into n from pg_proc p
    join pg_namespace ns on ns.oid = p.pronamespace
   where ns.nspname = 'public' and p.proname = 'quiz_finishers';
  if n <> 1 then raise exception '0038: quiz_finishers is missing (%)', n; end if;
end $$;


-- ############################################################################
-- 0039_one_to_three_and_one_change.sql
-- ############################################################################

-- =============================================================================
-- 0039 — A CODE IS ONE TO THREE CHARACTERS, AND EVERYBODY WHO HAS A STAMP
--        ALREADY GETS ONE CHANGE.
-- -----------------------------------------------------------------------------
-- The owner, 2026-09-23: "the stamps are locked at three digits, it should be
-- letters and numbers, a max of 3 a min of 1, and allow all users to change,
-- as two users have made stamps they weren't satisfied with due to the min of
-- 3 rule — a fix for the two active users right now, then back to the one
-- time stamp rule."
--
-- Two changes, and the second one is the delicate one.
--
-- 1 · THE SHAPE. `^[A-Z0-9]{3}$` becomes `^[A-Z0-9]{1,3}$`, in the CHECK, in
--     claim_code and in both arities of issue_licence. Letters and numbers
--     were always both allowed; what was locked was the length.
--
-- 2 · ONE CHANGE, THEN PERMANENT AGAIN. A credit rather than an amnesty
--     window: `pilot_profiles.stamp_redo` is a count, every account that has
--     already issued a stamp is given exactly one here, and issue_licence
--     spends it. When it is spent the account is back under the original
--     rule with nothing to turn off later, and no date anywhere decides who
--     is allowed — which is what a window would have meant, and what would
--     have had to be remembered and reversed.
--
--     THE TRIGGER IS WHAT MAKES A STAMP PERMANENT, and it is not being
--     loosened. It now allows exactly one shape of change: the same UPDATE
--     that alters the stamp must also take the credit down by one. Anything
--     else raises, as before. And because RLS here is open by design (0009's
--     header: the anon key is the bearer on every request, access control is
--     the app's), the credit itself has to be protected or it would be a way
--     to hand yourself another change: the trigger refuses any UPDATE that
--     RAISES stamp_redo unless `pw.grant_redo` is set for the transaction,
--     and the only thing that sets it is grant_stamp_redo(), which is
--     granted to service_role and to nobody else. anon cannot reach it.
--
-- The backfill below runs with the trigger off for exactly that reason: the
-- migration is the first grant, and it is subject to the same rule it writes.
-- =============================================================================

-- ---------------------------------------------------------------- 1 · shape
alter table pilot_profiles drop constraint if exists pilot_code_shape;
alter table pilot_profiles
  add constraint pilot_code_shape check (code is null or code ~ '^[A-Z0-9]{1,3}$');

-- --------------------------------------------------------------- 2 · credit
alter table pilot_profiles add column if not exists stamp_redo integer not null default 0;
alter table pilot_profiles drop constraint if exists stamp_redo_sane;
alter table pilot_profiles add constraint stamp_redo_sane check (stamp_redo >= 0 and stamp_redo <= 3);

-- ------------------------------------------------------- 3 · what may change
create or replace function stamp_is_permanent() returns trigger
language plpgsql as $$
declare
  changed boolean;
  spends  boolean;
begin
  changed := old.stamp_issued_at is not null and (
       new.stamp_shape   is distinct from old.stamp_shape
    or new.stamp_code    is distinct from old.stamp_code
    or new.stamp_rim     is distinct from old.stamp_rim
    or new.stamp_ring    is distinct from old.stamp_ring
    or new.stamp_pattern is distinct from old.stamp_pattern
    or new.stamp_pscope  is distinct from old.stamp_pscope
    or new.stamp_ink     is distinct from old.stamp_ink
    or new.stamp_pink    is distinct from old.stamp_pink
    or new.stamp_cink    is distinct from old.stamp_cink
    or new.stamp_seed    is distinct from old.stamp_seed
    or new.stamp_issued_at is distinct from old.stamp_issued_at
    or new.code          is distinct from old.code);

  -- The one shape of change that is allowed: the same statement takes the
  -- credit down by one.
  spends := old.stamp_redo > 0 and new.stamp_redo = old.stamp_redo - 1;

  if changed and not spends then
    raise exception 'a stamp cannot be changed once it is issued';
  end if;

  -- And a credit cannot be handed to yourself.
  if new.stamp_redo > old.stamp_redo
     and coalesce(current_setting('pw.grant_redo', true), '') <> '1' then
    raise exception 'a change has to be granted';
  end if;

  return new;
end $$;

-- The only way a credit is given. service_role only: anon must not reach it.
create or replace function grant_stamp_redo(uid text, n integer default 1)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare left_now integer;
begin
  perform set_config('pw.grant_redo', '1', true);
  update pilot_profiles p
     set stamp_redo = least(3, greatest(0, p.stamp_redo + greatest(0, n)))
   where p.user_id = uid
  returning p.stamp_redo into left_now;
  perform set_config('pw.grant_redo', '', true);
  return coalesce(left_now, 0);
end $$;

revoke all on function grant_stamp_redo(text, integer) from public, anon, authenticated;
grant execute on function grant_stamp_redo(text, integer) to service_role;

-- ------------------------------------------------------------ 4 · claim_code
create or replace function claim_code(uid text, want text)
returns text
language plpgsql
volatile
as $$
declare taken boolean;
begin
  if want is null or want !~ '^[A-Z0-9]{1,3}$' then
    return null;
  end if;

  -- An issued stamp carries its code. It moves only through issue_licence,
  -- and only by spending a change.
  if exists (select 1 from pilot_profiles p
              where p.user_id = uid and p.stamp_issued_at is not null
                and p.code is distinct from want) then
    return null;
  end if;

  select exists (
    select 1 from pilot_profiles p where p.code = want and p.user_id <> uid
  ) into taken;
  if taken then return null; end if;

  insert into pilot_profiles (user_id, code) values (uid, want)
  on conflict (user_id) do update set code = excluded.code;

  return want;
exception
  when unique_violation then return null;
end $$;

-- ------------------------------------------------------- 5 · issue_licence
-- 0036's ten-argument shape, which is the one the client calls. The seven
-- argument one from 0035 follows it, for a bundle deployed before this.
create or replace function issue_licence(
  uid text, p_code text, p_shape text, p_rim boolean,
  p_ring text, p_pattern text, p_ink text,
  p_pscope text, p_pink text, p_cink text)
returns pilot_profiles
language plpgsql
security definer
set search_path = public
as $$
declare
  want text;
  had  pilot_profiles;
  out_row pilot_profiles;
begin
  if uid is null or uid = '' then raise exception 'no pilot'; end if;

  want := upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'));
  if want !~ '^[A-Z0-9]{1,3}$' then
    raise exception 'a licence needs a code of one to three characters';
  end if;

  insert into pilot_profiles (user_id) values (uid)
  on conflict (user_id) do nothing;

  select * into had from pilot_profiles p where p.user_id = uid;

  -- Already issued? Then this is the one change, and only if it is owed.
  if had.stamp_issued_at is not null and coalesce(had.stamp_redo, 0) < 1 then
    raise exception 'that stamp is already issued';
  end if;

  if exists (select 1 from pilot_profiles p where p.code = want and p.user_id <> uid) then
    raise exception 'that code is taken';
  end if;

  update pilot_profiles p set
    code = want,
    stamp_code = want,
    stamp_shape = p_shape,
    stamp_rim = coalesce(p_rim, true),
    stamp_ring = nullif(left(upper(regexp_replace(coalesce(p_ring, ''), '[^A-Za-z0-9 .''-]', '', 'g')), 10), ''),
    stamp_pattern = coalesce(p_pattern, 'none'),
    stamp_pscope = coalesce(p_pscope, 'both'),
    stamp_ink = p_ink,
    stamp_pink = p_pink,
    stamp_cink = p_cink,
    stamp_seed = 1 + floor(random() * 999998)::int,
    stamp_issued_at = now(),
    -- The credit is spent in the SAME statement, which is what the trigger
    -- reads as permission. A first issue has none to spend and needs none.
    stamp_redo = case when had.stamp_issued_at is not null
                      then coalesce(p.stamp_redo, 0) - 1 else coalesce(p.stamp_redo, 0) end
  where p.user_id = uid
  returning p.* into out_row;

  return out_row;
exception
  when unique_violation then raise exception 'that code is taken';
end $$;

grant execute on function issue_licence(text, text, text, boolean, text, text, text, text, text, text) to anon, authenticated;

create or replace function issue_licence(
  uid text, p_code text, p_shape text, p_rim boolean,
  p_ring text, p_pattern text, p_ink text)
returns pilot_profiles
language plpgsql
security definer
set search_path = public
as $$
begin
  return issue_licence(uid, p_code, p_shape, p_rim, p_ring, p_pattern, p_ink, 'both', null, null);
end $$;

grant execute on function issue_licence(text, text, text, boolean, text, text, text) to anon, authenticated;

-- --------------------------------------------- 6 · the one change, to everyone
-- With the trigger off, because this statement is the first grant and the
-- rule it writes would refuse it. Two accounts have a stamp today; anybody
-- who issues one after this gets none, which is the rule going back on.
alter table pilot_profiles disable trigger pilot_stamp_permanent;
update pilot_profiles set stamp_redo = 1 where stamp_issued_at is not null and stamp_redo = 0;
alter table pilot_profiles enable trigger pilot_stamp_permanent;

-- ------------------------------------------------------------------ 7 · proof
do $$
declare n integer;
begin
  select count(*) into n from information_schema.columns
   where table_name = 'pilot_profiles' and column_name = 'stamp_redo';
  if n <> 1 then raise exception '0039: stamp_redo is missing'; end if;

  select count(*) into n from pg_constraint
   where conname = 'pilot_code_shape'
     and pg_get_constraintdef(oid) like '%{1,3}%';
  if n <> 1 then raise exception '0039: the code shape was not widened'; end if;
end $$;


-- ############################################################################
-- 0040_the_course_lives_in_a_table.sql
-- ############################################################################

-- =============================================================================
-- 0040 — THE COURSE LIVES IN A TABLE, AND ONLY AN EDITOR CAN CHANGE IT.
-- -----------------------------------------------------------------------------
-- The Studio (2026-09-30) let an admin write a chapter and hand back a file to
-- commit. The owner: "build it" — publish it for real. So the course document
-- gets a home the app can read at runtime, and the write side gets the one
-- thing the rest of this schema does not have: a gate.
--
-- WHY THIS TABLE IS DIFFERENT FROM EVERY OTHER TABLE HERE. 0009's header says
-- it plainly: `auth.uid()` is NULL on every request, the publishable key is
-- the bearer, and access control happens in the app — so every table is open
-- and the cost is stated. For student data that cost is a student's own rows.
-- For the COURSE it would be the syllabus: one person with the key in their
-- browser's network tab could empty every quiz for everybody. So:
--
--   · reads are open, because every visitor needs the course;
--   · there is NO insert, update or delete policy at all, which means RLS
--     refuses all three to anon and authenticated — not by choice of policy
--     but by absence of one;
--   · the only way in is `publish_course`, SECURITY DEFINER, which demands a
--     publishing key it never returns and only ever compares as a digest.
--
-- A KEY, NOT AN IDENTITY, and that is a deliberate limitation rather than an
-- oversight. There is no trusted identity to check: a uid passed as an
-- argument is a claim anybody can make, and every user id in this database is
-- readable with the publishable key (`saves`, `quiz_runs`). A shared secret
-- held by the people who publish is the strongest gate available without a
-- server of our own; the day there is one, this becomes a token check and the
-- table does not move. `course_editors` records who used it, so a publish is
-- never anonymous even though the key is shared.
--
-- NOTHING IS OVERWRITTEN. A publish inserts a version; the app reads the
-- newest. Rolling back is publishing an older document again, which is one
-- statement, and the history is the audit trail.
-- =============================================================================

create table if not exists course_docs (
  id           bigserial primary key,
  doc          jsonb       not null,
  note         text,
  published_by text,
  published_at timestamptz not null default now()
);

create index if not exists course_docs_newest on course_docs (published_at desc, id desc);

alter table course_docs enable row level security;

-- Reads, for everybody. This is the course.
drop policy if exists course_docs_read on course_docs;
create policy course_docs_read on course_docs for select using (true);

-- And deliberately no policy for insert, update or delete. RLS denies what no
-- policy allows, so the publishable key cannot write here at all.

-- The publishing key, as a digest. The plaintext is never stored and never
-- returned by anything in this file.
create table if not exists course_keys (
  id         smallint primary key default 1,
  digest     text        not null,
  set_at     timestamptz not null default now(),
  constraint course_keys_one_row check (id = 1)
);
alter table course_keys enable row level security;
-- No policies at all: the digest is not readable with the publishable key
-- either. Only SECURITY DEFINER functions, which run as the owner, see it.

/* pgcrypto is already installed on this project, in the `extensions` schema
   where Supabase puts them — which is why every function below sets
   `search_path = public, extensions`. Without the second entry `digest()` is
   simply not found, and the first run of this migration said so. */

/* Set or rotate the key. service_role only — this is run from a migration or
   the SQL console, never from a browser. */
create or replace function set_course_key(p_key text)
returns timestamptz
language plpgsql
security definer
set search_path = public, extensions
as $$
declare at timestamptz;
begin
  if p_key is null or length(p_key) < 16 then
    raise exception 'a publishing key is at least 16 characters';
  end if;
  insert into course_keys (id, digest, set_at)
       values (1, encode(digest(p_key, 'sha256'), 'hex'), now())
  on conflict (id) do update set digest = excluded.digest, set_at = now()
  returning course_keys.set_at into at;
  return at;
end $$;

revoke all on function set_course_key(text) from public, anon, authenticated;
grant execute on function set_course_key(text) to service_role;

/* THE COURSE, as the app reads it: the newest version, or nothing at all.
   Nothing is an answer — the app falls back to the document it shipped
   with, which is what keeps an empty table or a slow night from being a
   blank Library. */
create or replace function current_course()
returns table (id bigint, doc jsonb, note text, published_at timestamptz)
language sql
stable
security definer
set search_path = public
as $$
  select c.id, c.doc, c.note, c.published_at
    from course_docs c
   order by c.published_at desc, c.id desc
   limit 1
$$;

grant execute on function current_course() to anon, authenticated;

/* Publishing. The key is compared as a digest and never echoed; the document
   is checked for the shape the app cannot run without, so a typo cannot take
   the Library away from a class. */
create or replace function publish_course(p_doc jsonb, p_key text, p_note text default null, p_by text default null)
returns table (id bigint, published_at timestamptz)
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  want text;
  mods jsonb;
  n integer;
begin
  select k.digest into want from course_keys k where k.id = 1;
  if want is null then raise exception 'no publishing key is set'; end if;
  if p_key is null or encode(digest(p_key, 'sha256'), 'hex') <> want then
    raise exception 'that publishing key is not right';
  end if;

  if p_doc is null or jsonb_typeof(p_doc -> 'modules') <> 'array' then
    raise exception 'a course document has a modules array';
  end if;
  mods := p_doc -> 'modules';
  if jsonb_array_length(mods) = 0 then
    raise exception 'a course document has at least one module';
  end if;
  /* Every module needs an id and a name, and every chapter needs an id: the
     app keys progress, saves and stamps to those, so a document missing them
     is not a course, it is a way to lose somebody's work. */
  select count(*) into n from jsonb_array_elements(mods) m
   where coalesce(m ->> 'id', '') = '' or coalesce(m ->> 'name', '') = '';
  if n > 0 then raise exception '% module(s) without an id or a name', n; end if;
  select count(*) into n
    from jsonb_array_elements(mods) m,
         jsonb_array_elements(coalesce(m -> 'chapters', '[]'::jsonb)) c
   where coalesce(c ->> 'id', '') = '';
  if n > 0 then raise exception '% chapter(s) without an id', n; end if;

  return query
  insert into course_docs (doc, note, published_by)
       values (p_doc, nullif(btrim(coalesce(p_note, '')), ''), nullif(btrim(coalesce(p_by, '')), ''))
    returning course_docs.id, course_docs.published_at;
end $$;

grant execute on function publish_course(jsonb, text, text, text) to anon, authenticated;

-- ------------------------------------------------------------------ proof
do $$
declare n integer;
begin
  select count(*) into n from pg_policies where tablename = 'course_docs' and cmd <> 'SELECT';
  if n <> 0 then raise exception '0040: course_docs has % write policies; it must have none', n; end if;

  select count(*) into n from pg_proc p join pg_namespace ns on ns.oid = p.pronamespace
   where ns.nspname = 'public' and p.proname in ('publish_course', 'current_course', 'set_course_key');
  if n <> 3 then raise exception '0040: expected three functions, found %', n; end if;
end $$;


-- ############################################################################
-- 0041_search_finds_anybody.sql
-- ############################################################################

-- ===========================================================================
-- 0041 · A NAME FINDS ANYBODY, AND THE PEOPLE LIST IS CALLSIGNS
-- ===========================================================================
-- Owner, 2026-10-11, having searched for somebody he knows by name AND by
-- username and got nothing back: "disregard anything we decided earlier. This
-- is the new rule. You type the name of the person, or the username, and if it
-- is registered on a server, it will show their name. Think of like the
-- Instagram suggestions."
--
-- Then, 2026-10-12, on where that list lives and what it may show: "if you
-- select people, it shows every current person ... they are filtered in
-- alphabetical order ... we filter as per username ... you can only get the
-- name if you search it up. If you actually search for the name you get the
-- name, otherwise it only shows the username. If you press it you can see the
-- real name, but you don't get it just through looking at it."
--
-- THIS FILE HAS NOT BEEN RUN YET, which is why it is being rewritten rather
-- than followed by an 0042: the live database is still on 0032's
-- `people_search`. Once it HAS run, nothing here may be edited again — the
-- next change is a new file.
--
-- ---------------------------------------------------------------------------
-- WHY NOTHING CAME BACK, AND IT WAS NOT THE MATCHING
-- ---------------------------------------------------------------------------
-- The matching was already on both: 0012 matches `callsign` and `real_name`,
-- case-insensitively, as substrings. What refused the row was the SCOPE.
--
-- 0011 built `people_search` so that it "cannot return a stranger whatever it
-- is asked", through `in_my_orbit(p_me, p_them)` — true only if you share a
-- squadron, or they authored a thread in one of YOUR modules, or they replied
-- in one. `my_modules` is itself derived from `chapter_completions` and
-- `lesson_threads`, so a student who has not finished a chapter has no
-- modules, and for them orbit collapses to "shares a squadron with me".
--
-- So on a class this size the function was mostly answering "is this person
-- already in a room with me" — and the honest answer to a search for somebody
-- who has signed up, done nothing yet and joined nothing was an empty list.
-- The feature was not broken; it was scoped to something other than what it
-- says on the box.
--
-- THE ORBIT RULE IS WITHDRAWN FOR SEARCH. `in_my_orbit` is NOT dropped —
-- `discover_squadrons` (0011) still uses it to decide which faces it may show
-- on a room's card, which is a different question and still the right one.
--
-- ---------------------------------------------------------------------------
-- A LIST SHOWS CALLSIGNS. A NAME IS SOMETHING YOU ASKED FOR.
-- ---------------------------------------------------------------------------
-- This is the shape change, and it is a privacy rule rather than a layout
-- one, so it lives here rather than in the component that draws it.
--
--   `people_browse`  returns CALLSIGNS AND NO NAMES AT ALL. It is the list
--                    you scroll when you have not typed anything, so nobody
--                    can read a roster of real names off the side of the
--                    screen. There is no column for a name to arrive in.
--
--   `people_search`  returns the callsign always, and `real_name` ONLY on the
--                    rows whose name actually matched what you typed. Search
--                    "Hamdan" and Sara's name comes back, because you already
--                    knew it; search "SRH", or scroll the list, and it does
--                    not. The client cannot leak what it was never sent.
--
-- The third way in is the profile sheet, which is a deliberate press on one
-- person and has always shown the name. That is "if you press it you can see
-- the real name".
--
-- 0012'S IDENTITY RULE SURVIVES ON TOP OF THIS and is stricter: a student
-- whose `identity_display` is 'username' is never matched on `real_name` and
-- never has it returned, however it was asked for. They are still findable —
-- their callsign finds them — and that is the point of the two rules sitting
-- together rather than one replacing the other.
--
-- ---------------------------------------------------------------------------
-- WHAT IS KEPT
-- ---------------------------------------------------------------------------
--   Fly solo (`pilot_profiles.invisible`)  0032 exists to make "I am not
--       here" mean it on this surface. Untouched.
--   Blocks, both ways                      symmetric and total.
--   `discoverable`                         0011's separate "don't put me
--       forward". No screen sets it today, so it is `true` for every real
--       account and costs nothing to honour.
--   Never yourself. Orbit used to do this incidentally (`p_me <> p_them`);
--       it is explicit now, and `is distinct from` so a null searcher does
--       not silently empty the result.
--   A PROFILE WITH NO CALLSIGN IS NOT LISTED. Both functions require one,
--       because the list has nothing else to draw and a blank row is worse
--       than an absent one. FirstFlightGate sets the callsign when it makes a
--       profile and heals it for older accounts, so this excludes nobody in
--       practice; if it ever does, that profile is the bug.
-- ===========================================================================

-- THE RETURN TYPE CHANGES, so this is a drop and a create rather than a
-- replace: Postgres refuses to change a function's output columns in place
-- (0017's header has the same note, and 0012 dropped this very function for
-- the same reason). Dropping is safe here because the only caller is the app,
-- and the app ships with the client that matches.
drop function if exists people_search(text, text);

create function people_search(p_me text, p_q text)
returns table (
  user_id        text,
  callsign       text,       -- always; this is what a list may draw
  real_name      text,       -- ONLY when the term matched it, else null
  module_code    text,
  shares_squadron boolean
)
language sql
stable
as $$
  with q as (
    select t as term,
           /* the same text with LIKE's own wildcards neutralised */
           replace(replace(replace(t, '\', '\\'), '%', '\%'), '_', '\_') as esc
      from (select btrim(coalesce(p_q, '')) as t) r
  ),
  pool as (
    select
      p.user_id,
      p.callsign,
      /* The real name is matchable ONLY while they have not chosen
         otherwise. Null here means "do not match on this", and `ilike`
         against null is null, which is not true — so it never matches. */
      case when coalesce(up.identity_display, 'real') = 'username'
           then null else p.real_name end as findable_name,
      (select c.module_code from chapter_completions c
        where c.user_id = p.user_id order by c.completed_at desc limit 1) as module_code,
      exists (
        select 1 from squadron_members a
        join squadron_members b on b.squadron_id = a.squadron_id
        where a.user_id = p_me and b.user_id = p.user_id
      ) as shares_squadron
    from pilot_profiles p
    left join user_prefs up on up.user_id = p.user_id
    cross join q
    where q.term <> ''
      and p.user_id is distinct from p_me
      and coalesce(btrim(p.callsign), '') <> ''
      and p.discoverable
      and not coalesce(p.invisible, false)
      and not exists (select 1 from blocks b
                      where (b.user_id = p_me and b.blocked_id = p.user_id)
                         or (b.user_id = p.user_id and b.blocked_id = p_me))
  )
  select
    pool.user_id,
    pool.callsign,
    /* THE NAME ONLY TRAVELS WHEN THE NAME WAS ASKED FOR, and asking is
       stricter than matching.
       ------------------------------------------------------------------
       MATCHING stays a loose substring, so any fragment still FINDS people.
       DISCLOSURE does not: the term has to be at least three characters and
       has to start one of the words of the name.

       Without both halves the rule is worthless. A plain substring reveal
       hands back a name for "a", and measured on the fixture it handed back
       "Kai Lindqvist" for the two letters "KA" — somebody typing the start
       of a CALLSIGN was being given a real name. Three letters off the front
       of a word is what "actually searching for the name" means; one letter
       is harvesting.

       `escape '\'` because the term is a student's text: a bare `%` or `_`
       in it would otherwise be a wildcard and match far more than was
       typed. */
    case when length(q.term) >= 3 and pool.findable_name is not null
          and (lower(pool.findable_name) like lower(q.esc) || '%' escape '\'
            or lower(pool.findable_name) like '% ' || lower(q.esc) || '%' escape '\')
         then pool.findable_name else null end as real_name,
    pool.module_code,
    pool.shares_squadron
    from pool cross join q
   where pool.callsign ilike '%' || q.term || '%'
      or pool.findable_name ilike '%' || q.term || '%'
   /* What you typed comes first: exact, then starts-with, then merely
      contains; then somebody you share a squadron with; then by callsign,
      which is the order the browse list is in, so the two agree. */
   order by
     case
       when lower(pool.callsign) = lower(q.term)
         or lower(pool.findable_name) = lower(q.term) then 0
       when pool.callsign ilike q.term || '%'
         or pool.findable_name ilike q.term || '%' then 1
       else 2
     end,
     pool.shares_squadron desc,
     pool.callsign
   limit 40;
$$;


-- ===========================================================================
-- THE PEOPLE LIST
-- ===========================================================================
-- "If you select people, it shows every current person ... you can look up
-- the exact name, or you can just swipe through them."
--
-- Alphabetical BY CALLSIGN, because that is the only thing the list shows and
-- sorting by a name nobody can see would look arbitrary. No names, by
-- construction: there is no column for one.
--
-- AND NO COUNT, which is the rule from the first version of this and still
-- holds (owner, 2026-10-11: a directory "that doesn't expose if we have small
-- users"). It returns rows and nothing else — no total, and deliberately no
-- `count(*)` companion, because the moment one exists a screen will print it.
--
-- `p_since` is null by default, which is EVERYONE. It was a fortnight's
-- activity in the first draft; "every current person" is what was asked for,
-- and the window stays only as a knob for a class large enough to want one.
create or replace function people_browse(p_me text, p_since interval default null,
                                         p_limit integer default 400)
returns table (
  user_id        text,
  callsign       text,
  module_code    text,
  shares_squadron boolean
)
language sql
stable
as $$
  with acted as (
    select user_id, max(at) as at from (
      select pr.user_id, pr.last_seen    as at from presence pr
      union all
      select t.author_id, t.created_at   as at from lesson_threads t
      union all
      select r.author_id, r.created_at   as at from lesson_replies r
      union all
      select c.user_id, c.completed_at   as at from chapter_completions c
      union all
      select qr.user_id, qr.submitted_at as at from quiz_runs qr
       where qr.submitted_at is not null
    ) s
    group by user_id
  )
  select
    p.user_id,
    p.callsign,
    (select c.module_code from chapter_completions c
      where c.user_id = p.user_id order by c.completed_at desc limit 1) as module_code,
    exists (
      select 1 from squadron_members a
      join squadron_members b on b.squadron_id = a.squadron_id
      where a.user_id = p_me and b.user_id = p.user_id
    ) as shares_squadron
  from pilot_profiles p
  left join acted on acted.user_id = p.user_id
  where p.user_id is distinct from p_me
    and coalesce(btrim(p.callsign), '') <> ''
    and p.discoverable
    and not coalesce(p.invisible, false)
    and not exists (select 1 from blocks b
                    where (b.user_id = p_me and b.blocked_id = p.user_id)
                       or (b.user_id = p.user_id and b.blocked_id = p_me))
    /* Null window means everybody; a window asks for somebody who has done
       one of the five things inside it. */
    and (p_since is null or (acted.at is not null and acted.at >= now() - p_since))
  order by upper(p.callsign), p.user_id
  limit greatest(coalesce(p_limit, 400), 1);
$$;


do $$
declare n integer;
begin
  select count(*) into n from pg_proc
   where proname in ('people_search', 'people_browse')
     and pronamespace = 'public'::regnamespace;
  if n < 2 then
    raise exception '0041 did not take: expected people_search and people_browse, found %', n;
  end if;
end $$;


-- ############################################################################
-- 0042_a_paper_you_started.sql
-- ############################################################################

-- ===========================================================================
-- 0042 · ONE ANSWER COUNTS, AND EVERY ATTEMPT GETS ITS OWN STAMP
-- ===========================================================================
-- Owner, 2026-10-12: "if you open the exam and answer at least one question,
-- so you have progress, and leave it or submit it, whatever it is ... answer
-- one question, you stamp it, and if you complete it, you also get stamped."
-- And: "if you complete it more than once, you just get stamped twice ... we
-- will work towards something where an attempt that you have made shows a
-- different version, but as of right now, just stamp it twice."
--
-- ---------------------------------------------------------------------------
-- WHY NOT ON OPEN, WHICH IS WHAT WAS ASKED FOR FIRST
-- ---------------------------------------------------------------------------
-- A row already exists the moment a paper opens: `start_quiz_run` fires from
-- an effect in Exam.jsx, with `submitted_at` null. So "who opened this" has
-- been in the table all along and reading it would have been a one-line
-- change. It is deliberately NOT the rule.
--
-- Opening is free and repeatable, so a stamp on open is inflatable to the
-- point of noise — ten taps, ten rows — and it would have contradicted the
-- screen it sits on: a chapter quiz is an EXAM, nothing is marked before
-- hand-in, and `check:exam` asserts no mark reaches the question screen. The
-- end-exam dialog offers "Leave it for now" precisely so a mis-tap costs
-- nothing; stamping on open would have given that choice a permanent public
-- consequence, and the student likeliest to open and back out is a nervous
-- one. ONE ANSWER is the bar instead: it cannot be reached by accident, it
-- cannot be reached by curiosity, and it is reached long before a paper is
-- finished — which is the liveness the owner is actually after.
--
-- ---------------------------------------------------------------------------
-- LEAVING KEEPS YOUR PLACE, AND THAT WAS THE CONDITION
-- ---------------------------------------------------------------------------
-- "Note that leaving it should save your progress. Whenever you come back to
-- it, you are stopped at this exact time and at this exact question. So if we
-- can achieve that, then I think, yes, we stamp it."
--
-- It already does, and it was MEASURED rather than assumed before this
-- migration was written: answer two questions, step to the third, leave by
-- the arrow and "Leave it for now", wait, come back — question 3, 2 of 40
-- answered, and the clock 0 seconds further on than it was left. The attempt
-- carries `at` (which question is on screen) and `left` (seconds), and the
-- clock only moves while the paper is on screen (quiz.js §1).
--
-- THE ONE LIMIT, STATED RATHER THAN DISCOVERED: the attempt lives in
-- localStorage under `wingman.attempt.<quizId>` and is not mirrored anywhere.
-- Resume is therefore PER DEVICE. Leave a paper on a phone and open it on a
-- laptop and you get a fresh one, and the stamp this migration grants is the
-- only trace the first sitting leaves. Carrying the attempt to the server is
-- a separate piece of work and is not done here.
-- ===========================================================================

-- ------------------------------------------------- 1 · the progress stamp
-- Additive, nullable, and with the same shape of CHECK as `submitted_at`:
-- a run cannot have been answered before it was started.
alter table quiz_runs add column if not exists answered_at timestamptz;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'quiz_runs_answered_after_start') then
    alter table quiz_runs add constraint quiz_runs_answered_after_start
      check (answered_at is null or answered_at >= started_at);
  end if;
end $$;

create index if not exists quiz_runs_counted_idx
  on quiz_runs (quiz_id, user_id)
  where answered_at is not null or submitted_at is not null;

-- WRITTEN ONCE AND NEVER MOVED. The client calls this on the first answer of
-- a sitting and does not track whether it already has; `coalesce` makes a
-- second call a no-op rather than a lie about when the paper was started.
-- Scoped to the caller's own run, because every table here is readable with
-- the publishable key (0009) and "mark somebody else's paper as begun" is not
-- a thing this should allow.
create or replace function mark_quiz_progress(p_me text, p_run uuid)
returns timestamptz
language sql
volatile
as $$
  update quiz_runs
     set answered_at = coalesce(answered_at, now())
   where id = p_run and user_id = p_me
  returning answered_at;
$$;


-- ------------------------------------------- 2 · a stamp per ATTEMPT, not per person
-- 0038 grouped runs into PEOPLE (`max(submitted_at)`, one row each) so a
-- repeat kept its place on the board but not its stamp. The owner wants the
-- other thing for now: "if I attempt it twice, I get stamped" twice.
--
-- So this returns ONE ROW PER RUN. The de-duplication is gone from the server
-- rather than from the client, because the cap is applied here — a client
-- that expanded rows after a cap of eleven would be capping people and
-- drawing attempts, which is the bug 0038's own header warns about in the
-- other direction.
--
-- `run_id` is new and is what the client keys on. Without it two attempts by
-- one person collide on `user_id` in React and the second silently does not
-- render — which would have looked exactly like the de-duplication this
-- migration removes.
--
-- WHAT COUNTS: answered or submitted. An opened-and-abandoned paper with no
-- answer on it is not an attempt and never becomes one.
drop function if exists quiz_finishers(text, text[], integer);

create function quiz_finishers(uid text, p_quizzes text[], p_cap integer default 11)
returns table (
  quiz_id         text,
  run_id          uuid,
  user_id         text,
  callsign        text,
  code            text,
  finished_at     timestamptz,
  is_you          boolean,
  finishers       integer,
  stamp_shape     text,
  stamp_code      text,
  stamp_rim       boolean,
  stamp_ring      text,
  stamp_pattern   text,
  stamp_pscope    text,
  stamp_ink       text,
  stamp_pink      text,
  stamp_cink      text,
  stamp_seed      integer,
  stamp_issued_at timestamptz
)
language sql
stable
security definer
set search_path = public
as $$
  with visible as (
    select r.id, r.quiz_id, r.user_id,
           /* The moment the attempt began to count. A finished paper is
              dated by its hand-in; one still open is dated by its first
              answer, so the order reads as "most recently active". */
           coalesce(r.submitted_at, r.answered_at) as at
      from quiz_runs r
      join pilot_profiles p on p.user_id = r.user_id
     where r.quiz_id = any(coalesce(p_quizzes, array[]::text[]))
       and (r.answered_at is not null or r.submitted_at is not null)
       /* 0034's visibility rules, unchanged: Fly solo, and a block cutting
          both ways. You always see your own. */
       and (r.user_id = uid
            or (not coalesce(p.invisible, false)
                and not exists (select 1 from blocks b
                                where (b.user_id = uid and b.blocked_id = r.user_id)
                                   or (b.user_id = r.user_id and b.blocked_id = uid))))
  ),
  ranked as (
    select v.*,
           count(*) over (partition by v.quiz_id) as n,
           row_number() over (
             partition by v.quiz_id
             /* You first, then most recent — 0038's order, kept. */
             order by (v.user_id = uid) desc, v.at desc, v.id
           ) as rn
      from visible v
  )
  select r.quiz_id, r.id, r.user_id, p.callsign, p.code, r.at, r.user_id = uid,
         r.n::integer,
         p.stamp_shape, p.stamp_code, p.stamp_rim, p.stamp_ring, p.stamp_pattern,
         p.stamp_pscope, p.stamp_ink, p.stamp_pink, p.stamp_cink,
         p.stamp_seed, p.stamp_issued_at
    from ranked r
    join pilot_profiles p on p.user_id = r.user_id
   where r.rn <= greatest(1, least(coalesce(p_cap, 11), 400))
   order by r.quiz_id, r.rn;
$$;


do $$
declare n integer;
begin
  select count(*) into n from pg_proc
   where proname in ('quiz_finishers', 'mark_quiz_progress')
     and pronamespace = 'public'::regnamespace;
  if n < 2 then
    raise exception '0042 did not take: expected quiz_finishers and mark_quiz_progress, found %', n;
  end if;
  if not exists (select 1 from information_schema.columns
                  where table_name = 'quiz_runs' and column_name = 'answered_at') then
    raise exception '0042 did not take: quiz_runs.answered_at is missing';
  end if;
end $$;


-- ############################################################################
-- 0043_a_face_and_a_mark.sql
-- ############################################################################

-- ===========================================================================
-- 0043 · THE PEOPLE LIST CARRIES A STAMP, AND SORTS ITS OWN STRAGGLERS LAST
-- ===========================================================================
-- Owner, 2026-10-12, on the People list: "the stamp is the identity so i want
-- that integrated too", and then "keep the profile but also add the stamp near
-- the name"; and of the A/B/C headers, "it doesnt have to show it just do it
-- quietly theyll understand".
--
-- ---------------------------------------------------------------------------
-- 1 · THE STAMP COLUMNS
-- ---------------------------------------------------------------------------
-- 0041's two functions return a callsign and nothing else about the person, so
-- the rail drew a coloured initial — a hash of the user id, which identifies
-- nobody. A stamp is what a student actually signs with, and it is already on
-- the quiz row and the leaderboard through `quiz_finishers`. Same eleven
-- columns here, in the same order, so the client shapes them for `stampOf`
-- exactly as board.js already does and the app keeps ONE stamp renderer.
--
-- Somebody who has not issued one comes back with nulls and is drawn as the
-- un-inked outline — the licence's own "not yet" mark. That is deliberate:
-- the one place students look at each other is the place where a missing
-- stamp is worth noticing.
--
-- NO REAL NAME COMES WITH THIS. `people_browse` still has no column for one,
-- and `people_search` still returns one only when the name was asked for
-- (0041). A stamp is a mark the student made for everybody to see; a name is
-- not, and widening one is not an excuse to widen the other.
--
-- ---------------------------------------------------------------------------
-- 2 · AND THE ORDER HAS TO CARRY WHAT THE HEADERS WERE CARRYING
-- ---------------------------------------------------------------------------
-- The list was grouped under A, B, C … with a "#" bucket at the end, and
-- `byLetter` in roomModel.js put anything not starting with a letter into it.
-- The headers are gone now — a sorted list does not need to announce that it
-- is sorted, and on a class of five they were five dividers for five people.
--
-- BUT ONE THING THOSE HEADERS WERE DOING WAS REAL: `_vnx` belongs at the END,
-- and 0041's `order by upper(callsign)` puts it FIRST, because the database
-- collation sorts punctuation before letters. Measured on the live list, not
-- assumed. Dropping the grouping without moving that rule would have silently
-- reordered the screen.
--
-- So it moves into the SQL, where the rest of the order already lives. The
-- client formats and does not sort — the same division as the leaderboard,
-- and `check:people` asserts it by refusing a `.sort(` in the people block.
-- ===========================================================================

-- Both return types change, so both are a drop and a create. 0041's bodies
-- are carried over unchanged except where this file says otherwise.
drop function if exists people_search(text, text);
drop function if exists people_browse(text, interval, integer);

create function people_search(p_me text, p_q text)
returns table (
  user_id        text,
  callsign       text,
  real_name      text,       -- ONLY when the term matched it (0041)
  module_code    text,
  shares_squadron boolean,
  stamp_shape     text,
  stamp_code      text,
  stamp_rim       boolean,
  stamp_ring      text,
  stamp_pattern   text,
  stamp_pscope    text,
  stamp_ink       text,
  stamp_pink      text,
  stamp_cink      text,
  stamp_seed      integer,
  stamp_issued_at timestamptz
)
language sql
stable
as $$
  with q as (
    select t as term,
           replace(replace(replace(t, '\', '\\'), '%', '\%'), '_', '\_') as esc
      from (select btrim(coalesce(p_q, '')) as t) r
  ),
  pool as (
    select
      p.user_id,
      p.callsign,
      case when coalesce(up.identity_display, 'real') = 'username'
           then null else p.real_name end as findable_name,
      (select c.module_code from chapter_completions c
        where c.user_id = p.user_id order by c.completed_at desc limit 1) as module_code,
      exists (
        select 1 from squadron_members a
        join squadron_members b on b.squadron_id = a.squadron_id
        where a.user_id = p_me and b.user_id = p.user_id
      ) as shares_squadron,
      p.stamp_shape, p.stamp_code, p.stamp_rim, p.stamp_ring, p.stamp_pattern,
      p.stamp_pscope, p.stamp_ink, p.stamp_pink, p.stamp_cink,
      p.stamp_seed, p.stamp_issued_at
    from pilot_profiles p
    left join user_prefs up on up.user_id = p.user_id
    cross join q
    where q.term <> ''
      and p.user_id is distinct from p_me
      and coalesce(btrim(p.callsign), '') <> ''
      and p.discoverable
      and not coalesce(p.invisible, false)
      and not exists (select 1 from blocks b
                      where (b.user_id = p_me and b.blocked_id = p.user_id)
                         or (b.user_id = p.user_id and b.blocked_id = p_me))
  )
  select
    pool.user_id,
    pool.callsign,
    /* Disclosure is stricter than matching: three characters or more that
       START a word of the name. A plain substring reveal handed a real name
       back for two letters of somebody's CALLSIGN (0041). */
    case when length(q.term) >= 3 and pool.findable_name is not null
          and (lower(pool.findable_name) like lower(q.esc) || '%' escape '\'
            or lower(pool.findable_name) like '% ' || lower(q.esc) || '%' escape '\')
         then pool.findable_name else null end as real_name,
    pool.module_code,
    pool.shares_squadron,
    pool.stamp_shape, pool.stamp_code, pool.stamp_rim, pool.stamp_ring, pool.stamp_pattern,
    pool.stamp_pscope, pool.stamp_ink, pool.stamp_pink, pool.stamp_cink,
    pool.stamp_seed, pool.stamp_issued_at
    from pool cross join q
   where pool.callsign ilike '%' || q.term || '%'
      or pool.findable_name ilike '%' || q.term || '%'
   order by
     case
       when lower(pool.callsign) = lower(q.term)
         or lower(pool.findable_name) = lower(q.term) then 0
       when pool.callsign ilike q.term || '%'
         or pool.findable_name ilike q.term || '%' then 1
       else 2
     end,
     pool.shares_squadron desc,
     /* Same straggler rule as the browse list, so a search result and the
        list it came out of do not disagree about where `_vnx` sits. */
     case when upper(pool.callsign) ~ '^[A-Z]' then 0 else 1 end,
     upper(pool.callsign)
   limit 40;
$$;


create function people_browse(p_me text, p_since interval default null,
                              p_limit integer default 400)
returns table (
  user_id        text,
  callsign       text,
  module_code    text,
  shares_squadron boolean,
  stamp_shape     text,
  stamp_code      text,
  stamp_rim       boolean,
  stamp_ring      text,
  stamp_pattern   text,
  stamp_pscope    text,
  stamp_ink       text,
  stamp_pink      text,
  stamp_cink      text,
  stamp_seed      integer,
  stamp_issued_at timestamptz
)
language sql
stable
as $$
  with acted as (
    select user_id, max(at) as at from (
      select pr.user_id, pr.last_seen    as at from presence pr
      union all
      select t.author_id, t.created_at   as at from lesson_threads t
      union all
      select r.author_id, r.created_at   as at from lesson_replies r
      union all
      select c.user_id, c.completed_at   as at from chapter_completions c
      union all
      select qr.user_id, qr.submitted_at as at from quiz_runs qr
       where qr.submitted_at is not null
    ) s
    group by user_id
  )
  select
    p.user_id,
    p.callsign,
    (select c.module_code from chapter_completions c
      where c.user_id = p.user_id order by c.completed_at desc limit 1) as module_code,
    exists (
      select 1 from squadron_members a
      join squadron_members b on b.squadron_id = a.squadron_id
      where a.user_id = p_me and b.user_id = p.user_id
    ) as shares_squadron,
    p.stamp_shape, p.stamp_code, p.stamp_rim, p.stamp_ring, p.stamp_pattern,
    p.stamp_pscope, p.stamp_ink, p.stamp_pink, p.stamp_cink,
    p.stamp_seed, p.stamp_issued_at
  from pilot_profiles p
  left join acted on acted.user_id = p.user_id
  where p.user_id is distinct from p_me
    and coalesce(btrim(p.callsign), '') <> ''
    and p.discoverable
    and not coalesce(p.invisible, false)
    and not exists (select 1 from blocks b
                    where (b.user_id = p_me and b.blocked_id = p.user_id)
                       or (b.user_id = p.user_id and b.blocked_id = p_me))
    and (p_since is null or (acted.at is not null and acted.at >= now() - p_since))
  /* A TO Z, AND ANYTHING THAT IS NOT A LETTER LAST. The grouping that used to
     do this in the client is gone; the collation alone would put `_vnx`
     first. */
  order by case when upper(p.callsign) ~ '^[A-Z]' then 0 else 1 end,
           upper(p.callsign), p.user_id
  limit greatest(coalesce(p_limit, 400), 1);
$$;


do $$
declare n integer;
begin
  select count(*) into n from pg_proc
   where proname in ('people_search', 'people_browse')
     and pronamespace = 'public'::regnamespace;
  if n <> 2 then
    raise exception '0043 did not take: expected 2 functions, found %', n;
  end if;
end $$;
